        self.record_debug.set(self.settings.record_debug)
        self.record_minimum_duration.set(self.settings.record_minimum_duration)
        self.record_min_free_gb.set(self.settings.record_min_free_gb)
        self.record_max_disk_usage_percent.set(self.settings.record_max_disk_usage_percent)
        self.record_variable_command.set(self.settings.record_variable_command)
        self.record_variable_name.set(self.settings.record_variable_name)
        self.record_variable_start.set(self.settings.record_variable_start)
        self.record_variable_stop.set(self.settings.record_variable_stop)
        self.area_capture_roi.set(self.settings.area_capture_roi)
        self.area_capture_output_target.set(self.settings.area_capture_output_target)
        self.area_capture_background.set(self.settings.area_capture_background)
        self.area_capture_active.set(self.settings.area_capture_active)
        self.area_capture_detection_scope.set(self.settings.area_capture_detection_scope)
        self.area_capture_detection_output.set(self.settings.area_capture_detection_output)
        self.area_capture_detection_roi.set(self.settings.area_capture_detection_roi)
        self.area_capture_detection_threshold.set(self.settings.area_capture_detection_threshold)
        self.area_capture_detection_gray.set(self.settings.area_capture_detection_gray)
        self.area_capture_match_color.set(self.settings.area_capture_match_color)
        self.area_capture_no_match_color.set(self.settings.area_capture_no_match_color)
        self.command_watch_enabled.set(self.settings.command_watch_enabled)
        self.command_watch_command.set(self.settings.command_watch_command)
        self.command_watch_target.set(self.settings.command_watch_target)
        self.command_watch_variables = [name for name in self.settings.command_watch_variables.split(",") if name]
        self.command_watch_list.delete(0, "end")
        for name in self.command_watch_variables:
            self.command_watch_list.insert("end", name)
        try:
            self.record_trigger_rules = json.loads(self.settings.record_trigger_rules)
            self.record_cleanup_rules = json.loads(self.settings.record_cleanup_rules)
            self.record_variable_rules = json.loads(self.settings.record_variable_rules)
        except (TypeError, ValueError):
            self.record_trigger_rules, self.record_cleanup_rules, self.record_variable_rules = [], [], []
        self.commands_assist_enabled.set(self.settings.commands_assist_enabled)
        self.commands_assist_recovery_command.set(self.settings.commands_assist_recovery_command)
        try:
            self.commands_assist_rules = json.loads(self.settings.commands_assist_rules)
        except (TypeError, ValueError):
            self.commands_assist_rules = []
        self.step_debug_rules = self._read_step_debug_rules()
        self._pending_profile_step_debug_rules = json.loads(
            json.dumps(self.step_debug_rules, ensure_ascii=False))
        self._refresh_commands_assist_rule_list()
        self.configure_recording_rules()
        self.refresh_recording_presets()
        self.refresh_operation_sessions()
        # Profile path is final now.  Prompt before camera/serial objects are
        # created so no device is opened with the previous profile's values.
        self.refresh_input_sets()
        self._startup_combined_item = self._prompt_startup_input_set()
        self._startup_input_item = None
        self._startup_effective_snapshot = {}
        if self._startup_combined_item:
            startup_input_name = str(self._startup_combined_item.get("input_set", ""))
            self._set_active_input_set(
                startup_input_name, self._startup_selected_combined_name)
            self.input_set_name.set(startup_input_name)
            startup_data = self._read_input_sets()
            self._startup_input_item = startup_data["input_sets"].get(startup_input_name)
            top_assist = self._startup_input_item.get("commands_assist", {}) \
                if isinstance(self._startup_input_item, dict) else {}
            tab_assist = self._startup_input_item.get("all_tabs", {}).get("commands_assist", {}) \
                if has_complete_snapshot(self._startup_input_item) else {}
            stored_step_rules = tab_assist.get("step_debug_rules") \
                if isinstance(tab_assist.get("step_debug_rules"), list) \
                else top_assist.get("step_debug_rules")
            # One-time migration from the former profile-global file.  It is
            # performed before InputSet application so an empty snapshot can
            # never erase an existing adjustment draft.
            startup_uses_commands = input_set_commands_enabled(
                self._startup_input_item)
            if (startup_uses_commands and not isinstance(stored_step_rules, list)
                    and self.step_debug_rules):
                if sync_step_debug_rules(startup_data, startup_input_name, self.step_debug_rules):
                    self._write_input_sets(startup_data)
                    self._startup_input_item = startup_data["input_sets"].get(startup_input_name)
            self._pending_profile_step_debug_rules = []
            if has_complete_snapshot(self._startup_input_item):
                self._startup_effective_snapshot = json.loads(json.dumps(
                    self._startup_input_item.get("all_tabs", {}), ensure_ascii=False))
                self._startup_effective_snapshot["commands_enabled"] = startup_uses_commands
                if not startup_uses_commands:
                    self._startup_effective_snapshot = strip_commands_from_snapshot(
                        self._startup_effective_snapshot)
            else:
                # Legacy combinations owned the non-device tab settings and a
                # separate Recording preset.  Preserve that only for old data.
                preset = self._read_recording_presets().get(
                    self._startup_combined_item.get("recording_set", ""))
                if preset:
                    self._apply_recording_preset_data(preset)
                self._startup_effective_snapshot = legacy_combined_snapshot(
                    self._startup_input_item, self._startup_combined_item)
            self._apply_all_tabs_snapshot(
                self._startup_effective_snapshot, runtime=False,
                commands_enabled=startup_uses_commands)
        if self.record_template_path.get():
            self.recorder.configure_template(self.record_template_path.get())
        self.apply_panel_assignment()
        self.refresh_presets()
        self.refresh_others_presets()

        # Shortcutボタンに名称とtooltipを設定する
        self.shortcut_1.set(self.shortcut_command_name[1][:8])
        self.shortcut_2.set(self.shortcut_command_name[2][:8])
        self.shortcut_3.set(self.shortcut_command_name[3][:8])
        self.shortcut_4.set(self.shortcut_command_name[4][:8])
        self.shortcut_5.set(self.shortcut_command_name[5][:8])
        self.shortcut_6.set(self.shortcut_command_name[6][:8])
        self.shortcut_7.set(self.shortcut_command_name[7][:8])
        self.shortcut_8.set(self.shortcut_command_name[8][:8])
        self.shortcut_9.set(self.shortcut_command_name[9][:8])
        self.shortcut_10.set(self.shortcut_command_name[10][:8])
        self.shortcut_button_1_tooltip = ToolTip(self.shortcut_button_1, self.shortcut_command_name[1])
        self.shortcut_button_2_tooltip = ToolTip(self.shortcut_button_2, self.shortcut_command_name[2])
        self.shortcut_button_3_tooltip = ToolTip(self.shortcut_button_3, self.shortcut_command_name[3])
        self.shortcut_button_4_tooltip = ToolTip(self.shortcut_button_4, self.shortcut_command_name[4])
        self.shortcut_button_5_tooltip = ToolTip(self.shortcut_button_5, self.shortcut_command_name[5])
        self.shortcut_button_6_tooltip = ToolTip(self.shortcut_button_6, self.shortcut_command_name[6])
        self.shortcut_button_7_tooltip = ToolTip(self.shortcut_button_7, self.shortcut_command_name[7])
        self.shortcut_button_8_tooltip = ToolTip(self.shortcut_button_8, self.shortcut_command_name[8])
        self.shortcut_button_9_tooltip = ToolTip(self.shortcut_button_9, self.shortcut_command_name[9])
        self.shortcut_button_10_tooltip = ToolTip(self.shortcut_button_10, self.shortcut_command_name[10])

        # self.shortcut_button_1["text"] = self.settings.command_name_1
        # 各コンボボックスを現在の設定値に合わせて表示
        self.fps_cb.current(self.fps_cb["values"].index(self.fps.get()))
        self.show_size_cb.current(self.show_size_cb["values"].index(self.show_size.get()))

        # 類似度の表示機能を反映する
        self.mode_change_show_value()

        # ガイドの表示機能を反映する
        self.mode_change_show_guide()

        # 標準出力をログにリダイレクト
        self.switchStdoutDestination()

        # Notificationの設定を反映する
        self.mode_change_notification()

        # ダイアログのOK/NGのボタンの位置を設定する
        self.change_buttons_position()

        if platform.system() == "Windows" or platform.system() == "Darwin":
            try:
                self.locateCameraCmbbox()
                self.camera_name_cb.config(state="readonly")
                self.camera_id_entry.config(state="disable")
            except Exception as e:
                self._logger.warning("An error occurred when displaying the camera name in the Win/Mac environment.")
                self._logger.warning(e)
                # DirectShow enumeration can succeed before a later selection
                # step fails.  Do not disable a usable list in that case.
                if getattr(self, "camera_dic", None):
                    self.camera_name_cb.config(state="readonly")
                    self.camera_id_entry.config(state="disable")
                else:
                    self.camera_name_fromDLL.set(
                        "An error occurred when displaying the camera name in the Win/Mac environment."
                    )
                    self.camera_name_cb.config(state="disable")
                    self.camera_id_entry.config(state="normal")
            try:
                self.locateDeviceCmbbox()
                self.set_init_device_name()
            except Exception as e:
                self._logger.warning("An error occurred when checking serial device list.")
                self._logger.warning(e)
        elif platform.system() == "Linux":
            self.camera_name_fromDLL.set("Linux environment. So that cannot show Camera name.")
            self.camera_name_cb.config(state="disable")
            self.camera_id_entry.config(state="normal")
        else:
            self.camera_name_fromDLL.set("Unknown environment. Cannot show Camera name.")
            self.camera_name_cb.config(state="disable")
            self.camera_id_entry.config(state="normal")
        if self._startup_combined_item:
            startup_snapshot = self._startup_effective_snapshot
            serial_override = (startup_snapshot.get("serial")
                               if isinstance(startup_snapshot, dict) else None)
            input_item = self._startup_input_item
            if input_item:
                self._apply_input_set_data(
                    input_item, open_hardware=False,
                    apply_serial=not isinstance(serial_override, dict))
            if isinstance(serial_override, dict) and not self._startup_skip_hardware:
                # Schema 3 stores the Serial identity inside the InputSet's
                # complete snapshot. Sender is created later by the worker.
                self._apply_serial_input_set(serial_override)
        if self._startup_skip_hardware:
            self._apply_hardware_unconfigured_selection()
        # open up a camera
        self.camera = Camera(self.fps.get())
        self.refresh_window_sources()
        # activate serial communication
        try:
            self.locateDeviceCmbbox()
            self.set_init_device_name()
        except Exception:
            self.serial_device_name_label.destroy()
            self.serial_device_name_cb.destroy()
            self.scan_device_button.destroy()
            self.com_port_entry["state"] = "normal"

        if platform.system() == "Windows" or platform.system() == "Darwin":
            pass
        else:
            self.com_port_entry["state"] = "normal"

        self.ser = Sender.Sender(self.is_show_serial)
        self.ser.set_activity_callback(self._record_command_key_activity)
        # Opening a USB serial driver can block.  KeyPress may safely hold a
        # closed Sender until the background startup connection completes.
        self.keyPress = KeyPress(self.ser)
        self.activateKeyboard()
        self.preview = CaptureArea(
            self.camera,
            self.fps.get(),
            self.serial_data_format_name.get(),
            self.is_show_realtime,
            #    self.ser,
            KeyPress(self.ser, priority=True),
            self.camera_lf,
            *list(map(int, self.show_size.get().split("x"))),
        )
        self.preview.config(cursor="crosshair")
        self.preview.grid(column="0", columnspan="7", row="2", padx="5", pady="5", sticky=tk.NSEW)
        self.preview.setTouchscreenArea(
            self.touchscreen_start_x, self.touchscreen_start_y, self.touchscreen_end_x, self.touchscreen_end_y
        )
        self.preview.set_region_listener(self.receive_output_region)
        self.preview.set_frame_listener(self.analyse_live_frame)
        self.preview.set_frame_work_provider(self._live_frame_analysis_active)
        self.preview.set_record_listener(self.process_recording_frame)
        self.preview.set_presentation_listener(
            self.process_presented_recording_frame)
        self.preview.set_render_priority_provider(self._preview_render_priority)
        self.preview.set_capture_work_provider(self._preview_capture_work_active)
        self.preview.set_resource_multiplier_provider(
            self._resource_preview_multiplier)
        self.preview.setFeatureLimited(self.camera_feature_limited.get())
        self.image_analysis_assist = ImageAnalysisAssist(
            os.path.dirname(os.path.abspath(__file__)), self._queue_image_assist_results,
            max_candidates=self.image_assist_max_candidates.get())
        self.analysis_rule_engine = AnalysisRuleEngine(self._queue_analysis_rule_results)
        self.toggle_image_analysis_assist()
        self.toggle_pc_gamepad_input()
        self.root.after(1000, self.preview_area_capture)
        self.root.after(50, self._drain_gui_actions)
        # Audio devices have now been enumerated and the GUI is ready.  Use
        # an idle callback so an unavailable device never delays startup.
        self.root.after(700, self.start_audio_on_launch)
        self._pending_startup_snapshot = (
            self._startup_effective_snapshot if self._startup_combined_item else None)
        self._start_load_commands_async()

        # キャンバスに自動化スクリプトからアクセスできるようにする。
        Command.canvas = self.preview
        Command.output = self.show_output
        Command.text_output = self._queue_command_text_output
        Command.image_detection_event = self.receive_image_detection_event

        self.show_size_tmp = self.show_size_cb["values"].index(self.show_size_cb.get())
        self.root.bind("<Key-F5>", self.ReloadCommandWithF5)
        self._logger.debug("Bind F5 key to reload commands")
        self.root.bind("<Key-F6>", self.StartCommandWithF6)
        self._logger.debug("Bind F6 key to execute commands")
        self.root.bind("<Key-Escape>", self.StopCommandWithEsc)
        self._logger.debug("Bind Escape key to stop commands")

        # self.keys_software_controller = UnitCommand
        self.keys_software_controller = KeyPress(self.ser, priority=True)
        # A queued item is only a version number for a complete state
        # snapshot.  Old mouse-motion versions have no value once a newer
        # state exists, so never let them accumulate behind serial I/O.
        self._software_controller_queue = queue.Queue(maxsize=1)
        self._software_controller_state = SoftwareControllerState()
        self._software_controller_paused_command = None
        self._software_controller_override_active = False
        self._software_controller_thread = threading.Thread(
            target=self._software_controller_loop, daemon=True, name="SoftwareControllerSender")
        self._software_controller_thread.start()

