    def sendLineImage(self):
        def sendMessage(src):
            Line = Line_Notify()
            Line.send_message("---Manual---", src, "token")

        src = self.camera.readFrame()
        thread = threading.Thread(target=sendMessage, args=(src,))
        thread.start()

    def sendDiscordImage(self):
        def sendMessage(src):
            Discord = Discord_Notify()
            Discord.send_message(notification_message="---Manual---", image=src)

        src = self.camera.readFrame()
        thread = threading.Thread(target=sendMessage, args=(src,))
        thread.start()

    def OpenCommandDir(self):
        selected_tab = self.command_nb.tab(self.command_nb.select(), "text")
        if selected_tab == "Mcu Command":
            directory = os.path.join("Commands", "McuCommands")
        elif selected_tab == "Python Sample Command":
            directory = os.path.join(dirname(dirname(abspath(__file__))), "DevStudio", "SampleCommands")
        else:
            directory = os.path.join("Commands", "PythonCommands")
        self._logger.debug(f"Open folder: '{directory}'")
        if platform.system() == "Windows":
            subprocess.call(f'explorer "{directory}"')
        elif platform.system() == "Darwin":
            command = f'open "{directory}"'
            subprocess.run(command, shell=True)

    def _create_scrollable_tab(self):
        """Create a notebook page whose lightweight content scrolls vertically."""
        page = ttk.Frame(self.controller_nb)
        background = ttk.Style().lookup("TFrame", "background") or self.root.cget("background")
        canvas = tk.Canvas(page, highlightthickness=0, borderwidth=0, background=background)
        scrollbar = ttk.Scrollbar(page, orient="vertical", command=canvas.yview)
        canvas.configure(yscrollcommand=scrollbar.set)
        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")
        content = ttk.Frame(canvas)
        window_id = canvas.create_window((0, 0), window=content, anchor="nw")

        def update_scrollregion(event=None):
            canvas.configure(scrollregion=canvas.bbox("all"))

        def resize_content(event):
            canvas.itemconfigure(window_id, width=max(1, event.width))

        content.bind("<Configure>", update_scrollregion)
        canvas.bind("<Configure>", resize_content)
        self._tab_scroll_canvases.append(canvas)
        return page, content

    def _scroll_tabs_with_wheel(self, event):
        """Scroll only the tab canvas currently below the mouse pointer."""
        pointer_x, pointer_y = self.root.winfo_pointerx(), self.root.winfo_pointery()
        for canvas in self._tab_scroll_canvases:
            try:
                if not canvas.winfo_ismapped():
                    continue
                inside = (canvas.winfo_rootx() <= pointer_x < canvas.winfo_rootx() + canvas.winfo_width() and
                          canvas.winfo_rooty() <= pointer_y < canvas.winfo_rooty() + canvas.winfo_height())
                if not inside:
                    continue
                bounds = canvas.bbox("all")
                if not bounds or bounds[3] - bounds[1] <= canvas.winfo_height():
                    return
                delta = getattr(event, "delta", 0)
                steps = -int(delta / 120) if abs(delta) >= 120 else (-1 if delta > 0 else 1)
                canvas.yview_scroll(steps, "units")
                return "break"
            except tk.TclError:
                continue

    def _update_others_scrollregion(self, event=None):
        self.others_canvas.configure(scrollregion=self.others_canvas.bbox("all"))

    def _resize_others_content(self, event):
        self.others_canvas.itemconfigure(self.others_canvas_window, width=max(1, event.width))

    def _scroll_others_with_wheel(self, event):
        canvas = getattr(self, "others_canvas", None)
        if canvas is None or not canvas.winfo_exists():
            return
        x, y = self.root.winfo_pointerx(), self.root.winfo_pointery()
        if not (canvas.winfo_rootx() <= x < canvas.winfo_rootx() + canvas.winfo_width() and
                canvas.winfo_rooty() <= y < canvas.winfo_rooty() + canvas.winfo_height()):
            return
        canvas.yview_scroll(-1 if event.delta > 0 else 1, "units")
        return "break"

    def _update_input_set_scrollregion(self, event=None):
        canvas = getattr(self, "input_set_canvas", None)
        if canvas is not None and canvas.winfo_exists():
            canvas.configure(scrollregion=canvas.bbox("all"))

    def _reorder_controller_tabs(self):
        """Keep the frequently used tabs in the requested fixed order."""
        ordered = [
             (self.input_set_f, "InputSet"), (self.camera_tab, "Camera"),
             (self.resource_tab, "Resource"),
             (self.audio_tab, "Audio"), (self.recording_tab, "Recording"),
             (self.serial_tab, "Serial"), (self.manual_control_tab, "Manual Control"),
             (self.area_capture_tab, "Area Capture"), (self.commands_tab, "Commands"),
             (self.commands_assist_tab, "CommandsAssist"),
             (self.operation_capture_tab, "操作記録→Commands"),
             (self.image_detection_monitor_tab, "Image Detection"),
            (self.analysis_tab, "Analysis"),
            (self.object_detection_tab, "Object Detection"),
            (self.command_watch_tab, "Command Watch"),
            (self.execution_path_tab, "実行経路"),
            (self.notification_tab, "Notification"), (self.others_tab, "Others"),
        ]
        # Presets are superseded by the all-tab snapshot stored in InputSet.
        if str(self.presets_tab) in self.controller_nb.tabs():
            self.controller_nb.forget(self.presets_tab)
        limited_tabs = set(self._feature_limited_hidden_tabs()) \
            if hasattr(self, "camera_feature_limited") \
            and self.camera_feature_limited.get() else set()
        for index, (widget, label) in enumerate(ordered):
            if widget in limited_tabs:
                try:
                    self.controller_nb.hide(widget)
                except tk.TclError:
                    pass
                continue
            try:
                # add() makes a previously hidden tab visible again.
                self.controller_nb.add(widget)
            except tk.TclError:
                pass
            self.controller_nb.insert(index, widget, text=label, padding="5", sticky="nsew")

    def _feature_limited_hidden_tabs(self):
        return tuple(
            tab for tab in (
                getattr(self, "area_capture_tab", None),
                getattr(self, "commands_tab", None),
                getattr(self, "commands_assist_tab", None),
                getattr(self, "operation_capture_tab", None),
                getattr(self, "image_detection_monitor_tab", None),
                getattr(self, "analysis_tab", None),
                getattr(self, "object_detection_tab", None),
                getattr(self, "command_watch_tab", None),
                getattr(self, "execution_path_tab", None),
            ) if tab is not None)

    def _apply_camera_feature_limited(self, notify=False):
        limited = bool(self.camera_feature_limited.get())
        limited_tabs = self._feature_limited_hidden_tabs()
        if limited:
            selected = self.controller_nb.select()
            if selected and any(str(tab) == selected for tab in limited_tabs):
                self.controller_nb.select(self.camera_tab)
            for tab in limited_tabs:
                try:
                    self.controller_nb.hide(tab)
                except tk.TclError:
                    pass
            if hasattr(self, "recording_mode_tabs"):
                try:
                    if self.recording_mode_tabs.select() == str(
                            self.recording_monitor_page):
                        self.recording_mode_tabs.select(
                            self.recording_normal_page)
                    self.recording_mode_tabs.hide(
                        self.recording_monitor_page)
                except tk.TclError:
                    pass
            if hasattr(self, "top_command_f"):
                self.top_command_f.grid_remove()
            if hasattr(self, "input_set_include_commands"):
                self.input_set_include_commands.set(False)
                self._toggle_input_set_commands()
            if hasattr(self, "record_debug"):
                self.record_debug.set(False)
            for variable_name in (
                    "is_show_value", "is_show_guide", "image_assist_enabled",
                    "analysis_rules_enabled", "image_detection_monitor_enabled",
                    "area_capture_active"):
                variable = getattr(self, variable_name, None)
                if hasattr(variable, "set"):
                    variable.set(False)
            if hasattr(self, "record_mode") \
                    and self.record_mode.get() == "CommandMonitor":
                self.record_mode.set("Manual")
            self.camera_feature_limited_status.set(
                "機能制限版：Windowsネイティブ映像を優先。Commands・解析・範囲指定・Tk重ね描画は停止中です。")
        else:
            for tab in limited_tabs:
                try:
                    self.controller_nb.add(tab)
                except tk.TclError:
                    pass
            self._reorder_controller_tabs()
            if hasattr(self, "recording_mode_tabs"):
                try:
                    self.recording_mode_tabs.add(
                        self.recording_monitor_page, text="Commands監視録画")
                    self.recording_mode_tabs.insert(
                        1, self.recording_monitor_page,
                        text="Commands監視録画")
                except tk.TclError:
                    pass
            if hasattr(self, "top_command_f"):
                self.top_command_f.grid()
            self.camera_feature_limited_status.set(
                "通常版：映像上の範囲指定とTk重ね描画を使用できます。")
        preview = getattr(self, "preview", None)
        if preview is not None:
            preview.setFeatureLimited(limited)
        if notify:
            message = ("機能制限版を有効にしました。InputSetへ残すには「変更保存」を押してください。"
                       if limited else
                       "通常版へ戻しました。Tk重ね描画と映像範囲指定を使用できます。")
            self.camera_feature_limited_status.set(
                self.camera_feature_limited_status.get() + " " + message)

    def _require_tk_video_overlay(self, feature_name, show_popup=True):
        limited_var = getattr(self, "camera_feature_limited", None)
        if limited_var is None or not limited_var.get():
            return True
        if show_popup:
            tkmsg.showwarning(
                "機能制限版では使用できません",
                "「{}」にはTkの映像重ね描画または範囲指定が必要です。\n\n"
                "Cameraタブで「機能制限版」をOFFにしてから実行してください。".format(
                    feature_name),
                parent=self.root)
        return False

