    def open_step_debug_guide(self):
        path = os.path.join(self._commands_assist_dir(), "STEP_DEBUG_GUIDE.md")
        try:
            with open(path, "r", encoding="utf-8") as stream: content = stream.read()
        except OSError as error:
            tkmsg.showerror("Stepデバッグ", str(error), parent=self._step_debug_window or self.root); return
        dialog = tk.Toplevel(self._step_debug_window or self.root)
        dialog.title("Stepデバッグアシスト - 詳しい使い方")
        dialog.geometry("850x680"); dialog.transient(self._step_debug_window or self.root)
        viewer = tk.Text(dialog, wrap="word", padx=12, pady=10)
        viewer.pack(fill="both", expand=True); viewer.insert("1.0", content); viewer.configure(state="disabled")
        ttk.Button(dialog, text="閉じる", command=dialog.destroy).pack(pady=7)

    @staticmethod
    def _read_step_debug_source_file(path):
        for encoding in ("utf-8", "cp932"):
            try:
                with open(path, "r", encoding=encoding) as stream:
                    return stream.read(), encoding
            except UnicodeDecodeError:
                continue
        raise ValueError("ソースの文字コードを判定できません: " + str(path))

    def _step_debug_rule_source_context(self, rule):
        target = rule.get("source", {}) if isinstance(rule.get("source"), dict) else {}
        # A shared draft can contain an absolute path from another PokeCon
        # installation. Prefer the matching command loaded by this process so
        # source application never edits the other installation by accident.
        scope = rule.get("command", "")
        classes = list(getattr(self, "py_classes", [])) + list(getattr(self, "sample_py_classes", []))
        command_class = next((item for item in classes
                              if getattr(item, "NAME", "") == scope), None)
        if command_class is None and getattr(self, "cur_command", None) is not None:
            current = self.cur_command.__class__
            if getattr(current, "NAME", "") == scope:
                command_class = current
        loaded_path = inspect.getsourcefile(command_class) if command_class is not None else ""
        path = loaded_path if loaded_path and os.path.isfile(loaded_path) \
            else str(target.get("file", "") or "")
        if not path or not os.path.isfile(path):
            raise ValueError("対象CommandsのPythonファイルを特定できません。Commandsを再読込してください。")
        path = os.path.abspath(path)
        source, encoding = self._read_step_debug_source_file(path)
        info = extract_state_method_info(
            source, rule.get("variable", ""), rule.get("state", ""),
            preferred=str(target.get("method", "") or ""))
        return {"path": path, "source": source, "encoding": encoding, "info": info}

    def _enrich_step_debug_rule(self, rule, info):
        changed = False
        source = rule.setdefault("source", {})
        for key, value in (("file", info.get("file", "")), ("method", info.get("name", ""))):
            if value and source.get(key) != value:
                source[key] = value; changed = True
        by_id = {item["id"]: item for item in info.get("operations", [])}
        for operation_id, replacement in rule.get("replacements", {}).items():
            operation = by_id.get(operation_id)
            if not isinstance(replacement, dict) or operation is None:
                continue
            for key, value in (("summary", operation.get("summary", "")),
                               ("original_code", operation.get("code", "")),
                               ("line", operation.get("line", 0))):
                if value and replacement.get(key) != value:
                    replacement[key] = value; changed = True
        return changed

    def _step_debug_replacement_code(self, replacement):
        if replacement.get("type") == "code":
            return replacement.get("code", "")
        if replacement.get("type") == "delete":
            return DELETE_OPERATION_CODE
        if replacement.get("type") == "recording":
            item = self._read_controller_recordings().get(replacement.get("recording", ""))
            if not item:
                raise ValueError("コントローラー記録が見つかりません: " + replacement.get("recording", ""))
            return python_replacement_body(item.get("lines", []))
        raise ValueError("未対応の置換形式です。")

    @staticmethod
    def _function_mapping_as_step_rule(rule):
        """Expose a function-mapping draft to the existing diff/apply path."""
        return {
            "command": rule.get("command", ""),
            "variable": rule.get("variable", ""),
            "state": rule.get("value", ""),
            "source": rule.get("source", {}),
            "replacements": rule.get("replacements", {}),
            "use_replacements": True,
        }

    def _function_mapping_replacement_codes(self, rule, enabled_only=True):
        return {
            operation_id: self._step_debug_replacement_code(replacement)
            for operation_id, replacement in rule.get("replacements", {}).items()
            if not enabled_only or replacement_is_enabled(replacement)
        }

    def _function_replacement_diff(self, rule):
        step_rule = self._function_mapping_as_step_rule(rule)
        context = self._step_debug_rule_source_context(step_rule)
        replacements = self._function_mapping_replacement_codes(rule, enabled_only=False)
        if not replacements:
            raise ValueError("実動作試験ONの置換処理がありません。")
        updated = apply_operation_replacements(
            context["source"], context["info"], replacements)
        return "".join(difflib.unified_diff(
            context["source"].splitlines(True), updated.splitlines(True),
            fromfile=context["path"] + " (元の関数)",
            tofile=context["path"] + " (一時置換後)")) or "（差分はありません）"

    def add_current_step_debug_to_function_replacements(self):
        """Consolidate active operation drafts into one runtime state method."""
        session = self._step_debug_session
        if not session or session.get("busy"):
            tkmsg.showinfo(
                "関数置換へ追加", "Stepデバッグで対象関数を停止してから実行してください。",
                parent=self._step_debug_window or self.root)
            return
        step_rule = session["rule"]
        if self._enrich_step_debug_rule(step_rule, session["info"]):
            self._write_step_debug_rules()
        replacements = {
            operation_id: json.loads(json.dumps(replacement, ensure_ascii=False))
            for operation_id, replacement in step_rule.get("replacements", {}).items()
            if replacement_is_enabled(replacement)
        }
        if not step_rule.get("use_replacements", True) or not replacements:
            tkmsg.showinfo(
                "関数置換へ追加",
                "試験ONになっている保存済み置換案がありません。\n"
                "置換案の「試験に使用」をONにしてから追加してください。",
                parent=self._step_debug_window or self.root)
            return
        command_name = str(getattr(session["command"], "NAME", "") or step_rule.get("command", ""))
        mapping = {
            "id": str(time.time_ns()),
            "function_replacement": True,
            "command": command_name,
            "kind": "value_stable",
            "variable": session["variable"],
            "value": session["state"],
            "seconds": 0.0,
            "action": "replace",
            "replacement_type": "step_debug_function",
            "runtime_enabled": True,
            "step_debug_rule_id": str(step_rule.get("id", "")),
            "source": json.loads(json.dumps(step_rule.get("source", {}), ensure_ascii=False)),
            "replacements": replacements,
        }
        try:
            # Validate both the live in-memory function and the persisted
            # source diff before registering a production-speed trial.
            build_runtime_replacement_function(
                session["method"], self._function_mapping_replacement_codes(mapping))
            mapping["reviewed_diff"] = self._function_replacement_diff(mapping)
        except (OSError, SyntaxError, TypeError, ValueError) as error:
            tkmsg.showerror(
                "関数置換へ追加", "関数全体の置換を生成できませんでした。\n{}".format(error),
                parent=self._step_debug_window or self.root)
            return
        existing = next((index for index, item in enumerate(self.commands_assist_rules)
                         if item.get("function_replacement")
                         and item.get("replacement_type") == "step_debug_function"
                         and item.get("command") == command_name
                         and item.get("variable") == session["variable"]
                         and item.get("value") == session["state"]), None)
        if existing is None:
            self.commands_assist_rules.append(mapping)
        else:
            mapping["id"] = self.commands_assist_rules[existing].get("id", mapping["id"])
            self.commands_assist_rules[existing] = mapping
        self._refresh_commands_assist_rule_list()
        self._sync_commands_assist_rules_to_active_input_set()
        self.open_function_replacements(select_rule_id=mapping["id"])

    def _choose_step_debug_apply_target(self, source_path, sample_paths, parent):
        if not sample_paths:
            return "source"
        dialog = tk.Toplevel(parent)
        dialog.title("本反映先を選択")
        dialog.transient(parent); dialog.grab_set(); dialog.geometry("900x360")
        selected = tk.StringVar(value="source")
        ttk.Label(dialog, text=(
            "この関数はサンプル関数ライブラリにもあります。\n"
            "特定箇所だけの調整は「このCommandsだけ」を選び、共通修正と確認できた場合だけサンプル本体へ反映してください。"),
            justify="left", foreground="#174a7e").pack(anchor="w", padx=10, pady=10)
        ttk.Radiobutton(
            dialog, variable=selected, value="source",
            text="このCommandsだけに反映（推奨・他の使用箇所は変更しない）\n  " + source_path).pack(
                anchor="w", padx=12, pady=6)
        for index, path in enumerate(sample_paths):
            ttk.Radiobutton(
                dialog, variable=selected, value="sample:" + str(index),
                text="共通サンプル本体と現在のCommandsへ反映\n  " + path).pack(
                    anchor="w", padx=12, pady=6)
        result = {"value": None}
        def accept():
            value = selected.get()
            result["value"] = sample_paths[int(value.split(":", 1)[1])] \
                if value.startswith("sample:") else "source"
            dialog.destroy()
        buttons = ttk.Frame(dialog); buttons.pack(fill="x", padx=10, pady=12)
        ttk.Button(buttons, text="差分確認へ", command=accept).pack(side="right", padx=4)
        ttk.Button(buttons, text="キャンセル", command=dialog.destroy).pack(side="right", padx=4)
        dialog.wait_window()
        return result["value"]

    def _confirm_step_debug_source_diff(self, diffs, parent):
        dialog = tk.Toplevel(parent)
        dialog.title("Stepデバッグ置換案－本反映差分")
        dialog.transient(parent); dialog.grab_set(); dialog.geometry("1100x760")
        ttk.Label(dialog, text=(
            "赤い削除行（-）と追加行（+）を確認してください。反映時は各ファイルの .bak を作成します。"),
            foreground="#9a4e00").pack(anchor="w", padx=8, pady=6)
        viewer = tk.Text(dialog, wrap="none", font=("Consolas", 10))
        viewer.pack(fill="both", expand=True, padx=8, pady=5)
        content = "\n".join(diffs)
        viewer.insert("1.0", content)
        viewer.tag_configure("added", foreground="#0b6b2b")
        viewer.tag_configure("removed", foreground="#b00020")
        for line_number, line in enumerate(content.splitlines(), 1):
            if line.startswith("+") and not line.startswith("+++"):
                viewer.tag_add("added", "{}.0".format(line_number), "{}.end".format(line_number))
            elif line.startswith("-") and not line.startswith("---"):
                viewer.tag_add("removed", "{}.0".format(line_number), "{}.end".format(line_number))
        viewer.configure(state="disabled")
        result = {"ok": False}
        def accept(): result["ok"] = True; dialog.destroy()
        buttons = ttk.Frame(dialog); buttons.pack(fill="x", padx=8, pady=8)
        ttk.Button(buttons, text="バックアップを作成して本反映", command=accept).pack(side="right", padx=4)
        ttk.Button(buttons, text="キャンセル", command=dialog.destroy).pack(side="right", padx=4)
        dialog.wait_window()
        return result["ok"]

    def _repair_step_debug_rule_before_apply(self, rule, parent, refresh_callback=None):
        repaired, changed = self._repair_mixed_step_debug_rules([rule])
        if not changed:
            return False
        index = next((position for position, candidate in enumerate(self.step_debug_rules)
                      if candidate is rule or str(candidate.get("id", "")) == str(rule.get("id", ""))),
                     None)
        if len(repaired) == 1:
            rule.clear(); rule.update(repaired[0])
            self._write_step_debug_rules()
            return False
        if index is not None:
            self.step_debug_rules[index:index + 1] = repaired
        else:
            self.step_debug_rules.extend(repaired)
        self._write_step_debug_rules()
        if refresh_callback:
            refresh_callback()
        summary = "\n".join(
            "{}: {}件".format(item.get("state", ""), len(item.get("replacements", {})))
            for item in repaired)
        tkmsg.showinfo(
            "旧Step記録を分離しました",
            "複数関数へ混在していた旧記録をStep別に分離しました。\n\n{}\n\n"
            "一覧の＋から反映する関数を選び直してください。".format(summary),
            parent=parent)
        return True

    def _apply_step_debug_rule_to_source(
            self, rule, parent, refresh_callback=None, operation_ids=None):
        if self._repair_step_debug_rule_before_apply(rule, parent, refresh_callback):
            return False
        try:
            context = self._step_debug_rule_source_context(rule)
            replacements = {
                operation_id: self._step_debug_replacement_code(replacement)
                for operation_id, replacement in rule.get("replacements", {}).items()
                if replacement_is_enabled(replacement)
                and (operation_ids is None or operation_id in operation_ids)
            }
            if not rule.get("use_replacements", True):
                replacements = {}
            if not replacements:
                raise ValueError("試験ONになっている置換案がありません。")
            fragment_root = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                         "DevTemplates", "Fragments")
            sample_paths = find_sample_function_files(fragment_root, context["info"]["name"])
            selected_target = self._choose_step_debug_apply_target(
                context["path"], sample_paths, parent)
            if selected_target is None:
                return
            targets = [(context["path"], context["source"], context["encoding"], context["info"])]
            if selected_target != "source":
                sample_source, sample_encoding = self._read_step_debug_source_file(selected_target)
                sample_info = extract_named_method_info(sample_source, context["info"]["name"])
                targets.insert(0, (selected_target, sample_source, sample_encoding, sample_info))
            prepared, diffs = [], []
            for path, source, encoding, info in targets:
                updated = apply_operation_replacements(source, info, replacements)
                if updated == source:
                    continue
                diff = "".join(difflib.unified_diff(
                    source.splitlines(True), updated.splitlines(True),
                    fromfile=path + " (変更前)", tofile=path + " (変更後)"))
                diffs.append(diff); prepared.append((path, updated, encoding))
            if not prepared:
                raise ValueError("反映対象に変更はありません。")
        except (OSError, SyntaxError, ValueError) as error:
            tkmsg.showerror("Stepデバッグ本反映", str(error), parent=parent); return False
        if not self._confirm_step_debug_source_diff(diffs, parent):
            return False
        timestamp = time.strftime("%Y%m%d_%H%M%S")
        try:
            temporary_files = []
            for path, updated, encoding in prepared:
                backup = path + ".stepdebug_" + timestamp + ".bak"
                if os.path.exists(backup):
                    backup += "." + str(time.time_ns())
                shutil.copy2(path, backup)
                temporary = path + ".stepdebug.tmp"
                with open(temporary, "w", encoding=encoding, newline="\n") as stream:
                    stream.write(updated)
                temporary_files.append((temporary, path))
            for temporary, path in temporary_files:
                os.replace(temporary, path)
        except OSError as error:
            tkmsg.showerror("Stepデバッグ本反映", "ファイルへ反映できませんでした:\n" + str(error), parent=parent); return False
        applied_paths = [path for path, _, _ in prepared]
        for operation_id in replacements:
            replacement = rule.get("replacements", {}).get(operation_id, {})
            replacement["enabled"] = False
            replacement["applied_at"] = datetime.datetime.now().isoformat(timespec="seconds")
            replacement["applied_to"] = applied_paths
        self._write_step_debug_rules()
        if refresh_callback:
            refresh_callback()
        tkmsg.showinfo(
            "Stepデバッグ本反映",
            "{}ファイルへ反映しました。置換案は記録として残し、試験OFFにしました。\n"
            "Commandsを再読込して確認してください。".format(len(applied_paths)), parent=parent)
        return True

    def open_step_debug_replacement_manager(self):
        dialog = tk.Toplevel(self.root)
        dialog.title("保存済みStepデバッグ置換案")
        dialog.transient(self.root); dialog.geometry("1180x820")
        search = tk.StringVar()
        top = ttk.Frame(dialog); top.pack(fill="x", padx=8, pady=7)
        ttk.Label(top, text="検索:").pack(side="left")
        ttk.Entry(top, textvariable=search, width=55).pack(side="left", padx=5)
        ttk.Label(top, text="停止していない関数も確認できます。InputSetへ常時同期されます。",
                  foreground="#174a7e").pack(side="left", padx=12)
        tree = ttk.Treeview(
            dialog, columns=("command", "state", "kind", "trial", "applied"),
            show="tree headings", selectmode="browse", height=13)
        for column, label, width in (
                ("#0", "処理", 360), ("command", "Commands", 230),
                ("state", "Step", 230), ("kind", "種類", 80),
                ("trial", "試験", 70), ("applied", "本反映", 110)):
            tree.heading(column, text=label); tree.column(column, width=width)
        tree.pack(fill="both", expand=True, padx=8, pady=5)
        detail = tk.StringVar(value="置換案を選択してください。")
        ttk.Label(dialog, textvariable=detail, justify="left", wraplength=1120).pack(
            anchor="w", padx=8, pady=4)
        panes = ttk.Panedwindow(dialog, orient="horizontal"); panes.pack(fill="both", expand=True, padx=8, pady=5)
        original_frame = ttk.Labelframe(panes, text="元の処理（確認専用）")
        replacement_frame = ttk.Labelframe(panes, text="保存済み置換案")
        panes.add(original_frame, weight=1); panes.add(replacement_frame, weight=1)
        original_editor = tk.Text(original_frame, wrap="none", font=("Consolas", 10), height=12)
        replacement_editor = tk.Text(replacement_frame, wrap="none", font=("Consolas", 10), height=12, undo=True)
        original_editor.pack(fill="both", expand=True); replacement_editor.pack(fill="both", expand=True)
        actions = ttk.Frame(dialog); actions.pack(fill="x", padx=8, pady=8)
        visible = {}

        def selected_item():
            selected = tree.selection()
            if not selected: return None
            return visible.get(selected[0])

        def resolve_original(rule, operation_id, replacement):
            if replacement.get("original_code"):
                path = str(rule.get("source", {}).get("file", "") or "")
                return (replacement.get("original_code", ""),
                        replacement.get("summary", operation_id), path)
            try:
                context = self._step_debug_rule_source_context(rule)
                operation = next((item for item in context["info"]["operations"]
                                  if item["id"] == operation_id), None)
                if operation:
                    return operation["code"], operation["summary"], context["path"]
                return "（現在のソースではこの処理IDを見つけられません）", operation_id, context["path"]
            except (OSError, SyntaxError, ValueError) as error:
                return "（元処理を取得できません: {}）".format(error), operation_id, ""

        def rule_function_preview(rule):
            context = self._step_debug_rule_source_context(rule)
            replacements = {
                operation_id: self._step_debug_replacement_code(replacement)
                for operation_id, replacement in rule.get("replacements", {}).items()
                if replacement_is_enabled(replacement)
            }
            updated = apply_operation_replacements(
                context["source"], context["info"], replacements)
            updated_info = extract_named_method_info(updated, context["info"]["name"])

            def method_text(source, info):
                lines = source.splitlines(True)
                return "".join(lines[int(info["line"]) - 1:int(info["end_line"])]).rstrip()

            return (context, method_text(context["source"], context["info"]),
                    method_text(updated, updated_info), updated)

        def show_selected(event=None):
            item = selected_item()
            original_editor.configure(state="normal"); original_editor.delete("1.0", "end")
            replacement_editor.configure(state="normal"); replacement_editor.delete("1.0", "end")
            if not item:
                original_editor.configure(state="disabled"); return
            if item[0] == "function":
                rule = item[1]
                try:
                    context, original, updated, _ = rule_function_preview(rule)
                    original_editor.insert("1.0", original)
                    replacement_editor.insert("1.0", updated)
                    detail.set(
                        "{} :: {} / 関数 {}() の変更{}件をまとめて表示\n元ファイル: {}".format(
                            rule.get("variable", ""), rule.get("state", ""),
                            context["info"]["name"], len(rule.get("replacements", {})),
                            context["path"]))
                except (OSError, SyntaxError, TypeError, ValueError) as error:
                    original_editor.insert("1.0", "関数を取得できません: {}".format(error))
                    detail.set("関数単位の表示を作成できません。")
                original_editor.configure(state="disabled")
                replacement_editor.configure(state="disabled")
                return
            _kind, rule, operation_id, replacement = item
            original, summary, path = resolve_original(rule, operation_id, replacement)
            original_editor.insert("1.0", original); original_editor.configure(state="disabled")
            try: replacement_code = self._step_debug_replacement_code(replacement)
            except ValueError as error: replacement_code = "# " + str(error)
            replacement_editor.insert("1.0", replacement_code)
            if replacement.get("type") != "code": replacement_editor.configure(state="disabled")
            detail.set("{} :: {} / {}\n元ファイル: {}".format(
                rule.get("variable", ""), rule.get("state", ""), summary, path or "未特定"))

        def refresh():
            needle = search.get().strip().casefold(); visible.clear()
            tree.delete(*tree.get_children())
            operation_count = 0
            for rule_index, rule in enumerate(self.step_debug_rules):
                matched = []
                for operation_id, replacement in rule.get("replacements", {}).items():
                    haystack = " ".join((str(rule.get("command", "")), str(rule.get("state", "")),
                                         str(operation_id), str(replacement.get("summary", "")),
                                         str(replacement.get("code", "")), str(replacement.get("recording", "")),
                                         "削除" if replacement.get("type") == "delete" else "")).casefold()
                    if not needle or needle in haystack:
                        matched.append((operation_id, replacement))
                if not matched:
                    continue
                try:
                    context = self._step_debug_rule_source_context(rule)
                    method_name = context["info"]["name"]
                except (OSError, SyntaxError, TypeError, ValueError):
                    method_name = rule.get("source", {}).get("method") or rule.get("state", "")
                root_id = "function:{}".format(rule_index)
                active = sum(1 for _, replacement in matched
                             if rule.get("use_replacements", True)
                             and replacement_is_enabled(replacement))
                applied_count = sum(1 for _, replacement in matched
                                    if replacement.get("applied_at"))
                tree.insert(
                    "", "end", iid=root_id, open=False,
                    text="関数: {}()（変更{}件）".format(method_name, len(matched)),
                    values=(rule.get("command", ""), rule.get("state", ""), "まとめ",
                            "ON {}件".format(active),
                            "{} / {}件".format(applied_count, len(matched))))
                visible[root_id] = ("function", rule)
                for child_index, (operation_id, replacement) in enumerate(matched):
                    child_id = "operation:{}:{}".format(rule_index, child_index)
                    summary = replacement.get("summary") or operation_id
                    replacement_type = replacement.get("type")
                    kind = {"code": "コード", "recording": "記録",
                            "delete": "削除"}.get(replacement_type, replacement_type or "不明")
                    trial = "ON" if (rule.get("use_replacements", True)
                                        and replacement_is_enabled(replacement)) else "OFF"
                    applied = "反映済" if replacement.get("applied_at") else "未反映"
                    tree.insert(root_id, "end", iid=child_id, text=summary,
                                values=(rule.get("command", ""), rule.get("state", ""),
                                        kind, trial, applied))
                    visible[child_id] = ("operation", rule, operation_id, replacement)
                    operation_count += 1
            detail.set("保存済み置換案: {}関数 / {}処理（＋で展開）".format(
                len(tree.get_children()), operation_count))
            original_editor.configure(state="normal"); original_editor.delete("1.0", "end"); original_editor.configure(state="disabled")
            replacement_editor.configure(state="normal"); replacement_editor.delete("1.0", "end")

        def save_edit():
            item = selected_item()
            if not item or item[0] != "operation": return
            _kind, rule, operation_id, replacement = item
            if replacement.get("type") != "code":
                tkmsg.showinfo("保存済み置換案", "PC操作記録は記録ライブラリ側で編集してください。", parent=dialog); return
            try: code = validate_operation_code(replacement_editor.get("1.0", "end-1c"))
            except (SyntaxError, ValueError) as error:
                tkmsg.showwarning("保存済み置換案", str(error), parent=dialog); return
            replacement["code"] = code; self._write_step_debug_rules(); refresh()

        def toggle():
            item = selected_item()
            if not item or item[0] != "operation": return
            replacement = item[3]
            replacement["enabled"] = not replacement_is_enabled(replacement)
            self._write_step_debug_rules(); refresh()

        def delete():
            item = selected_item()
            if not item or item[0] != "operation": return
            _kind, rule, operation_id, _replacement = item
            if not tkmsg.askyesno("保存済み置換案", "選択した置換案を削除しますか？", parent=dialog): return
            rule.get("replacements", {}).pop(operation_id, None)
            self._write_step_debug_rules(); refresh()

        def rebind_original():
            item = selected_item()
            if not item or item[0] != "operation": return
            _kind, rule, old_operation_id, replacement = item
            try:
                context = self._step_debug_rule_source_context(rule)
            except (OSError, SyntaxError, ValueError) as error:
                tkmsg.showerror("元処理の再指定", str(error), parent=dialog); return
            popup = tk.Toplevel(dialog)
            popup.title("置換案の元処理を再指定")
            popup.transient(dialog); popup.grab_set(); popup.geometry("1050x720")
            ttk.Label(
                popup,
                text="現在のソースから、この置換案が置き換える処理を1件選んでください。自動では変更しません。",
                foreground="#9a4e00").pack(anchor="w", padx=8, pady=8)
            listing_frame = ttk.Labelframe(popup, text="1. 元処理を選択")
            listing_frame.pack(fill="both", expand=True, padx=8, pady=5)
            listing = tk.Listbox(listing_frame, exportselection=False, width=120, height=13)
            listing.pack(fill="both", expand=True, padx=5, pady=5)
            preview_frame = ttk.Labelframe(popup, text="2. 選択した元処理の内容（確認専用）")
            preview_frame.pack(fill="both", expand=True, padx=8, pady=5)
            preview = tk.Text(preview_frame, wrap="none", font=("Consolas", 10), height=12)
            preview_scroll_y = ttk.Scrollbar(
                preview_frame, orient="vertical", command=preview.yview)
            preview_scroll_x = ttk.Scrollbar(
                preview_frame, orient="horizontal", command=preview.xview)
            preview.configure(
                yscrollcommand=preview_scroll_y.set, xscrollcommand=preview_scroll_x.set)
            preview.grid(column=0, row=0, sticky="nsew")
            preview_scroll_y.grid(column=1, row=0, sticky="ns")
            preview_scroll_x.grid(column=0, row=1, sticky="ew")
            preview_frame.columnconfigure(0, weight=1)
            preview_frame.rowconfigure(0, weight=1)
            operations = context["info"]["operations"]
            for index, operation in enumerate(operations):
                listing.insert("end", "{}. 行{} / {} / {}".format(
                    index + 1, operation.get("line", "-"),
                    operation.get("context") or "条件なし", operation.get("summary", "")))
            old_keys = list(rule.get("replacements", {}))
            if old_operation_id in old_keys:
                guessed_index = min(old_keys.index(old_operation_id), max(0, len(operations) - 1))
                if operations:
                    listing.selection_set(guessed_index); listing.see(guessed_index)

            def show_original_code(_event=None):
                selected = listing.curselection()
                preview.configure(state="normal")
                preview.delete("1.0", "end")
                if selected:
                    operation = operations[selected[0]]
                    preview.insert(
                        "1.0", "行: {}\n条件内: {}\n処理ID: {}\n\n{}".format(
                            operation.get("line", "-"),
                            operation.get("context") or "条件なし",
                            operation.get("id", ""),
                            operation.get("code", "（コードを取得できません）")))
                else:
                    preview.insert("1.0", "上の一覧から元処理を1件選んでください。")
                preview.configure(state="disabled")

            def accept():
                selected = listing.curselection()
                if not selected: return
                operation = operations[selected[0]]
                new_operation_id = operation["id"]
                existing = rule.get("replacements", {}).get(new_operation_id)
                if existing is not None and existing is not replacement:
                    if not tkmsg.askyesno(
                            "元処理の再指定", "選択先には別の置換案があります。上書きしますか？",
                            parent=popup): return
                rule.setdefault("replacements", {}).pop(old_operation_id, None)
                replacement.update({"summary": operation.get("summary", ""),
                                    "original_code": operation.get("code", ""),
                                    "line": operation.get("line", 0)})
                rule["replacements"][new_operation_id] = replacement
                rule["source"] = {"file": context["path"], "method": context["info"]["name"]}
                self._write_step_debug_rules(); popup.destroy(); refresh()
            listing.bind("<<ListboxSelect>>", show_original_code)
            show_original_code()
            buttons = ttk.Frame(popup); buttons.pack(fill="x", padx=8, pady=8)
            ttk.Button(buttons, text="選んだ1件を元処理として設定", command=accept).pack(
                side="right", padx=3)
            ttk.Button(buttons, text="キャンセル", command=popup.destroy).pack(side="right", padx=3)

        def copy_code():
            value = replacement_editor.get("1.0", "end-1c")
            if not value: return
            self.root.clipboard_clear(); self.root.clipboard_append(value)

        def selected_rule():
            item = selected_item()
            return item[1] if item else None

        def mark_operation_deleted():
            item = selected_item()
            if not item or item[0] != "operation":
                tkmsg.showinfo("処理削除", "関数内の処理を1件選んでください。", parent=dialog)
                return
            _kind, rule, operation_id, replacement = item
            if not tkmsg.askyesno(
                    "処理削除",
                    "選択した処理を実行しない置換案へ変更します。\n"
                    "ソース反映時は安全な pass 行になります。続行しますか？",
                    parent=dialog):
                return
            replacement["type"] = "delete"
            replacement.pop("code", None)
            replacement.pop("recording", None)
            replacement["enabled"] = True
            rule.setdefault("replacements", {})[operation_id] = replacement
            self._write_step_debug_rules(); refresh()

        def show_function_diff():
            rule = selected_rule()
            if rule is None:
                return
            try:
                context, _original, _updated_function, updated_source = rule_function_preview(rule)
                content = "".join(difflib.unified_diff(
                    context["source"].splitlines(True), updated_source.splitlines(True),
                    fromfile=context["path"] + " (変更前)",
                    tofile=context["path"] + " (変更後)"))
            except (OSError, SyntaxError, TypeError, ValueError) as error:
                tkmsg.showerror("関数差分", str(error), parent=dialog); return
            popup = tk.Toplevel(dialog)
            popup.title("関数単位の差分（確認専用）")
            popup.transient(dialog); popup.geometry("1100x720")
            viewer = tk.Text(popup, wrap="none", font=("Consolas", 10))
            y_scroll = ttk.Scrollbar(popup, orient="vertical", command=viewer.yview)
            x_scroll = ttk.Scrollbar(popup, orient="horizontal", command=viewer.xview)
            viewer.configure(yscrollcommand=y_scroll.set, xscrollcommand=x_scroll.set)
            viewer.grid(column=0, row=0, sticky="nsew")
            y_scroll.grid(column=1, row=0, sticky="ns")
            x_scroll.grid(column=0, row=1, sticky="ew")
            popup.columnconfigure(0, weight=1); popup.rowconfigure(0, weight=1)
            viewer.insert("1.0", content or "差分はありません。")
            viewer.tag_configure("added", foreground="#0b6b2b")
            viewer.tag_configure("removed", foreground="#b00020")
            for line_number, line in enumerate((content or "").splitlines(), 1):
                if line.startswith("+") and not line.startswith("+++"):
                    viewer.tag_add("added", "{}.0".format(line_number), "{}.end".format(line_number))
                elif line.startswith("-") and not line.startswith("---"):
                    viewer.tag_add("removed", "{}.0".format(line_number), "{}.end".format(line_number))
            viewer.configure(state="disabled")
            ttk.Button(popup, text="閉じる", command=popup.destroy).grid(
                column=0, row=2, padx=8, pady=7, sticky="e")

        def apply_source():
            rule = selected_rule()
            if rule is None: return
            self._apply_step_debug_rule_to_source(rule, dialog, refresh)

        def apply_selected_operation():
            item = selected_item()
            if not item or item[0] != "operation":
                tkmsg.showinfo(
                    "1件を本反映", "関数の＋を開き、本反映する処理を1件選んでください。",
                    parent=dialog)
                return
            _kind, rule, operation_id, replacement = item
            if not replacement_is_enabled(replacement):
                tkmsg.showinfo(
                    "1件を本反映",
                    "選択した置換案は試験OFFです。［試験ON／OFF］でONにしてから反映してください。",
                    parent=dialog)
                return
            self._apply_step_debug_rule_to_source(
                rule, dialog, refresh, operation_ids={operation_id})

        ttk.Button(actions, text="編集内容を保存", command=save_edit).pack(side="left", padx=3)
        ttk.Button(actions, text="試験ON／OFF", command=toggle).pack(side="left", padx=3)
        ttk.Button(actions, text="処理を削除にする", command=mark_operation_deleted).pack(side="left", padx=3)
        ttk.Button(actions, text="コードをコピー", command=copy_code).pack(side="left", padx=3)
        ttk.Button(actions, text="元処理を再指定…", command=rebind_original).pack(side="left", padx=3)
        ttk.Button(actions, text="選んだ1件をソースへ本反映…",
                   command=apply_selected_operation).pack(side="left", padx=(10, 3))
        function_actions = ttk.Frame(dialog); function_actions.pack(fill="x", padx=8, pady=(0, 8))
        ttk.Button(function_actions, text="関数全体の差分を表示",
                   command=show_function_diff).pack(side="left", padx=3)
        ttk.Button(function_actions, text="この関数の変更をまとめてソースへ本反映…",
                   command=apply_source).pack(side="left", padx=8)
        ttk.Button(function_actions, text="置換案の登録を削除", command=delete).pack(side="right", padx=3)
        ttk.Button(function_actions, text="閉じる", command=dialog.destroy).pack(side="right", padx=3)
        tree.bind("<<TreeviewSelect>>", show_selected)
        search.trace_add("write", lambda *_args: refresh())
        refresh()

    def _refresh_step_debug_window(self):
        dialog = self._step_debug_window
        try:
            if dialog is None or not dialog.winfo_exists(): return
        except tk.TclError:
            return
        self.step_debug_rule_list.delete(0, "end")
        for rule in self.step_debug_rules:
            self.step_debug_rule_list.insert("end", self._step_debug_rule_text(rule))
        tree = self.step_debug_operation_tree
        tree.delete(*tree.get_children())
        session = self._step_debug_session
        if not session:
            self.step_debug_live_status.set("まだ停止していません。停止地点を保存し、CommandsをStartしてください。")
            self.step_debug_progress_status.set(
                "置換案は保存済みです。再実行して同じStepで停止すると③に表示されます。")
            self.step_debug_next_combo.configure(values=())
            self._refresh_step_debug_operation_preview()
            return
        info, rule = session["info"], session["rule"]
        self.step_debug_live_status.set("停止中: {} :: {}  →  {}()  （元ソースは未変更）".format(
            session["variable"], session["state"], info["name"]))
        replacements = rule.get("replacements", {})
        operation_count = len(info["operations"])
        executed = {index for index in session["executed"] if 0 <= index < operation_count}
        continuous = 0
        while continuous in executed:
            continuous += 1
        next_index = next((index for index in range(operation_count) if index not in executed), None)
        if next_index is None:
            progress = "実行位置: 全{}件を実行済み".format(operation_count)
        else:
            progress = "実行位置: 先頭から{} / {}件完了（合計{}件）  次は {}番".format(
                continuous, operation_count, len(executed), next_index + 1)
        self.step_debug_progress_status.set(
            progress + "  ※この画面を閉じても、Commandsを止めない限り続きから戻れます。")
        session["tree_indices"] = {}
        index_iids = {}
        for index, operation in enumerate(info["operations"]):
            replacement = replacements.get(operation["id"], {})
            if replacement.get("type") == "code":
                snippet = " ".join(str(replacement.get("code", "")).strip().splitlines())
                replacement_label = "コード: " + (snippet[:55] + ("…" if len(snippet) > 55 else ""))
            elif replacement.get("type") == "recording":
                replacement_label = "記録: " + replacement.get("recording", "")
            elif replacement.get("type") == "delete":
                replacement_label = "削除（実行しない）"
            else:
                replacement_label = "-"
            if replacement:
                if not rule.get("use_replacements", True):
                    replacement_label += " [全体試験OFF]"
                else:
                    replacement_label += " [試験ON]" if replacement_is_enabled(replacement) else " [試験OFF]"
            status = "実行済" if index in session["executed"] else "未実行"
            context = operation["context"] or "-"
            if operation.get("uses_names"):
                context += " / 単独実行注意: " + ", ".join(operation["uses_names"])
            iid = tree.insert("", "end", text="{}. {}".format(index + 1, operation["summary"]),
                              values=(status, operation["line"], context, replacement_label))
            session.setdefault("tree_indices", {})[iid] = index
            index_iids[index] = iid
        preview_index = next_index if next_index is not None else (
            operation_count - 1 if operation_count else None)
        if preview_index is not None and preview_index in index_iids:
            tree.selection_set(index_iids[preview_index])
            tree.focus(index_iids[preview_index])
            tree.see(index_iids[preview_index])
        self._refresh_step_debug_operation_preview()
        mapping_values = list(
            getattr(session["command"], session["variable"], {}).keys())
        values = info["next_states"] or mapping_values
        self.step_debug_next_combo.configure(values=values)
        if self.step_debug_next_state.get() not in values:
            recommended = recommended_next_state(
                session["state"], info["next_states"], mapping_values)
            self.step_debug_next_state.set(recommended or (values[0] if values else ""))

    def _selected_step_debug_index(self):
        if not self._step_debug_session or not hasattr(self, "step_debug_operation_tree"): return None
        selected = self.step_debug_operation_tree.selection()
        return self._step_debug_session.get("tree_indices", {}).get(selected[0]) if selected else None

    @staticmethod
    def _set_step_debug_preview_text(widget, value):
        if widget is None:
            return
        widget.configure(state="normal")
        widget.delete("1.0", "end")
        widget.insert("1.0", value)
        widget.configure(state="disabled")

    def _step_debug_operation_preview_values(self):
        session, index = self._step_debug_session, self._selected_step_debug_index()
        if not session or index is None:
            return "", "置換なし", ""
        operations = session["info"]["operations"]
        if not 0 <= index < len(operations):
            return "", "置換なし", ""
        operation = operations[index]
        original = str(operation.get("code", ""))
        replacement = self._step_debug_saved_replacement(session, operation)
        if not replacement:
            return original, "置換なし（実行時は元処理を使用）", original
        overall_enabled = bool(session["rule"].get("use_replacements", True))
        item_enabled = replacement_is_enabled(replacement)
        active = overall_enabled and item_enabled
        status = "試験ON：この置換を実行" if active else (
            "全体試験OFF：保存済みですが実行時は元処理を使用"
            if not overall_enabled else
            "試験OFF：保存済みですが実行時は元処理を使用")
        if replacement.get("type") == "recording":
            name = str(replacement.get("recording", ""))
            item = self._read_controller_recordings().get(name, {})
            try:
                body = python_replacement_body(item.get("lines", [])) if item else ""
            except ValueError as error:
                body = "変換できません: {}".format(error)
            content = "記録名: {}\n{}".format(name, body or "（記録内容が見つかりません）")
            return original, "PC操作記録 / " + status, content
        return original, "コード置換 / " + status, str(replacement.get("code", ""))

    def _refresh_step_debug_operation_preview(self, _event=None):
        if not hasattr(self, "step_debug_original_preview"):
            return
        original, status, replacement = self._step_debug_operation_preview_values()
        self._set_step_debug_preview_text(self.step_debug_original_preview, original)
        self.step_debug_replacement_preview_status.set(status)
        self._set_step_debug_preview_text(self.step_debug_replacement_preview, replacement)

    def copy_selected_step_debug_replacement(self):
        _original, _status, replacement = self._step_debug_operation_preview_values()
        if not replacement:
            tkmsg.showinfo("Stepデバッグ", "コピーする処理を選んでください。",
                           parent=self._step_debug_window or self.root)
            return
        self.root.clipboard_clear()
        self.root.clipboard_append(replacement)

    def _step_debug_saved_replacement(self, session, operation):
        return session["rule"].get("replacements", {}).get(operation["id"], {})

    def _step_debug_replacement(self, session, operation):
        if not session["rule"].get("use_replacements", True):
            return {}
        replacement = self._step_debug_saved_replacement(session, operation)
        return replacement if replacement_is_enabled(replacement) else {}

    def _confirm_step_debug_action(self, message):
        if self.step_debug_skip_confirm.get():
            return True
        return tkmsg.askyesno(
            "Stepデバッグ - 実行確認", message,
            parent=self._step_debug_window or self.root)

    def _run_step_debug_operations(self, indices):
        session = self._step_debug_session
        if not session or session.get("busy"):
            return
        operations = session["info"]["operations"]
        indices = [index for index in indices if 0 <= index < len(operations)]
        if not indices: return
        summaries = ["{}. {}".format(index + 1, operations[index]["summary"])
                     for index in indices]
        preview = "\n".join(summaries[:5])
        if len(summaries) > 5:
            preview += "\nほか{}件".format(len(summaries) - 5)
        if not self._confirm_step_debug_action(
                "次の処理を実機で実行します。大丈夫ですか？\n\n" + preview):
            return
        session["busy"] = True
        self.step_debug_live_status.set("選択処理を実行中です。操作完了まで待ってください。")

        def worker():
            for index in indices:
                operation = operations[index]
                replacement = self._step_debug_replacement(session, operation)
                if replacement.get("type") == "delete":
                    # Intentionally skip this controller/image operation.
                    pass
                elif replacement.get("type") == "recording":
                    item = self._read_controller_recordings().get(replacement.get("recording", ""))
                    if not item:
                        raise ValueError("コントローラー記録が見つかりません: " + replacement.get("recording", ""))
                    replay_recording(item.get("lines", []), self.ser,
                                     should_continue=lambda: session is self._step_debug_session)
                else:
                    code = replacement.get("code") if replacement.get("type") == "code" else operation["code"]
                    command = session["command"]
                    if hasattr(command, "begin_pause_bypass"): command.begin_pause_bypass()
                    try:
                        execute_operation(command, session["method"], code)
                    finally:
                        if hasattr(command, "end_pause_bypass"): command.end_pause_bypass()
                session["executed"].add(index)

        def completed(error=None):
            session["busy"] = False
            if error:
                tkmsg.showerror("Stepデバッグ", "実行できませんでした:\n{}".format(error), parent=self._step_debug_window or self.root)
            self._refresh_step_debug_window()

        def run():
            try: worker()
            except Exception as error:
                self._gui_action_queue.put(lambda caught=error: completed(caught))
            else:
                self._gui_action_queue.put(completed)
        threading.Thread(target=run, daemon=True, name="StepDebugOperation").start()

    def execute_selected_step_debug_operation(self):
        index = self._selected_step_debug_index()
        if index is None:
            tkmsg.showinfo("Stepデバッグ", "実行する処理を1つ選んでください。", parent=self._step_debug_window); return
        self._run_step_debug_operations([index])

    def execute_next_step_debug_operation(self):
        session = self._step_debug_session
        if not session or session.get("busy"):
            return
        operation_count = len(session["info"]["operations"])
        index = next((value for value in range(operation_count)
                      if value not in session["executed"]), None)
        if index is None:
            tkmsg.showinfo("Stepデバッグ", "この関数の処理はすべて実行済みです。",
                           parent=self._step_debug_window or self.root)
            return
        self._run_step_debug_operations([index])

    def execute_step_debug_until_selected(self):
        index = self._selected_step_debug_index()
        if index is None:
            tkmsg.showinfo("Stepデバッグ", "最後に実行する処理を選んでください。", parent=self._step_debug_window); return
        session = self._step_debug_session
        self._run_step_debug_operations([value for value in range(index + 1) if value not in session["executed"]])

    def edit_step_debug_operation(self):
        session, index = self._step_debug_session, self._selected_step_debug_index()
        if not session or index is None:
            tkmsg.showinfo("Stepデバッグ", "修正する処理を1つ選んでください。", parent=self._step_debug_window); return
        operation = session["info"]["operations"][index]
        current = self._step_debug_saved_replacement(session, operation)
        popup = tk.Toplevel(self._step_debug_window); popup.title("一時置換の編集")
        popup.transient(self._step_debug_window); popup.grab_set(); popup.geometry("850x470")
        ttk.Label(popup, text="この調整は別設定に保存されます。元のPythonソースは変更しません。",
                  foreground="#174a7e").pack(anchor="w", padx=8, pady=6)
        editor = tk.Text(popup, wrap="none", undo=True, font=("Consolas", 10), tabs=(32,))
        editor.pack(fill="both", expand=True, padx=8, pady=5)
        editor.insert("1.0", current.get("code", operation["code"]) if current.get("type") != "recording" else operation["code"])

        def save():
            try: code = validate_operation_code(editor.get("1.0", "end-1c"))
            except (SyntaxError, ValueError) as error:
                tkmsg.showwarning("Stepデバッグ", str(error), parent=popup); return
            session["rule"].setdefault("replacements", {})[operation["id"]] = {
                "type": "code", "code": code,
                "enabled": bool(current.get("enabled", True)),
                "summary": operation.get("summary", ""),
                "original_code": operation.get("code", ""),
                "line": operation.get("line", 0)}
            self._write_step_debug_rules(); popup.destroy(); self._refresh_step_debug_window()
        buttons = ttk.Frame(popup); buttons.pack(fill="x", padx=8, pady=7)
        ttk.Button(buttons, text="一時置換として保存", command=save).pack(side="right", padx=3)
        ttk.Button(buttons, text="キャンセル", command=popup.destroy).pack(side="right", padx=3)

    def replace_step_debug_with_recording(self):
        session, index = self._step_debug_session, self._selected_step_debug_index()
        if not session or index is None:
            tkmsg.showinfo("Stepデバッグ", "置換する処理を1つ選んでください。", parent=self._step_debug_window); return
        names = sorted(self._read_controller_recordings(), key=str.casefold)
        if not names:
            tkmsg.showinfo("PC操作記録", "登録済み記録がありません。\n「記録ライブラリを開く」から記録ファイルを登録してください。",
                           parent=self._step_debug_window); return
        popup = tk.Toplevel(self._step_debug_window); popup.title("PC操作記録で置換")
        popup.transient(self._step_debug_window); popup.grab_set(); popup.geometry("620x440")
        search = tk.StringVar(); ttk.Label(popup, text="記録名を検索:").pack(anchor="w", padx=8, pady=(8, 2))
        ttk.Entry(popup, textvariable=search).pack(fill="x", padx=8)
        listing = tk.Listbox(popup, exportselection=False); listing.pack(fill="both", expand=True, padx=8, pady=6)
        visible = []
        def refresh(*_args):
            visible[:] = [name for name in names if search.get().strip().casefold() in name.casefold()]
            listing.delete(0, "end")
            for name in visible: listing.insert("end", name)
        def accept():
            selected = listing.curselection()
            if not selected: return
            operation = session["info"]["operations"][index]
            session["rule"].setdefault("replacements", {})[operation["id"]] = {
                "type": "recording", "recording": visible[selected[0]], "enabled": True,
                "summary": operation.get("summary", ""),
                "original_code": operation.get("code", ""),
                "line": operation.get("line", 0)}
            self._write_step_debug_rules(); popup.destroy(); self._refresh_step_debug_window()
        search.trace_add("write", refresh); refresh()
        buttons = ttk.Frame(popup); buttons.pack(fill="x", padx=8, pady=7)
        ttk.Button(buttons, text="この記録で置換", command=accept).pack(side="right", padx=3)
        ttk.Button(buttons, text="キャンセル", command=popup.destroy).pack(side="right", padx=3)

    def delete_selected_step_debug_operation(self):
        """Save a no-op replacement while retaining an auditable source diff."""
        session, index = self._step_debug_session, self._selected_step_debug_index()
        if not session or index is None:
            tkmsg.showinfo(
                "Stepデバッグ", "削除する処理を1つ選んでください。",
                parent=self._step_debug_window or self.root)
            return
        operation = session["info"]["operations"][index]
        if not tkmsg.askyesno(
                "処理を削除",
                "次の処理を実行しない置換案として保存します。\n\n{}\n\n"
                "ソース反映時は安全のため pass 行へ置き換えます。続行しますか？".format(
                    operation.get("summary", "")),
                parent=self._step_debug_window or self.root):
            return
        session["rule"].setdefault("replacements", {})[operation["id"]] = {
            "type": "delete", "enabled": True,
            "summary": operation.get("summary", ""),
            "original_code": operation.get("code", ""),
            "line": operation.get("line", 0),
        }
        self._write_step_debug_rules()
        self._refresh_step_debug_window()

    def record_step_debug_operation_now(self):
        """Record a live PC-gamepad correction and attach it to one operation."""
        from tkinter import simpledialog
        session, index = self._step_debug_session, self._selected_step_debug_index()
        if not session or index is None:
            tkmsg.showinfo("Stepデバッグ", "PC操作で置換する処理を1つ選んでください。",
                           parent=self._step_debug_window); return
        if self.pro_controller_thread is not None and self.pro_controller_thread.is_alive():
            tkmsg.showwarning("PC操作記録", "すでにPCゲームパッド入力が実行中です。",
                              parent=self._step_debug_window); return
        self.refresh_pc_gamepads()
        if not self.pc_gamepad.get():
            tkmsg.showwarning("PC操作記録", "PCゲームパッドが見つかりません。",
                              parent=self._step_debug_window); return
        if not tkmsg.askyesno(
                "PC操作記録",
                "PCゲームパッドからSwitchへの入力を許可し、今からの操作を記録します。\n"
                "最初にスティックとボタンをすべて離してください。\n\n開始しますか？",
                parent=self._step_debug_window): return
        os.makedirs("Controller_Log", exist_ok=True)
        self.is_record_Pro_Controller.set(True)
        self.record_Pro_Controller()
        self.pc_gamepad_input_enabled.set(True)
        self.toggle_pc_gamepad_input()
        self.is_use_Pro_Controller.set(True)
        self.mode_change_Pro_Controller()
        if not self.is_use_Pro_Controller.get():
            return
        popup = tk.Toplevel(self._step_debug_window)
        popup.title("PC操作を記録中")
        popup.transient(self._step_debug_window); popup.grab_set(); popup.geometry("560x230")
        status = tk.StringVar(value="ニュートラル確認後、ゲームパッドで問題箇所を操作してください。")
        ttk.Label(popup, text="● 記録中", foreground="#b00020", font=("TkDefaultFont", 13, "bold")).pack(pady=(18, 8))
        ttk.Label(popup, textvariable=status, wraplength=520, justify="left").pack(padx=12, pady=5)
        stop_button = ttk.Button(popup, text="操作完了－記録を停止してこの処理に登録")
        stop_button.pack(pady=16)
        state = {"stopping": False, "filename": ""}

        def finish_registration(attempt=0):
            if self.pro_controller_thread is not None and self.pro_controller_thread.is_alive() and attempt < 100:
                popup.after(100, finish_registration, attempt + 1); return
            filename = state["filename"] or str(getattr(self.procon, "filename", "") or "")
            path = os.path.abspath(filename) if filename else ""
            if not path or not os.path.isfile(path):
                status.set("記録ファイルを取得できませんでした。記録ライブラリからファイルを登録できます。")
                stop_button.configure(state="disabled"); return
            try:
                with open(path, "r", encoding="utf-8") as stream: lines = stream.readlines()
                python_replacement_body(lines)
            except (OSError, ValueError) as error:
                status.set("記録を登録できません: {}".format(error)); return
            default_name = "{}_{}_{}".format(session["state"], index + 1, time.strftime("%Y%m%d_%H%M%S"))
            name = simpledialog.askstring("PC操作記録", "保存名:", initialvalue=default_name, parent=popup)
            if not name or not name.strip():
                status.set("保存名が入力されていません。記録ファイル自体は残っています。"); return
            name = name.strip(); data = self._read_controller_recordings()
            if name in data and not tkmsg.askyesno("PC操作記録", "同名の記録を更新しますか？", parent=popup): return
            data[name] = {"source_path": path, "lines": lines}; self._write_controller_recordings(data)
            operation = session["info"]["operations"][index]
            session["rule"].setdefault("replacements", {})[operation["id"]] = {
                "type": "recording", "recording": name, "enabled": True,
                "summary": operation.get("summary", ""),
                "original_code": operation.get("code", ""),
                "line": operation.get("line", 0)}
            self._write_step_debug_rules(); popup.destroy(); self._refresh_step_debug_window()

        def stop_recording():
            if state["stopping"]: return
            state["stopping"] = True; stop_button.configure(state="disabled")
            state["filename"] = str(getattr(self.procon, "filename", "") or "")
            status.set("記録を終了して保存中です…")
            ProController.flag_procon = False
            self.is_use_Pro_Controller.set(False)
            self.mode_change_Pro_Controller()
            popup.after(100, finish_registration)

        stop_button.configure(command=stop_recording)
        popup.protocol("WM_DELETE_WINDOW", stop_recording)

    def toggle_step_debug_replacement(self):
        session, index = self._step_debug_session, self._selected_step_debug_index()
        if not session or index is None:
            tkmsg.showinfo("Stepデバッグ", "試験ON/OFFを切り替える置換案を選んでください。",
                           parent=self._step_debug_window or self.root)
            return
        operation = session["info"]["operations"][index]
        replacement = self._step_debug_saved_replacement(session, operation)
        if not replacement:
            tkmsg.showinfo("Stepデバッグ", "この処理には保存済みの置換案がありません。",
                           parent=self._step_debug_window or self.root)
            return
        replacement["enabled"] = not replacement_is_enabled(replacement)
        self._write_step_debug_rules(); self._refresh_step_debug_window()

    def clear_step_debug_replacement(self):
        session, index = self._step_debug_session, self._selected_step_debug_index()
        if not session or index is None: return
        operation = session["info"]["operations"][index]
        if operation["id"] not in session["rule"].get("replacements", {}):
            return
        if not tkmsg.askyesno("Stepデバッグ", "選んだ処理の保存済み置換案を削除しますか？",
                              parent=self._step_debug_window or self.root):
            return
        session["rule"].setdefault("replacements", {}).pop(operation["id"], None)
        self._write_step_debug_rules(); self._refresh_step_debug_window()

    def finish_step_debug_next(self):
        session = self._step_debug_session
        if not session or session.get("busy"): return
        next_state = self.step_debug_next_state.get().strip()
        if not next_state:
            tkmsg.showwarning("Stepデバッグ", "次のStepを選んでください。", parent=self._step_debug_window); return
        if not self._confirm_step_debug_action(
                "元関数は実行せず、次Step「{}」へ進みます。大丈夫ですか？".format(next_state)):
            return
        if session["rule"].get("auto_follow", True):
            session["command"].__dict__.setdefault("_step_debug_follow_rules", {})[session["variable"]] = session["rule"]["id"]
        session["action"] = "next"; session["result"] = next_state; session["event"].set()
        self._step_debug_session = None; self._refresh_step_debug_window()

    def finish_step_debug_original(self):
        session = self._step_debug_session
        if not session or session.get("busy"): return
        if not self._confirm_step_debug_action(
                "元の関数を最初から通常実行します。大丈夫ですか？\n"
                "手動で試した操作と重複する可能性があります。"):
            return
        session["command"].__dict__.setdefault("_step_debug_follow_rules", {}).pop(session["variable"], None)
        session["action"] = "original"; session["event"].set()
        self._step_debug_session = None; self._refresh_step_debug_window()

    def _active_runtime_function_mapping(self, command_name, variable, state):
        return next((rule for rule in self.commands_assist_rules
                     if rule.get("function_replacement")
                     and rule.get("replacement_type") == "step_debug_function"
                     and rule.get("runtime_enabled", True)
                     and rule.get("command") in ("", "すべて", command_name)
                     and rule.get("variable") == variable
                     and rule.get("value") == state), None)

    def _install_function_replacement_mappings(self, command):
        """Install reviewed whole-function drafts on a fresh command instance."""
        self._pull_shared_debug(silent=True)
        command_name = str(getattr(command, "NAME", "") or "")
        installed = []
        try:
            for rule in self.commands_assist_rules:
                if not (rule.get("function_replacement")
                        and rule.get("replacement_type") == "step_debug_function"
                        and rule.get("runtime_enabled", True)
                        and rule.get("command") in ("", "すべて", command_name)):
                    continue
                variable, state = str(rule.get("variable", "")), str(rule.get("value", ""))
                mapping = getattr(command, variable, None)
                if not isinstance(mapping, dict) or state not in mapping:
                    raise ValueError("{} :: {} が実行Commandsにありません。".format(variable, state))
                codes = self._function_mapping_replacement_codes(rule)
                if not codes:
                    raise ValueError("{} の有効な置換処理がありません。".format(state))
                replacement = build_runtime_replacement_function(mapping[state], codes)
                bound = types.MethodType(replacement, command)
                marked = {"done": False}
                def tracked_replacement(_bound=bound, _rule=rule, _marked=marked):
                    if not _marked["done"]:
                        _marked["done"] = True
                        self._gui_action_queue.put(
                            lambda: self._mark_function_replacement_tested(_rule))
                    return _bound()
                mapping[state] = tracked_replacement
                installed.append("{} :: {}".format(variable, state))
        except (OSError, SyntaxError, TypeError, ValueError) as error:
            tkmsg.showerror(
                "関数置換の実動作試験", "一時置換関数を生成できませんでした。\n{}".format(error),
                parent=self.root)
            return False
        command._runtime_function_replacements = installed
        if installed:
            self.show_output(
                "Analysis", text="関数置換の実動作試験を適用: " + " / ".join(installed))
        return True

    def _mark_function_replacement_tested(self, rule):
        if rule.get("last_runtime_tested_at"):
            return
        rule["last_runtime_tested_at"] = datetime.datetime.now().isoformat(timespec="seconds")
        self._refresh_commands_assist_rule_list()
        self._sync_commands_assist_rules_to_active_input_set()
        self.show_output(
            "Analysis", text="関数置換の実動作を確認しました: {} :: {}".format(
                rule.get("variable", ""), rule.get("value", "")))

    def _matching_step_debug_rule(self, command, variable, state):
        command_name = getattr(command, "NAME", "")
        # A consolidated whole-function trial runs at production speed.  Keep
        # the saved breakpoint, but do not stop on the same state during trial.
        if self._active_runtime_function_mapping(command_name, variable, state):
            return None
        for rule in self.step_debug_rules:
            if (rule.get("enabled", True) and rule.get("variable") == variable
                    and rule.get("state") == state
                    and rule.get("command") in ("", "すべて", command_name)):
                return rule
        follow_id = getattr(command, "_step_debug_follow_rules", {}).get(variable)
        if follow_id:
            template = next((rule for rule in self.step_debug_rules
                             if str(rule.get("id")) == str(follow_id)), None)
            if template is not None:
                # Continuous Step debugging must not append the next
                # function's adjustments to the original stop rule.
                followed = derive_follow_step_rule(
                    template, command_name, variable, state, time.time_ns())
                self.step_debug_rules.append(followed)
                command._step_debug_follow_rules[variable] = followed["id"]
                return followed
        return None

    def _install_step_debug_wrappers(self, command):
        command_name = getattr(command, "NAME", "")
        variables = {rule.get("variable") for rule in self.step_debug_rules
                     if rule.get("enabled", True) and rule.get("command") in ("", "すべて", command_name)}
        command._step_debug_follow_rules = {}
        command._step_debug_originals = {}
        for variable in variables:
            mapping = getattr(command, variable, None)
            if not isinstance(mapping, dict): continue
            for state, original in list(mapping.items()):
                if not callable(original): continue
                command._step_debug_originals[(variable, state)] = original
                def wrapper(_original=original, _variable=variable, _state=state):
                    rule = self._matching_step_debug_rule(command, _variable, _state)
                    if not rule:
                        return _original()
                    return self._enter_step_debug_session(command, _variable, _state, _original, rule)
                mapping[state] = wrapper

    def _enter_step_debug_session(self, command, variable, state, method, rule):
        try:
            info = extract_step_method(method)
        except Exception as error:
            self._logger.warning("Step debug extraction failed: %s", error)
            return method()
        session = {
            "command": command, "variable": variable, "state": state, "method": method,
            "rule": rule, "info": info, "event": threading.Event(), "action": None,
            "result": None, "executed": set(), "busy": False, "tree_indices": {},
        }
        self._step_debug_pending_session = session
        while command.alive and not session["event"].wait(0.05):
            pass
        if not command.alive:
            return state
        if session.get("action") == "next":
            return session.get("result")
        return method()

    def _poll_step_debug_session(self):
        try:
            pending = self._step_debug_pending_session
            if pending is not None and pending is not self._step_debug_session:
                self._step_debug_pending_session = None
                if self._enrich_step_debug_rule(pending["rule"], pending["info"]):
                    self._write_step_debug_rules()
                self._step_debug_session = pending
                if hasattr(self, "step_debug_next_state"):
                    self.step_debug_next_state.set("")
                self.commands_assist_status.set("Stepデバッグ停止中: {} :: {}".format(
                    pending["variable"], pending["state"]))
                chunk = getattr(self, "_command_monitor_current_chunk", None)
                if chunk is not None:
                    info = pending.get("info", {})
                    location = {
                        "file": os.path.abspath(str(info.get("file", "") or "")),
                        "function": str(info.get("name", "")),
                        "line": int(info.get("first_line", 0) or 0),
                        "source": "Stepデバッグ停止地点",
                    }
                    self._write_command_monitor_event(
                        chunk, runtime_state_snapshot(pending.get("command")),
                        "step_debug_stop", location=location,
                        extra={
                            "stop_variable": str(pending.get("variable", "")),
                            "stop_state": str(pending.get("state", "")),
                        })
                # This is the useful stop notification: always show the
                # separate Step-debug window when execution reaches a stop.
                self.open_step_debug_assist()
        except (tk.TclError, RuntimeError):
            return
        self.root.after(100, self._poll_step_debug_session)

    def refresh_commands_assist_commands(self):
        os.makedirs(self._commands_assist_dir(), exist_ok=True)
        try:
            self.commands_assist_loader = FileCommandLoader(
                self._commands_assist_dir(), PythonCommandBase.PythonCommand,
                module_prefix="SerialController.CommandsAssist")
            self.commands_assist_classes = self.commands_assist_loader.load()
        except Exception as error:
            self.commands_assist_classes = []
            self._logger.warning("CommandsAssist load failed: %s", error)
        values = [command_class.NAME for command_class in self.commands_assist_classes]
        self.commands_assist_command_cb.configure(values=values)
        if self.commands_assist_recovery_command.get() not in values:
            self.commands_assist_recovery_command.set(values[0] if values else "")

    @staticmethod
    def _automation_rule_text(rule):
        scope = rule.get("command") or "すべて"
        seconds = float(rule.get("seconds", 0) or 0)
        if rule.get("kind") == "unchanged":
            condition = "{} が変化しない".format(rule.get("variable", "STEP"))
        else:
            condition = "{} == {}".format(rule.get("variable", ""), rule.get("value", ""))
        action = rule.get("action", "replace")
        if action == "pause":
            action_text = "一時停止"
        elif rule.get("replacement_type") == "step_debug_function":
            active = sum(1 for item in rule.get("replacements", {}).values()
                         if replacement_is_enabled(item))
            tested = "確認済" if rule.get("last_runtime_tested_at") else "未実行"
            action_text = "関数差分{}件 / 実動作試験{}・{}".format(
                active, "ON" if rule.get("runtime_enabled", True) else "OFF", tested)
        elif rule.get("replacement_type") == "controller_recording":
            action_text = "記録置換: {}".format(rule.get("controller_recording", ""))
        else:
            action_text = "置換: {}".format(rule.get("replacement_command") or "選択中コマンド")
        return "[{}] {} / {:.1f}秒 / {}".format(scope, condition, seconds, action_text)

    def _refresh_commands_assist_rule_list(self):
        self.commands_assist_rule_list.delete(0, "end")
        for rule in self.commands_assist_rules:
            self.commands_assist_rule_list.insert("end", self._automation_rule_text(rule))

    def _command_names_for_rules(self):
        return ["すべて"] + list(dict.fromkeys(
            list(getattr(self, "py_cb_all", [])) + list(getattr(self, "sample_py_cb_all", []))))

    def _selected_command_name(self):
        try:
            selected_tab = self.command_nb.tab(self.command_nb.select(), "text")
        except tk.TclError:
            return ""
        if selected_tab == "Python Command":
            return self.py_name.get()
        if selected_tab == "Python Sample Command":
            return self.sample_py_name.get()
        if selected_tab == "Mcu Command":
            return self.mcu_name.get()
        return ""

    def _command_classes(self, command_name=""):
        classes = list(getattr(self, "py_classes", [])) + list(getattr(self, "sample_py_classes", []))
        if command_name and command_name not in ("すべて", "All commands", "*"):
            classes = [item for item in classes if getattr(item, "NAME", "") == command_name]
        return classes

    def _state_variable_candidates(self, command_name):
        variables = set()
        for command_class in self._command_classes(command_name):
            try:
                path = inspect.getsourcefile(command_class)
                if not path or not os.path.isfile(path):
                    continue
                with open(path, "r", encoding="utf-8-sig") as stream:
                    variables.update(discover_state_variables(stream.read()))
            except (OSError, SyntaxError, TypeError):
                continue
        return sorted(variables, key=str.casefold)

    def _command_run_options(self, command_name):
        """Discover start/end/debug metadata without constructing Commands."""
        empty = {"enabled": False, "locations": [], "debug_options": [],
                 "save_recovery": {"available": False, "method": ""}}
        for command_class in self._command_classes(command_name):
            try:
                path = inspect.getsourcefile(command_class)
                if not path or not os.path.isfile(path):
                    continue
                with open(path, "r", encoding="utf-8-sig") as stream:
                    return discover_command_run_options(
                        stream.read(), class_name=command_class.__name__)
            except (OSError, SyntaxError, TypeError, ValueError):
                continue
        return empty

    def _prompt_command_run_settings(self, command_instance):
        """Show the Commands-owned Step selector after Start was requested."""
        command_name = str(getattr(command_instance, "NAME", "") or "")
        options = self._command_run_options(command_name)
        locations = list(options.get("locations", []))
        if not options.get("enabled") or not locations:
            return True

        result = {"start": False}
        saved = copy.deepcopy(self.command_start_overrides.get(command_name, {}))
        dialog = tk.Toplevel(self.root)
        dialog.title("{} - Step実行設定".format(command_name))
        dialog.geometry("1020x720")
        dialog.minsize(820, 580)
        dialog.transient(self.root)
        dialog.grab_set()

        search = tk.StringVar()
        group = tk.StringVar(value="すべて")
        start_value = tk.StringVar()
        end_value = tk.StringVar(value="（終了場所を指定しない）")
        favorite_value = tk.StringVar()
        description = tk.StringVar()
        filter_status = tk.StringVar()
        user_number = tk.IntVar(value=int(saved.get(
            "save_delete_user_number", 0) or 0))
        retry = tk.BooleanVar(value=bool(saved.get("retry_on_failure", False)))
        retries = tk.IntVar(value=max(1, int(saved.get("max_retries", 1) or 1)))
        debug_vars = {}
        display_to_location = {
            self._command_run_location_display(item): item for item in locations}

        ttk.Label(
            dialog, text="Startが押されました。実行する範囲を選択してください。",
            foreground="#174a7e").pack(anchor="w", padx=10, pady=(10, 5))
        filter_box = ttk.Labelframe(dialog, text="検索・フィルター")
        filter_box.pack(fill="x", padx=10, pady=5)
        ttk.Label(filter_box, text="文字検索:").grid(
            column=0, row=0, padx=5, pady=5, sticky="e")
        ttk.Entry(filter_box, textvariable=search).grid(
            column=1, row=0, padx=5, pady=5, sticky="ew")
        ttk.Label(filter_box, text="章／Stepグループ（任意）:").grid(
            column=2, row=0, padx=5, pady=5, sticky="e")
        raw_groups = sorted(
            {str(item.get("group", "")) for item in locations},
            key=str.casefold)
        group_display_to_raw = {"すべて": ""}
        for raw_group in raw_groups:
            display_group = raw_group
            if raw_group.startswith("STATE_") and raw_group.endswith("_FUNCTION"):
                display_group = raw_group[len("STATE_"):-len("_FUNCTION")]
            if display_group in group_display_to_raw:
                display_group = "{} ({})".format(display_group, raw_group)
            group_display_to_raw[display_group] = raw_group
        group_cb = ttk.Combobox(
            filter_box, state="readonly", textvariable=group,
            values=list(group_display_to_raw), width=32)
        group_cb.grid(column=3, row=0, padx=5, pady=5, sticky="ew")
        ttk.Label(filter_box, textvariable=filter_status).grid(
            column=4, row=0, padx=7, pady=5, sticky="w")
        filter_box.columnconfigure(1, weight=1)
        filter_box.columnconfigure(3, weight=1)

        range_box = ttk.Labelframe(dialog, text="開始・終了場所")
        range_box.pack(fill="x", padx=10, pady=5)
        ttk.Label(range_box, text="開始:").grid(
            column=0, row=0, padx=5, pady=5, sticky="e")
        start_cb = ttk.Combobox(
            range_box, state="readonly", width=78, textvariable=start_value)
        start_cb.grid(column=1, row=0, padx=5, pady=5, sticky="ew")
        ttk.Label(range_box, text="終了:").grid(
            column=0, row=1, padx=5, pady=5, sticky="e")
        end_cb = ttk.Combobox(
            range_box, state="readonly", width=78, textvariable=end_value)
        end_cb.grid(column=1, row=1, padx=5, pady=5, sticky="ew")
        ttk.Label(
            range_box, textvariable=description, justify="left",
            foreground="#174a7e", wraplength=930).grid(
                column=0, columnspan=2, row=2, padx=7, pady=(0, 6), sticky="w")
        range_box.columnconfigure(1, weight=1)

        favorite_box = ttk.Labelframe(dialog, text="お気に入り（Commandsごと・最大10件）")
        favorite_box.pack(fill="x", padx=10, pady=5)
        favorite_cb = ttk.Combobox(
            favorite_box, state="readonly", width=48,
            textvariable=favorite_value)
        favorite_cb.grid(column=0, row=0, padx=5, pady=5, sticky="ew")

        option_box = ttk.Labelframe(dialog, text="デバッグ・失敗時再実行")
        option_box.pack(fill="both", expand=True, padx=10, pady=5)
        debug_frame = ttk.Frame(option_box)
        debug_frame.pack(fill="x", padx=5, pady=3)
        saved_debug = saved.get("debug", {})
        for index, item in enumerate(options.get("debug_options", [])):
            attribute = str(item.get("attribute", item.get("id", "")))
            value = tk.BooleanVar(value=bool(
                saved_debug.get(attribute, item.get("default", False))))
            debug_vars[attribute] = value
            ttk.Checkbutton(
                debug_frame, text=str(item.get("label", attribute)),
                variable=value).grid(
                    column=index % 4, row=index // 4,
                    padx=5, pady=3, sticky="w")
        if not debug_vars:
            ttk.Label(debug_frame, text="選択可能なデバッグ項目はありません。").grid(
                column=0, row=0, padx=5, pady=3, sticky="w")
        recovery = options.get("save_recovery", {})
        recovery_row = ttk.Frame(option_box)
        recovery_row.pack(fill="x", padx=5, pady=4)
        ttk.Label(recovery_row, text="セーブ削除ユーザー番号:").pack(
            side="left", padx=(0, 3))
        ttk.Spinbox(recovery_row, from_=0, to=99, width=6,
                    textvariable=user_number).pack(side="left", padx=3)
        retry_cb = ttk.Checkbutton(
            recovery_row, text="失敗時にセーブを削除して再実行", variable=retry)
        retry_cb.pack(side="left", padx=10)
        ttk.Label(recovery_row, text="再試行:").pack(side="left", padx=(8, 2))
        ttk.Spinbox(recovery_row, from_=1, to=10, width=5,
                    textvariable=retries).pack(side="left", padx=2)
        if not recovery.get("available"):
            retry.set(False)
            retry_cb.configure(state="disabled")
            ttk.Label(
                option_box,
                text="このCommandsはセーブ削除関数を公開していないため、失敗時再実行は使用できません。",
                foreground="#8a4d00").pack(anchor="w", padx=10, pady=(0, 5))

        def find_display(location):
            location = location or {}
            return next((display for display, item in display_to_location.items()
                         if item.get("id") == location.get("id")), "")

        def refresh_description(_event=None):
            start = display_to_location.get(start_value.get(), {})
            end = display_to_location.get(end_value.get(), {})
            description.set("開始: {}\n終了: {}".format(
                start.get("description") or start.get("label") or "未選択",
                end.get("description") or end.get("label") or "指定なし"))

        def refresh_filter(*_args):
            needle = search.get().strip().casefold()
            selected_group = group_display_to_raw.get(group.get(), "")
            visible = []
            for display, item in display_to_location.items():
                haystack = "{} {} {} {}".format(
                    display, item.get("description", ""),
                    item.get("variable", ""), item.get("value", ""))
                if selected_group and str(item.get("group", "")) != selected_group:
                    continue
                if needle and needle not in haystack.casefold():
                    continue
                visible.append(display)
            start_cb.configure(values=visible)
            end_cb.configure(values=["（終了場所を指定しない）"] + visible)
            filter_status.set("{} / {}件".format(len(visible), len(locations)))
            # Filtering is only for finding the next choice. Keep selections
            # made under another chapter/search even when currently hidden.
            start_value.set(preserve_location_selection(
                start_value.get(), visible))
            end_value.set(preserve_location_selection(
                end_value.get(), visible, "（終了場所を指定しない）"))
            refresh_description()

        def current_config():
            start = copy.deepcopy(display_to_location.get(start_value.get(), {}))
            end = copy.deepcopy(display_to_location.get(end_value.get(), {}))
            if not start:
                return None
            return {
                "variable": start.get("variable", "")
                            if start.get("mode") == "state" else "",
                "state": start.get("value", "")
                         if start.get("mode") == "state" else "",
                "start": start, "end": end,
                "debug": {name: bool(value.get())
                          for name, value in debug_vars.items()},
                "save_delete_user_number": max(0, int(user_number.get() or 0)),
                "retry_on_failure": bool(retry.get() and recovery.get("available")),
                "recovery_method": str(recovery.get("method", "")),
                "max_retries": max(1, int(retries.get() or 1)),
                # This popup itself is the Start confirmation.
                "confirm": False,
            }

        def apply_config(config):
            nonlocal saved_debug
            if not isinstance(config, dict):
                return
            start_value.set(find_display(config.get("start")))
            end_value.set(find_display(config.get("end")) or
                          "（終了場所を指定しない）")
            saved_debug = config.get("debug", {})
            for name, value in debug_vars.items():
                value.set(bool(saved_debug.get(name, False)))
            user_number.set(int(config.get("save_delete_user_number", 0) or 0))
            retry.set(bool(config.get("retry_on_failure", False)
                           and recovery.get("available")))
            retries.set(max(1, int(config.get("max_retries", 1) or 1)))
            refresh_description()

        def favorites():
            return self.command_run_favorites.setdefault(command_name, [])

        def refresh_favorites(select_name=""):
            names = [str(item.get("name", "")) for item in favorites()]
            favorite_cb.configure(values=names,
                                  state="readonly" if names else "disabled")
            chosen = select_name or favorite_value.get()
            favorite_value.set(chosen if chosen in names else
                               (names[0] if names else ""))

        def selected_favorite():
            return next((item for item in favorites()
                         if str(item.get("name", "")) == favorite_value.get()), None)

        def load_favorite():
            item = selected_favorite()
            if item:
                apply_config(copy.deepcopy(item.get("config", {})))

        def add_favorite():
            from tkinter import simpledialog
            config = current_config()
            if not config:
                return
            if len(favorites()) >= 10:
                tkmsg.showwarning(
                    "Step実行お気に入り", "最大10件です。不要な項目を削除してください。",
                    parent=dialog)
                return
            name = simpledialog.askstring(
                "Step実行お気に入り", "登録名:",
                initialvalue="設定{}".format(len(favorites()) + 1), parent=dialog)
            name = str(name or "").strip()
            if not name:
                return
            if any(str(item.get("name", "")) == name for item in favorites()):
                tkmsg.showwarning(
                    "Step実行お気に入り", "同名が登録済みです。上書き変更を使用してください。",
                    parent=dialog)
                return
            favorites().append({"name": name, "config": config})
            self._sync_command_start_overrides_to_active_input_set()
            refresh_favorites(name)

        def update_favorite():
            item = selected_favorite()
            config = current_config()
            if item is None or not config:
                return
            item["config"] = config
            self._sync_command_start_overrides_to_active_input_set()

        def delete_favorite():
            item = selected_favorite()
            if item is None:
                return
            if tkmsg.askyesno(
                    "Step実行お気に入り",
                    "お気に入り「{}」を削除しますか？".format(item.get("name", "")),
                    parent=dialog):
                favorites().remove(item)
                if not favorites():
                    self.command_run_favorites.pop(command_name, None)
                self._sync_command_start_overrides_to_active_input_set()
                refresh_favorites()

        ttk.Button(favorite_box, text="呼出", command=load_favorite).grid(
            column=1, row=0, padx=3, pady=5)
        ttk.Button(favorite_box, text="新規登録", command=add_favorite).grid(
            column=2, row=0, padx=3, pady=5)
        ttk.Button(favorite_box, text="上書き変更", command=update_favorite).grid(
            column=3, row=0, padx=3, pady=5)
        ttk.Button(favorite_box, text="削除", command=delete_favorite).grid(
            column=4, row=0, padx=3, pady=5)
        favorite_box.columnconfigure(0, weight=1)

        def finish(mode):
            if mode == "apply":
                config = current_config()
                if not config:
                    tkmsg.showwarning(
                        "Step実行設定", "開始場所を選択してください。", parent=dialog)
                    return
                self.command_start_overrides[command_name] = config
                self._sync_command_start_overrides_to_active_input_set()
                result["start"] = True
            elif mode == "default":
                self.command_start_overrides.pop(command_name, None)
                self._sync_command_start_overrides_to_active_input_set()
                result["start"] = True
            dialog.destroy()

        buttons = ttk.Frame(dialog)
        buttons.pack(fill="x", padx=10, pady=(5, 10))
        ttk.Button(buttons, text="キャンセル", command=lambda: finish("cancel")).pack(
            side="right", padx=4)
        ttk.Button(buttons, text="Commands既定で開始",
                   command=lambda: finish("default")).pack(side="right", padx=4)
        ttk.Button(buttons, text="この設定で開始",
                   command=lambda: finish("apply")).pack(side="right", padx=4)
        dialog.protocol("WM_DELETE_WINDOW", lambda: finish("cancel"))
        search.trace_add("write", refresh_filter)
        group_cb.bind("<<ComboboxSelected>>", refresh_filter)
        start_cb.bind("<<ComboboxSelected>>", refresh_description)
        end_cb.bind("<<ComboboxSelected>>", refresh_description)
        refresh_filter()
        apply_config(saved if saved else {"start": locations[0]})
        refresh_favorites()
        self.root.wait_window(dialog)
        self._refresh_command_start_status()
        return bool(result["start"])

    def _selected_command_run_changed(self, _event=None):
        self._refresh_command_start_status()
        self._refresh_inline_command_run_panel()

    @staticmethod
    def _command_run_location_display(item):
        description = str(item.get("description", "") or "").strip()
        # State dictionaries are an implementation detail. Users select the
        # Step name directly; the hidden variable is applied automatically.
        text = str(item.get("label", item.get("value", "")))
        return text + (" — " + description if description else "")

    def _refresh_inline_command_run_panel(self):
        if not hasattr(self, "command_run_start_cb"):
            return
        command_name = self._selected_command_name()
        options = self._command_run_options(command_name)
        locations = options.get("locations", [])
        self._command_run_inline_locations = {
            self._command_run_location_display(item): item for item in locations}
        displays = list(self._command_run_inline_locations)
        self.command_run_start_cb.configure(
            values=displays, state="readonly" if displays else "disabled")
        self.command_run_end_cb.configure(
            values=["（終了場所を指定しない）"] + displays,
            state="readonly" if displays else "disabled")
        saved = self.command_start_overrides.get(command_name, {})
        saved_start = saved.get("start") or {}
        saved_end = saved.get("end") or {}

        def matching(location):
            return next((display for display, item in
                         self._command_run_inline_locations.items()
                         if item.get("id") == location.get("id")), "")

        start_display = matching(saved_start)
        end_display = matching(saved_end)
        self.command_run_start.set(
            start_display or (displays[0] if displays else ""))
        self.command_run_end.set(
            end_display or "（終了場所を指定しない）")
        favorites = self.command_run_favorites.get(command_name, [])
        favorite_names = [str(item.get("name", "")) for item in favorites]
        self.command_run_favorite_cb.configure(
            values=favorite_names,
            state="readonly" if favorite_names else "disabled")
        if self.command_run_favorite.get() not in favorite_names:
            self.command_run_favorite.set(favorite_names[0] if favorite_names else "")
        self._refresh_inline_command_run_description()

    def _refresh_inline_command_run_description(self, _event=None):
        if not hasattr(self, "command_run_description"):
            return
        command_name = self._selected_command_name()
        start = self._command_run_inline_locations.get(
            self.command_run_start.get(), {})
        end = self._command_run_inline_locations.get(
            self.command_run_end.get(), {})
        if not self._command_run_inline_locations:
            self.command_run_description.set(
                "{} はStep実行位置を公開していません。".format(
                    command_name or "選択中Commands"))
            return
        parts = ["開始: {}".format(start.get("description") or
                                   start.get("label") or "未選択")]
        parts.append("終了: {}".format(
            end.get("description") or end.get("label") or "指定なし"))
        self.command_run_description.set(" / ".join(parts))

    def _inline_command_run_config(self):
        command_name = self._selected_command_name()
        current = copy.deepcopy(
            self.command_start_overrides.get(command_name, {}))
        start = copy.deepcopy(self._command_run_inline_locations.get(
            self.command_run_start.get(), {}))
        end = copy.deepcopy(self._command_run_inline_locations.get(
            self.command_run_end.get(), {}))
        if not start:
            return command_name, None
        current.update({
            "variable": start.get("variable", "")
                        if start.get("mode") == "state" else "",
            "state": start.get("value", "")
                     if start.get("mode") == "state" else "",
            "start": start, "end": end,
        })
        current.setdefault("debug", {})
        current.setdefault("save_delete_user_number", 0)
        current.setdefault("retry_on_failure", False)
        current.setdefault("max_retries", 1)
        current.setdefault("confirm", True)
        return command_name, current

    def apply_inline_command_run_settings(self):
        command_name, config = self._inline_command_run_config()
        if not command_name or not config:
            tkmsg.showwarning(
                "Step実行設定", "Step対応Commandsと開始場所を選択してください。",
                parent=self.root)
            return False
        self.command_start_overrides[command_name] = config
        saved = self._sync_command_start_overrides_to_active_input_set()
        self._refresh_command_start_status()
        self._refresh_inline_command_run_description()
        if not saved:
            self.show_output(
                "Analysis", text="Step実行設定を作業中設定へ反映しました。InputSet登録時に保存されます。")
        return True

    def clear_inline_command_run_settings(self):
        command_name = self._selected_command_name()
        if not command_name:
            return
        self.command_start_overrides.pop(command_name, None)
        self._sync_command_start_overrides_to_active_input_set()
        self._refresh_command_start_status()
        self._refresh_inline_command_run_panel()

    def _selected_command_run_favorite(self):
        command_name = self._selected_command_name()
        name = self.command_run_favorite.get().strip()
        return command_name, next((item for item in
            self.command_run_favorites.get(command_name, [])
            if str(item.get("name", "")) == name), None)

    def add_command_run_favorite(self):
        from tkinter import simpledialog
        command_name, config = self._inline_command_run_config()
        if not command_name or not config:
            tkmsg.showwarning(
                "Step実行お気に入り", "先にStep対応Commandsと開始場所を選択してください。",
                parent=self.root)
            return
        favorites = self.command_run_favorites.setdefault(command_name, [])
        if len(favorites) >= 10:
            tkmsg.showwarning(
                "Step実行お気に入り", "1つのCommandsにつき最大10件です。不要な項目を削除してください。",
                parent=self.root)
            return
        name = simpledialog.askstring(
            "Step実行お気に入り", "登録名:",
            initialvalue="設定{}".format(len(favorites) + 1), parent=self.root)
        name = str(name or "").strip()
        if not name:
            return
        if any(str(item.get("name", "")) == name for item in favorites):
            tkmsg.showwarning(
                "Step実行お気に入り", "同じ名前が登録済みです。上書き変更を使用してください。",
                parent=self.root)
            return
        favorites.append({"name": name, "config": config})
        self.command_start_overrides[command_name] = copy.deepcopy(config)
        self.command_run_favorite.set(name)
        self._sync_command_start_overrides_to_active_input_set()
        self._refresh_command_start_status()
        self._refresh_inline_command_run_panel()

    def load_command_run_favorite(self):
        command_name, favorite = self._selected_command_run_favorite()
        if favorite is None:
            return
        self.command_start_overrides[command_name] = copy.deepcopy(
            favorite.get("config", {}))
        self._sync_command_start_overrides_to_active_input_set()
        self._refresh_command_start_status()
        self._refresh_inline_command_run_panel()

    def update_command_run_favorite(self):
        command_name, favorite = self._selected_command_run_favorite()
        _selected, config = self._inline_command_run_config()
        if favorite is None or not config:
            tkmsg.showwarning(
                "Step実行お気に入り", "変更するお気に入りを選択してください。",
                parent=self.root)
            return
        favorite["config"] = config
        self.command_start_overrides[command_name] = copy.deepcopy(config)
        self._sync_command_start_overrides_to_active_input_set()
        self._refresh_command_start_status()
        self._refresh_inline_command_run_panel()

    def delete_command_run_favorite(self):
        command_name, favorite = self._selected_command_run_favorite()
        if favorite is None:
            return
        if not tkmsg.askyesno(
                "Step実行お気に入り", "お気に入り「{}」を削除しますか？".format(
                    favorite.get("name", "")), parent=self.root):
            return
        favorites = self.command_run_favorites.get(command_name, [])
        favorites.remove(favorite)
        if not favorites:
            self.command_run_favorites.pop(command_name, None)
        self.command_run_favorite.set("")
        self._sync_command_start_overrides_to_active_input_set()
        self._refresh_inline_command_run_panel()

    def _refresh_command_start_status(self):
        if not hasattr(self, "command_start_status"):
            return
        command = self._selected_command_name()
        config = self.command_start_overrides.get(command, {})
        if config:
            start = config.get("start") or {}
            end = config.get("end") or {}
            start_text = (start.get("label") or start.get("value") or
                          config.get("state", ""))
            end_text = end.get("label") or end.get("value") or "指定なし"
            self.command_start_status.set(
                "実行範囲: {} → {}（{}）".format(
                    start_text or "Commands既定", end_text, command))
        elif self.command_start_overrides:
            self.command_start_status.set(
                "Step実行設定: 選択Commandsは既定 / 他{}件に設定あり".format(
                    len(self.command_start_overrides)))
        else:
            self.command_start_status.set("Step実行設定: Commands既定")
        self._refresh_inline_command_run_panel()

    def _sync_command_start_overrides_to_active_input_set(self):
        name = str(getattr(self, "_active_input_set_name", "") or "").strip()
        if not name or not hasattr(self, "input_set_name"):
            return False
        if self.input_set_name.get().strip() != name:
            return False
        data = self._read_input_sets()
        if not sync_command_start_overrides(
                data, name, self.command_start_overrides,
                favorites=self.command_run_favorites):
            return False
        self._write_input_sets(data)
        return True

    def open_command_start_settings(self):
        if not getattr(self, "_commands_loaded", False):
            tkmsg.showinfo("Step実行設定", "Commandsの読み込み完了後に設定してください。")
            return
        # Compatibility entry point for an old shortcut/menu. The former
        # state-variable screen is retired; always use the Commands-owned
        # Start popup where state variables are resolved internally.
        self.assignCommand()
        if self.cur_command is not None:
            self._prompt_command_run_settings(self.cur_command)
        return
        dialog = tk.Toplevel(self.root)
        dialog.title("選択中CommandsのStep実行詳細")
        dialog.geometry("980x850")
        dialog.transient(self.root)
        dialog.grab_set()

        command = tk.StringVar(value=self._selected_command_name())
        variable = tk.StringVar()
        state = tk.StringVar()
        search = tk.StringVar()
        start_location = tk.StringVar()
        end_location = tk.StringVar(value="（終了場所を指定しない）")
        location_description = tk.StringVar()
        confirm = tk.BooleanVar(value=True)
        save_delete_user_number = tk.IntVar(value=0)
        retry_on_failure = tk.BooleanVar(value=False)
        max_retries = tk.IntVar(value=1)
        recovery_status = tk.StringVar()
        current_text = tk.StringVar()
        debug_vars = {}
        location_by_display = {}
        run_options = {"locations": [], "debug_options": [],
                       "save_recovery": {"available": False, "method": ""}}
        command_values = [command.get()] if command.get() else []

        ttk.Label(dialog, text=(
            "通常のCommands Start時だけに使う開始・終了位置です。Pythonソースは変更しません。\n"
            "ZA状態辞書、Stepサンプル、番号付きルートを自動検出します。"),
            foreground="#174a7e", justify="left").pack(anchor="w", padx=10, pady=(10, 7))
        form = ttk.Frame(dialog)
        form.pack(fill="x", padx=10)
        ttk.Label(form, text="1. 対象Commands:").grid(column=0, row=0, padx=4, pady=5, sticky="e")
        command_combo = ttk.Combobox(
            form, textvariable=command, values=command_values,
            state="readonly", width=62)
        command_combo.grid(column=1, row=0, padx=4, pady=5, sticky="ew")
        ttk.Label(form, text="2. 開始場所:").grid(column=0, row=1, padx=4, pady=5, sticky="e")
        start_location_combo = ttk.Combobox(
            form, textvariable=start_location, state="readonly", width=62)
        start_location_combo.grid(column=1, row=1, padx=4, pady=5, sticky="ew")
        ttk.Label(form, text="3. 終了場所:").grid(column=0, row=2, padx=4, pady=5, sticky="e")
        end_location_combo = ttk.Combobox(
            form, textvariable=end_location, state="readonly", width=62)
        end_location_combo.grid(column=1, row=2, padx=4, pady=5, sticky="ew")
        ttk.Label(form, text="4. 状態変数（詳細指定）:").grid(column=0, row=3, padx=4, pady=5, sticky="e")
        variable_combo = ttk.Combobox(form, textvariable=variable, width=62)
        variable_combo.grid(column=1, row=3, padx=4, pady=5, sticky="ew")
        ttk.Label(form, text="5. 場所／Step検索:").grid(column=0, row=4, padx=4, pady=5, sticky="e")
        ttk.Entry(form, textvariable=search).grid(column=1, row=4, padx=4, pady=5, sticky="ew")
        form.columnconfigure(1, weight=1)

        ttk.Label(
            dialog, textvariable=location_description, foreground="#174a7e",
            wraplength=930, justify="left").pack(
                anchor="w", padx=14, pady=(0, 4))

        states_frame = ttk.Frame(dialog)
        states_frame.pack(fill="both", expand=True, padx=10, pady=5)
        states_scrollbar = ttk.Scrollbar(states_frame, orient="vertical")
        states = tk.Listbox(
            states_frame, exportselection=False, height=8,
            yscrollcommand=states_scrollbar.set)
        states_scrollbar.configure(command=states.yview)
        states.pack(side="left", fill="both", expand=True)
        states_scrollbar.pack(side="right", fill="y")

        def scroll_states(event):
            delta = int(getattr(event, "delta", 0))
            if delta:
                states.yview_scroll(-1 if delta > 0 else 1, "units")
                return "break"

        states.bind("<MouseWheel>", scroll_states, add="+")
        direct = ttk.Frame(dialog)
        direct.pack(fill="x", padx=10)
        ttk.Label(direct, text="選択／直接入力するStep:").pack(side="left", padx=4)
        ttk.Entry(direct, textvariable=state).pack(side="left", fill="x", expand=True, padx=4)
        ttk.Checkbutton(
            dialog, text="Start時にゲーム画面の状態確認を表示する",
            variable=confirm).pack(anchor="w", padx=14, pady=6)
        ttk.Label(dialog, textvariable=current_text, foreground="#555555").pack(
            anchor="w", padx=14, pady=(0, 4))

        option_box = ttk.Labelframe(dialog, text="デバッグ・失敗時のセーブ削除再実行")
        option_box.pack(fill="x", padx=10, pady=5)
        debug_box = ttk.Frame(option_box)
        debug_box.grid(column=0, columnspan=6, row=0, padx=5, pady=3, sticky="ew")
        ttk.Label(option_box, text="セーブ削除用ユーザー番号:").grid(
            column=0, row=1, padx=5, pady=4, sticky="e")
        ttk.Spinbox(
            option_box, from_=0, to=99, width=7,
            textvariable=save_delete_user_number).grid(
                column=1, row=1, padx=3, pady=4, sticky="w")
        retry_check = ttk.Checkbutton(
            option_box, text="失敗時にセーブを削除してやり直す",
            variable=retry_on_failure)
        retry_check.grid(column=2, row=1, padx=8, pady=4, sticky="w")
        ttk.Label(option_box, text="再試行回数:").grid(
            column=3, row=1, padx=3, pady=4, sticky="e")
        ttk.Spinbox(
            option_box, from_=1, to=10, width=6,
            textvariable=max_retries).grid(
                column=4, row=1, padx=3, pady=4, sticky="w")
        ttk.Label(
            option_box, textvariable=recovery_status,
            foreground="#8a4d00").grid(
                column=0, columnspan=6, row=2, padx=5, pady=(0, 4), sticky="w")
        option_box.columnconfigure(5, weight=1)

        visible_states = []

        def location_display(item):
            description = str(item.get("description", "")).strip()
            text = "{} / {}".format(item.get("group", ""), item.get("label", ""))
            return text + (" — " + description if description else "")

        def selected_location(value):
            return location_by_display.get(value.get(), {})

        def refresh_location_description(*_args):
            start_item = selected_location(start_location)
            end_item = selected_location(end_location)
            parts = []
            if start_item:
                parts.append("開始: {}\n{}".format(
                    start_item.get("label", ""),
                    start_item.get("description", "説明なし") or "説明なし"))
            if end_item:
                parts.append("終了: {}\n{}".format(
                    end_item.get("label", ""),
                    end_item.get("description", "説明なし") or "説明なし"))
            location_description.set("\n".join(parts))

        def choose_start_location(_event=None):
            item = selected_location(start_location)
            if item and item.get("mode") == "state":
                variable.set(str(item.get("variable", "")))
                state.set(str(item.get("value", "")))
                refresh_steps()
            refresh_location_description()

        def choose_end_location(_event=None):
            refresh_location_description()

        def refresh_current():
            saved = self.command_start_overrides.get(command.get().strip(), {})
            if saved:
                start_saved = saved.get("start") or {}
                end_saved = saved.get("end") or {}
                current_text.set("現在: {} → {} / ユーザー{} / 失敗再実行{}".format(
                    start_saved.get("label") or saved.get("state", "Commands既定"),
                    end_saved.get("label") or "終了指定なし",
                    saved.get("save_delete_user_number", 0),
                    "ON" if saved.get("retry_on_failure") else "OFF"))
            else:
                current_text.set("現在: 変更なし（Commands既定）")

        def refresh_steps(*_args):
            all_values = self._state_value_candidates(command.get().strip(), variable.get().strip())
            needle = search.get().strip().casefold()
            visible_states[:] = [value for value in all_values
                                 if not needle or needle in value.casefold()]
            states.delete(0, "end")
            for value in visible_states:
                states.insert("end", value)
            needle = search.get().strip().casefold()
            location_by_display.clear()
            displays = []
            for item in run_options.get("locations", []):
                display = location_display(item)
                location_by_display[display] = item
                searchable = "{} {} {}".format(
                    display, item.get("variable", ""), item.get("value", ""))
                if needle and needle not in searchable.casefold():
                    continue
                displays.append(display)
            start_location_combo.configure(values=displays)
            end_location_combo.configure(
                values=["（終了場所を指定しない）"] + displays)

        def refresh_debug_options(saved):
            for widget in debug_box.winfo_children():
                widget.destroy()
            debug_vars.clear()
            saved_debug = saved.get("debug", {}) if isinstance(saved, dict) else {}
            for column, item in enumerate(run_options.get("debug_options", [])):
                attribute = str(item.get("attribute", item.get("id", "")))
                value = tk.BooleanVar(value=bool(
                    saved_debug.get(attribute, item.get("default", False))))
                debug_vars[attribute] = value
                ttk.Checkbutton(
                    debug_box, text=str(item.get("label", attribute)),
                    variable=value).grid(
                        column=column, row=0, padx=5, pady=2, sticky="w")
            if not debug_vars:
                ttk.Label(debug_box, text="このCommandsに選択可能なデバッグ設定はありません。").grid(
                    column=0, row=0, sticky="w")
            recovery = run_options.get("save_recovery", {})
            if recovery.get("available"):
                retry_check.configure(state="normal")
                recovery_status.set(
                    "セーブ削除関数: {}（ユーザー番号を渡して実行）".format(
                        recovery.get("method")))
            else:
                retry_on_failure.set(False)
                retry_check.configure(state="disabled")
                recovery_status.set(
                    "セーブ削除関数が未登録のため、このCommandsでは失敗再実行をONにできません。")

        def refresh_variables(_event=None):
            nonlocal run_options
            values = self._state_variable_candidates(command.get().strip())
            variable_combo.configure(values=values)
            saved = self.command_start_overrides.get(command.get().strip(), {})
            run_options = self._command_run_options(command.get().strip())
            saved_variable = saved.get("variable", "")
            if saved_variable in values:
                variable.set(saved_variable)
            elif variable.get() not in values:
                variable.set(values[0] if values else "")
            if saved and saved.get("state"):
                state.set(saved.get("state"))
                confirm.set(bool(saved.get("confirm", True)))
            save_delete_user_number.set(int(saved.get(
                "save_delete_user_number", 0) or 0))
            retry_on_failure.set(bool(saved.get("retry_on_failure", False)))
            max_retries.set(max(1, int(saved.get(
                "max_retries", run_options.get("save_recovery", {}).get(
                    "max_retries", 1)) or 1)))
            refresh_debug_options(saved)
            refresh_steps()
            saved_start = saved.get("start") or {}
            saved_end = saved.get("end") or {}
            displays = list(location_by_display)
            start_match = next((display for display in displays
                                if location_by_display[display].get("id") ==
                                saved_start.get("id")), "")
            end_match = next((display for display in displays
                              if location_by_display[display].get("id") ==
                              saved_end.get("id")), "")
            if start_match:
                start_location.set(start_match)
            elif displays and not saved:
                start_location.set(displays[0])
            else:
                start_location.set("")
            end_location.set(end_match or "（終了場所を指定しない）")
            refresh_current()
            refresh_location_description()

        def select_state(_event=None):
            selected = states.curselection()
            if selected:
                state.set(states.get(selected[0]))

        def save():
            command_name = command.get().strip()
            variable_name = variable.get().strip()
            state_name = state.get().strip()
            start_item = copy.deepcopy(selected_location(start_location))
            end_item = copy.deepcopy(selected_location(end_location))
            if not command_name:
                tkmsg.showwarning("Step実行設定", "Commandsを選択してください。",
                                  parent=dialog)
                return
            if not start_item and (not variable_name or not state_name):
                tkmsg.showwarning("Step実行設定", "Commands、状態変数、Stepを選択してください。",
                                  parent=dialog)
                return
            if not start_item and state_name not in self._state_value_candidates(command_name, variable_name):
                tkmsg.showwarning("Step実行設定", "選択したStepが状態変数にありません。",
                                  parent=dialog)
                return
            if not start_item:
                start_item = {
                    "id": "state:{}:{}".format(variable_name, state_name),
                    "mode": "state", "kind": "state",
                    "variable": variable_name, "value": state_name,
                    "label": state_name, "description": ""}
            recovery = run_options.get("save_recovery", {})
            config = {
                "variable": (start_item.get("variable", "")
                             if start_item.get("mode") == "state" else ""),
                "state": (start_item.get("value", "")
                          if start_item.get("mode") == "state" else ""),
                "start": start_item,
                "end": end_item,
                "debug": {name: bool(value.get())
                          for name, value in debug_vars.items()},
                "save_delete_user_number": max(
                    0, int(save_delete_user_number.get() or 0)),
                "retry_on_failure": bool(
                    retry_on_failure.get() and recovery.get("available")),
                "recovery_method": str(recovery.get("method", "")),
                "max_retries": max(1, int(max_retries.get() or 1)),
                "confirm": bool(confirm.get()),
            }
            self.command_start_overrides[command_name] = config
            saved = self._sync_command_start_overrides_to_active_input_set()
            self._refresh_command_start_status()
            self._refresh_inline_command_run_panel()
            dialog.destroy()
            if not saved:
                self.show_output(
                    "Analysis", text="Step実行設定は作業中設定へ反映しました。InputSet登録時に保存されます。")

        def clear():
            command_name = command.get().strip()
            if command_name not in self.command_start_overrides:
                tkmsg.showinfo("Step実行設定", "このCommandsには削除する実行設定がありません。",
                               parent=dialog)
                return
            if not tkmsg.askyesno(
                    "Step実行設定を削除",
                    "{} の保存済みStep実行設定を削除しますか？\n\n"
                    "削除後はCommands本来のinitから開始します。".format(command_name),
                    parent=dialog):
                return
            self.command_start_overrides.pop(command_name, None)
            saved = self._sync_command_start_overrides_to_active_input_set()
            self._refresh_command_start_status()
            self._refresh_inline_command_run_panel()
            dialog.destroy()
            if not saved:
                self.show_output(
                    "Analysis", text="Step実行設定を削除しました。InputSet登録時に保存されます。")
            else:
                self.show_output(
                    "Analysis", text="Step実行設定をInputSetから削除しました: " + command_name)

        command_combo.bind("<<ComboboxSelected>>", refresh_variables)
        start_location_combo.bind("<<ComboboxSelected>>", choose_start_location)
        end_location_combo.bind("<<ComboboxSelected>>", choose_end_location)
        variable_combo.bind("<<ComboboxSelected>>", refresh_steps)
        states.bind("<<ListboxSelect>>", select_state)
        search.trace_add("write", refresh_steps)
        buttons = ttk.Frame(dialog)
        buttons.pack(fill="x", padx=10, pady=(5, 10))
        ttk.Button(buttons, text="詳しい使い方", command=self.open_command_start_guide).pack(
            side="left", padx=3)
        ttk.Button(buttons, text="この実行設定を保存", command=save).pack(side="right", padx=3)
        ttk.Button(buttons, text="Commands既定へ戻す", command=clear).pack(side="right", padx=3)
        ttk.Button(buttons, text="キャンセル", command=dialog.destroy).pack(side="right", padx=3)
        refresh_variables()

    def open_command_start_guide(self):
        path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "COMMAND_START_GUIDE.md")
        try:
            with open(path, "r", encoding="utf-8") as stream:
                content = stream.read()
        except OSError as error:
            tkmsg.showerror("Commands Step実行設定", str(error), parent=self.root)
            return
        dialog = tk.Toplevel(self.root)
        dialog.title("Commands Step実行設定 - 詳しい使い方")
        dialog.geometry("780x600")
        dialog.transient(self.root)
        viewer = tk.Text(dialog, wrap="word", padx=12, pady=10)
        viewer.pack(fill="both", expand=True)
        viewer.insert("1.0", content)
        viewer.configure(state="disabled")
        ttk.Button(dialog, text="閉じる", command=dialog.destroy).pack(pady=7)

    def _confirm_command_start_override(self, command_name, variable, state,
                                        config=None):
        """Return apply, ignore, or cancel from an explicit three-way dialog."""
        result = {"value": "cancel"}
        dialog = tk.Toplevel(self.root)
        dialog.title("Commands Step実行確認")
        dialog.transient(self.root)
        dialog.resizable(False, False)

        ttk.Label(
            dialog,
            text="{} に保存済みのStep実行設定があります。".format(command_name),
            font=("", 10, "bold"),
        ).pack(anchor="w", padx=16, pady=(15, 7))
        config = config or {}
        start = config.get("start") or {}
        end = config.get("end") or {}
        debug_enabled = [name for name, enabled in
                         (config.get("debug") or {}).items() if enabled]
        detail = "開始: {}\n終了: {}".format(
            start.get("label") or "{} :: {}".format(variable, state),
            end.get("label") or "指定なし")
        if start.get("description"):
            detail += "\n開始説明: " + str(start.get("description"))
        if end.get("description"):
            detail += "\n終了説明: " + str(end.get("description"))
        detail += "\nデバッグ: {}".format(
            ", ".join(debug_enabled) if debug_enabled else "なし")
        detail += "\nセーブ削除ユーザー: {} / 失敗再実行: {}".format(
            config.get("save_delete_user_number", 0),
            "ON" if config.get("retry_on_failure") else "OFF")
        ttk.Label(
            dialog,
            text=detail + "\n\nゲーム画面も開始場所の状態になっていますか？",
            justify="left",
        ).pack(anchor="w", padx=16, pady=(0, 12))

        def finish(value):
            result["value"] = value
            dialog.destroy()

        buttons = ttk.Frame(dialog)
        buttons.pack(fill="x", padx=12, pady=(0, 14))
        ttk.Button(
            buttons, text="設定したStepから開始",
            command=lambda: finish("apply"), width=24,
        ).pack(side="left", padx=4)
        ttk.Button(
            buttons, text="今回だけ設定を無視して通常開始",
            command=lambda: finish("ignore"), width=30,
        ).pack(side="left", padx=4)
        ttk.Button(
            buttons, text="開始をやめる",
            command=lambda: finish("cancel"), width=16,
        ).pack(side="left", padx=4)
        dialog.protocol("WM_DELETE_WINDOW", lambda: finish("cancel"))
        dialog.grab_set()
        self.root.wait_window(dialog)
        return result["value"]

    def _prepare_command_start_override(self, command):
        command_name = str(getattr(command, "NAME", "") or "")
        config = self.command_start_overrides.get(command_name)
        if not isinstance(config, dict):
            return True
        config = copy.deepcopy(config)
        if not config.get("start") and config.get("variable") and config.get("state"):
            config["start"] = {
                "id": "state:{}:{}".format(
                    config.get("variable"), config.get("state")),
                "mode": "state", "kind": "state",
                "variable": str(config.get("variable", "")),
                "value": str(config.get("state", "")),
                "label": str(config.get("state", "")),
                "description": ""}
        start = config.get("start") or {}
        variable = str(start.get("variable", config.get("variable", "")))
        state = str(start.get("value", config.get("state", "")))
        if config.get("confirm", True):
            decision = self._confirm_command_start_override(
                command_name, variable, state, config=config)
            if decision == "cancel":
                return False
            if decision == "ignore":
                # assignCommand/assignShortcutCommand creates a fresh instance,
                # so leaving it untouched uses the Commands source defaults.
                if hasattr(command, "_command_start_override_context"):
                    del command._command_start_override_context
                self.command_start_status.set(
                    "今回だけStep実行設定を無視: Commands本来のinitで開始")
                self.show_output(
                    "Analysis",
                    text="今回だけStep実行設定を無視し、Commands本来のinitで開始します: "
                         + command_name)
                return True
        try:
            assignments = apply_command_run_options(command, config)
        except (AttributeError, TypeError, ValueError) as error:
            tkmsg.showerror("Commands Step実行設定", "開始位置を設定できませんでした。\n{}".format(error),
                            parent=self.root)
            return False
        applied = " / ".join("{}={}".format(item["attribute"], item["value"])
                             for item in assignments)
        command._command_start_override_context = {
            "variable": variable,
            "state": state,
            "assignments": assignments,
            "start": start,
            "end": copy.deepcopy(config.get("end") or {}),
            "end_seen": False,
        }
        self.command_start_status.set("Step実行設定適用: " + applied)
        self.show_output("Analysis", text="Commands開始位置を設定しました: " + applied)
        return True

    def _start_command_start_monitor(self, command):
        """Show the state actually consumed by a running Commands instance."""
        context = getattr(command, "_command_start_override_context", None)
        if not isinstance(context, dict):
            return
        self._command_start_monitor_serial += 1
        serial = self._command_start_monitor_serial
        self.root.after(150, lambda: self._poll_command_start_monitor(command, context, serial))

    def _poll_command_start_monitor(self, command, context, serial):
        if serial != self._command_start_monitor_serial:
            return
        if command is not getattr(self, "cur_command", None):
            return
        variable = str(context.get("variable", ""))
        selected = str(context.get("state", ""))
        found, current, _actual = resolve_command_value(command, variable)
        main_found, main_current, _main_actual = resolve_command_value(command, "STATE_MAIN_FUNCTION")
        if found:
            current = str(current)
            if current == selected:
                progress = "開始指定どおり・処理中/画像条件待ち"
            else:
                progress = "開始指定 {} から進行済み".format(selected)
            main_text = " / MAIN: {}".format(main_current) if main_found else ""
            self.command_start_status.set(
                "現在Step: {} :: {} / {}{}".format(
                    variable, current, progress, main_text))
        else:
            self.command_start_status.set(
                "Step実行位置を確認できません: {}（開始指定: {}）".format(variable, selected))

        end = context.get("end") or {}
        if end and end.get("mode") in ("state", "attribute"):
            end_variable = str(end.get("variable", ""))
            # Numbered-route Commands such as FRLG consume stop_flag inside
            # the command itself. Other state/Step loops are stopped after the
            # selected end location has run and transitions to the next value.
            command_handles_end = bool(
                end.get("end_variable") and
                end.get("end_variable") != end_variable)
            if not command_handles_end:
                end_found, end_current, _end_actual = resolve_command_value(
                    command, end_variable)
                if end_found:
                    at_end = str(end_current) == str(end.get("value", ""))
                    if at_end:
                        context["end_seen"] = True
                    elif context.get("end_seen"):
                        command.sendStopRequest()
                        self.command_start_status.set(
                            "終了場所まで完了: {}".format(
                                end.get("label") or end.get("value")))
                        self.show_output(
                            "Analysis", text="Commands終了場所まで完了したため停止しました: " +
                            str(end.get("label") or end.get("value")))
                        return

        if bool(getattr(command, "alive", False)):
            self.root.after(250, lambda: self._poll_command_start_monitor(command, context, serial))

    def _state_value_candidates(self, command_name, variable_name):
        """Find state/Step strings from command dictionaries without running a command."""
        classes = list(getattr(self, "py_classes", [])) + list(getattr(self, "sample_py_classes", []))
        if command_name not in ("", "すべて", "All commands", "*"):
            classes = [cls for cls in classes if getattr(cls, "NAME", "") == command_name]
        target = str(variable_name or "").strip()
        values = set()
        for command_class in classes:
            try:
                path = inspect.getsourcefile(command_class)
                if not path or not os.path.isfile(path):
                    continue
                absolute_path = os.path.abspath(path)
                target_key = target.upper()
                cache_key = (absolute_path, os.path.getmtime(path), target_key)
                cached = self._state_value_cache.get(cache_key)
                if cached is not None:
                    values.update(cached)
                    continue
                with open(path, "r", encoding="utf-8-sig") as stream:
                    source = stream.read()
                found = set(discover_state_values(source, target))
                # A command reload changes mtime and used to leave the old AST
                # result behind forever.  Retain only the current revision and
                # a small cross-command working set.
                for old_key in list(self._state_value_cache):
                    if (old_key[0] == absolute_path
                            and old_key[2] == target_key
                            and old_key != cache_key):
                        self._state_value_cache.pop(old_key, None)
                self._state_value_cache[cache_key] = tuple(sorted(found))
                while len(self._state_value_cache) > 128:
                    self._state_value_cache.pop(next(iter(self._state_value_cache)))
                values.update(found)
            except (OSError, SyntaxError, TypeError):
                continue
        command = getattr(self, "cur_command", None)
        if command is not None:
            table = getattr(command, target, None)
            if isinstance(table, dict):
                values.update(str(key) for key in table)
        return sorted(values, key=str.casefold)

    def _bind_state_value_search(self, combo, value_var, command_var, variable_var):
        """Turn an editable Combobox into a filtered state-name picker."""
        def refresh(event=None):
            all_values = self._state_value_candidates(command_var.get(), variable_var.get())
            typed = value_var.get().strip().casefold()
            combo.configure(values=[value for value in all_values if not typed or typed in value.casefold()])
        combo.bind("<FocusIn>", refresh, add="+")
        combo.bind("<KeyRelease>", refresh, add="+")
        return combo

    def _edit_automation_rule_dialog(self, title, initial=None, include_kind=True):
        initial = dict(initial or {})
        dialog = tk.Toplevel(self.root)
        dialog.title(title)
        dialog.transient(self.root)
        dialog.grab_set()
        command = tk.StringVar(value=initial.get("command", "すべて"))
        kind = tk.StringVar(value=initial.get("kind", "value_stable"))
        variable = tk.StringVar(value=initial.get("variable", "STATE_1_STORY_FUNCTION"))
        value = tk.StringVar(value=initial.get("value", "1_STORY_OUT_HOTEL_Z_75"))
        seconds = tk.DoubleVar(value=initial.get("seconds", 0.0))
        action = tk.StringVar(value=initial.get("action", "pause"))
        replacement = tk.StringVar(value=initial.get(
            "replacement_command", self.commands_assist_recovery_command.get()))
        result = {}
        value_combo = ttk.Combobox(dialog, width=46, state="normal", textvariable=value)
        self._bind_state_value_search(value_combo, value, command, variable)
        row = 0
        for label, widget in (
                ("対象Commands:", ttk.Combobox(dialog, state="readonly", width=46,
                                                values=self._command_names_for_rules(), textvariable=command)),
                ("条件:", ttk.Combobox(dialog, state="readonly", width=24,
                                       values=("value_stable", "unchanged"), textvariable=kind)),
                ("変数/Step:", ttk.Entry(dialog, width=48, textvariable=variable)),
                ("一致値（入力・検索可）:", value_combo),
                ("継続秒:", ttk.Spinbox(dialog, from_=0, to=86400, increment=0.5,
                                        width=10, textvariable=seconds)),
                ("成立時の処理:", ttk.Combobox(
                    dialog, state="readonly", width=24, values=("pause", "replace"),
                    textvariable=action)),
                ("置換コマンド:", ttk.Combobox(
                    dialog, state="readonly", width=46,
                    values=[cls.NAME for cls in getattr(self, "commands_assist_classes", [])],
                    textvariable=replacement))):
            if label == "条件:" and not include_kind:
                continue
            ttk.Label(dialog, text=label).grid(column=0, row=row, padx=7, pady=4, sticky="e")
            widget.grid(column=1, row=row, padx=7, pady=4, sticky="ew")
            row += 1
        def accept():
            if not variable.get().strip():
                tkmsg.showwarning(title, "変数名またはSTEPを入力してください。", parent=dialog)
                return
            result.update({"id": initial.get("id") or str(time.time_ns()),
                           "command": command.get(), "kind": kind.get(),
                           "variable": variable.get().strip(), "value": value.get(),
                           "seconds": max(0.0, float(seconds.get())),
                           "action": action.get(),
                           "replacement_command": replacement.get()})
            dialog.destroy()
        buttons = ttk.Frame(dialog)
        buttons.grid(column=0, columnspan=2, row=row, padx=7, pady=8, sticky="e")
        ttk.Button(buttons, text="OK", command=accept).pack(side="left", padx=3)
        ttk.Button(buttons, text="キャンセル", command=dialog.destroy).pack(side="left", padx=3)
        dialog.columnconfigure(1, weight=1)
        dialog.wait_window()
        return result or None

    def add_commands_assist_rule(self):
        rule = self._edit_automation_rule_dialog("CommandsAssist 条件追加")
        if rule:
            self.commands_assist_rules.append(rule)
            self._refresh_commands_assist_rule_list()
            self._commands_assist_evaluator.reset()

    def edit_commands_assist_rule(self):
        selected = self.commands_assist_rule_list.curselection()
        if not selected:
            return
        index = selected[0]
        rule = self._edit_automation_rule_dialog("CommandsAssist 条件編集", self.commands_assist_rules[index])
        if rule:
            self.commands_assist_rules[index] = rule
            self._refresh_commands_assist_rule_list()
            self._commands_assist_evaluator.reset()

    def delete_commands_assist_rule(self):
        selected = self.commands_assist_rule_list.curselection()
        if selected:
            del self.commands_assist_rules[selected[0]]
            self._refresh_commands_assist_rule_list()
            self._commands_assist_evaluator.reset()

    def open_function_replacements(self, select_rule_id=None):
        """Bulk-map multiple state functions to independently editable replacements."""
        self._pull_shared_debug(silent=True)
        dialog = tk.Toplevel(self.root)
        dialog.title("関数置換マッピング")
        dialog.transient(self.root)
        dialog.geometry("1120x760")
        ttk.Label(
            dialog,
            text=("Stepデバッグの調整を関数にまとめ、実動作試験ONで通常Commandsを確認します。"
                  "問題がなければ、同じ差分をソースへ本反映します。"),
            foreground="#174a7e", justify="left",
        ).pack(anchor="w", padx=8, pady=(8, 2))
        listing = tk.Listbox(dialog, exportselection=False, height=10)
        listing.pack(fill="x", padx=8, pady=6)
        diff_frame = ttk.Labelframe(dialog, text="選択した関数の差分（－ 元処理 / ＋ 一時置換後）")
        diff_frame.pack(fill="both", expand=True, padx=8, pady=4)
        diff_viewer = tk.Text(diff_frame, wrap="none", font=("Consolas", 9), height=20)
        diff_y = ttk.Scrollbar(diff_frame, orient="vertical", command=diff_viewer.yview)
        diff_x = ttk.Scrollbar(diff_frame, orient="horizontal", command=diff_viewer.xview)
        diff_viewer.configure(yscrollcommand=diff_y.set, xscrollcommand=diff_x.set)
        diff_viewer.grid(column=0, row=0, sticky="nsew")
        diff_y.grid(column=1, row=0, sticky="ns")
        diff_x.grid(column=0, row=1, sticky="ew")
        diff_frame.columnconfigure(0, weight=1); diff_frame.rowconfigure(0, weight=1)
        diff_viewer.tag_configure("added", foreground="#0b6b27")
        diff_viewer.tag_configure("removed", foreground="#b00020")
        visible_rules = []

        def selected_item():
            selected = listing.curselection()
            if not selected:
                return None
            try:
                return visible_rules[selected[0]]
            except (IndexError, TypeError):
                return None

        def show_selected(event=None):
            diff_viewer.configure(state="normal")
            diff_viewer.delete("1.0", "end")
            item = selected_item()
            if item is None:
                diff_viewer.insert("1.0", "置換マッピングを選択してください。")
            else:
                _global_index, rule = item
                if rule.get("replacement_type") == "step_debug_function":
                    applied = any(item.get("applied_at") for item in
                                  rule.get("replacements", {}).values())
                    if applied and rule.get("reviewed_diff"):
                        content = "# 本反映時に確認した差分（履歴）\n" + rule["reviewed_diff"]
                    else:
                        try:
                            content = self._function_replacement_diff(rule)
                            rule["reviewed_diff"] = content
                        except (OSError, SyntaxError, TypeError, ValueError) as error:
                            saved = rule.get("reviewed_diff", "")
                            content = saved or "差分を生成できません:\n{}".format(error)
                else:
                    content = (
                        "このマッピングは関数差分ではありません。\n\n"
                        "置換形式: {}\n置換処理: {}"
                    ).format(
                        rule.get("replacement_type", "commands_assist_command"),
                        rule.get("controller_recording") or rule.get("replacement_command", ""))
                diff_viewer.insert("1.0", content)
                for line_number, line in enumerate(content.splitlines(), 1):
                    if line.startswith("+") and not line.startswith("+++"):
                        diff_viewer.tag_add("added", "{}.0".format(line_number), "{}.end".format(line_number))
                    elif line.startswith("-") and not line.startswith("---"):
                        diff_viewer.tag_add("removed", "{}.0".format(line_number), "{}.end".format(line_number))
            diff_viewer.configure(state="disabled")

        def refresh():
            visible_rules[:] = [(index, rule) for index, rule in enumerate(self.commands_assist_rules)
                                if rule.get("function_replacement")]
            listing.delete(0, "end")
            selected_index = None
            for index, (_, rule) in enumerate(visible_rules):
                listing.insert("end", self._automation_rule_text(rule))
                if select_rule_id is not None and str(rule.get("id")) == str(select_rule_id):
                    selected_index = index
            if visible_rules:
                selected_index = selected_index if selected_index is not None else 0
                listing.selection_set(selected_index)
                listing.see(selected_index)
            show_selected()

        def replacement_values(kind):
            if kind == "controller_recording":
                return sorted(self._read_controller_recordings(), key=str.casefold)
            return [cls.NAME for cls in getattr(self, "commands_assist_classes", [])]

        def add_many():
            popup = tk.Toplevel(dialog)
            popup.title("複数関数を置換へ追加")
            popup.transient(dialog)
            popup.grab_set()
            default_command = self.py_name.get() if self.py_name.get() in self._command_names_for_rules() else "すべて"
            scope = tk.StringVar(value=default_command)
            variable = tk.StringVar(value="STATE_1_STORY_FUNCTION")
            search = tk.StringVar()
            manual_state = tk.StringVar()
            kind = tk.StringVar(value="commands_assist_command")
            replacement = tk.StringVar()
            ttk.Label(popup, text="対象Commands:").grid(column=0, row=0, padx=6, pady=4, sticky="e")
            scope_combo = ttk.Combobox(popup, state="readonly", width=62,
                                       values=self._command_names_for_rules(), textvariable=scope)
            scope_combo.grid(column=1, columnspan=2, row=0, padx=6, pady=4, sticky="ew")
            ttk.Label(popup, text="状態変数:").grid(column=0, row=1, padx=6, pady=4, sticky="e")
            ttk.Entry(popup, width=64, textvariable=variable).grid(
                column=1, columnspan=2, row=1, padx=6, pady=4, sticky="ew")
            ttk.Label(popup, text="関数名検索:").grid(column=0, row=2, padx=6, pady=4, sticky="e")
            ttk.Entry(popup, width=64, textvariable=search).grid(
                column=1, columnspan=2, row=2, padx=6, pady=4, sticky="ew")
            states = tk.Listbox(popup, selectmode="extended", exportselection=False, height=13, width=88)
            states.grid(column=0, columnspan=3, row=3, padx=6, pady=5, sticky="nsew")
            ttk.Label(popup, text="一覧にない関数名を直接追加:").grid(
                column=0, row=4, padx=6, pady=4, sticky="e")
            ttk.Entry(popup, width=64, textvariable=manual_state).grid(
                column=1, columnspan=2, row=4, padx=6, pady=4, sticky="ew")
            ttk.Label(popup, text="置換元:").grid(column=0, row=5, padx=6, pady=4, sticky="e")
            kind_combo = ttk.Combobox(
                popup, state="readonly", width=26,
                values=("commands_assist_command", "controller_recording"), textvariable=kind)
            kind_combo.grid(column=1, row=5, padx=6, pady=4, sticky="w")
            replacement_combo = ttk.Combobox(popup, state="readonly", width=58, textvariable=replacement)
            replacement_combo.grid(column=1, columnspan=2, row=6, padx=6, pady=4, sticky="ew")
            ttk.Label(popup, text="置換後の処理:").grid(column=0, row=6, padx=6, pady=4, sticky="e")

            def refresh_states(*args):
                candidates = self._state_value_candidates(scope.get(), variable.get())
                needle = search.get().strip().casefold()
                states.delete(0, "end")
                for value in candidates:
                    if not needle or needle in value.casefold():
                        states.insert("end", value)

            def refresh_replacements(*args):
                values = replacement_values(kind.get())
                replacement_combo.configure(values=values)
                if replacement.get() not in values:
                    replacement.set(values[0] if values else "")

            search.trace_add("write", refresh_states)
            variable.trace_add("write", refresh_states)
            scope_combo.bind("<<ComboboxSelected>>", refresh_states)
            kind_combo.bind("<<ComboboxSelected>>", refresh_replacements)
            refresh_states()
            refresh_replacements()

            def accept():
                selected_states = [states.get(index) for index in states.curselection()]
                if manual_state.get().strip():
                    selected_states.append(manual_state.get().strip())
                selected_states = list(dict.fromkeys(selected_states))
                if not selected_states or not replacement.get():
                    tkmsg.showwarning("関数置換", "1つ以上の関数と置換後の処理を選択してください。", parent=popup)
                    return
                for offset, state in enumerate(selected_states):
                    rule = {
                        "id": str(time.time_ns() + offset), "function_replacement": True,
                        "command": scope.get(), "kind": "value_stable",
                        "variable": variable.get().strip(), "value": state, "seconds": 0.0,
                        "action": "replace", "replacement_type": kind.get(),
                        "replacement_command": replacement.get() if kind.get() == "commands_assist_command" else "",
                        "controller_recording": replacement.get() if kind.get() == "controller_recording" else "",
                    }
                    existing = next((index for index, item in enumerate(self.commands_assist_rules)
                                     if item.get("function_replacement")
                                     and item.get("command") == rule["command"]
                                     and item.get("variable") == rule["variable"]
                                     and item.get("value") == state), None)
                    if existing is None:
                        self.commands_assist_rules.append(rule)
                    else:
                        rule["id"] = self.commands_assist_rules[existing].get("id", rule["id"])
                        self.commands_assist_rules[existing] = rule
                self._commands_assist_evaluator.reset()
                self._refresh_commands_assist_rule_list()
                self._sync_commands_assist_rules_to_active_input_set()
                refresh()
                popup.destroy()

            buttons = ttk.Frame(popup)
            buttons.grid(column=0, columnspan=3, row=7, padx=6, pady=8, sticky="e")
            ttk.Button(buttons, text="選択した関数を登録", command=accept).pack(side="left", padx=3)
            ttk.Button(buttons, text="キャンセル", command=popup.destroy).pack(side="left", padx=3)
            popup.columnconfigure(1, weight=1)
            popup.rowconfigure(3, weight=1)

        def edit_selected():
            selected = listing.curselection()
            if not selected:
                return
            global_index, rule = visible_rules[selected[0]]
            if rule.get("replacement_type") == "step_debug_function":
                tkmsg.showinfo(
                    "関数置換", "この関数差分は「保存済み置換案」で編集してください。\n"
                    "編集後、Stepデバッグから再度「関数にまとめて実動作試験へ」を実行すると更新されます。",
                    parent=dialog)
                return
            popup = tk.Toplevel(dialog)
            popup.title("置換後の処理を変更: " + str(rule.get("value", "")))
            popup.transient(dialog)
            popup.grab_set()
            kind = tk.StringVar(value=rule.get("replacement_type", "commands_assist_command"))
            current = rule.get("controller_recording", "") if kind.get() == "controller_recording" \
                else rule.get("replacement_command", "")
            replacement = tk.StringVar(value=current)
            ttk.Label(popup, text="関数:").grid(column=0, row=0, padx=7, pady=5, sticky="e")
            ttk.Label(popup, text=rule.get("value", "")).grid(column=1, row=0, padx=7, pady=5, sticky="w")
            kind_combo = ttk.Combobox(popup, state="readonly", width=28, textvariable=kind,
                                      values=("commands_assist_command", "controller_recording"))
            kind_combo.grid(column=1, row=1, padx=7, pady=5, sticky="ew")
            ttk.Label(popup, text="置換元:").grid(column=0, row=1, padx=7, pady=5, sticky="e")
            replacement_combo = ttk.Combobox(popup, state="readonly", width=56, textvariable=replacement)
            replacement_combo.grid(column=1, row=2, padx=7, pady=5, sticky="ew")
            ttk.Label(popup, text="置換後の処理:").grid(column=0, row=2, padx=7, pady=5, sticky="e")
            def update_values(event=None):
                values = replacement_values(kind.get())
                replacement_combo.configure(values=values)
                if replacement.get() not in values:
                    replacement.set(values[0] if values else "")
            kind_combo.bind("<<ComboboxSelected>>", update_values)
            update_values()
            def accept():
                if not replacement.get():
                    return
                updated = dict(rule)
                updated.update({"replacement_type": kind.get(),
                                "replacement_command": replacement.get() if kind.get() == "commands_assist_command" else "",
                                "controller_recording": replacement.get() if kind.get() == "controller_recording" else ""})
                self.commands_assist_rules[global_index] = updated
                self._refresh_commands_assist_rule_list()
                self._commands_assist_evaluator.reset()
                self._sync_commands_assist_rules_to_active_input_set()
                refresh()
                popup.destroy()
            ttk.Button(popup, text="更新", command=accept).grid(column=1, row=3, padx=7, pady=8, sticky="e")
            popup.columnconfigure(1, weight=1)

        def delete_selected():
            selected = listing.curselection()
            if not selected:
                return
            global_index, rule = visible_rules[selected[0]]
            if not tkmsg.askyesno("関数置換", "{} の置換設定を削除しますか？".format(rule.get("value", "")), parent=dialog):
                return
            del self.commands_assist_rules[global_index]
            self._refresh_commands_assist_rule_list()
            self._commands_assist_evaluator.reset()
            self._sync_commands_assist_rules_to_active_input_set()
            refresh()

        def toggle_runtime_trial():
            item = selected_item()
            if item is None:
                return
            _global_index, rule = item
            if rule.get("replacement_type") != "step_debug_function":
                tkmsg.showinfo(
                    "関数置換", "この切り替えはStepデバッグから作成した関数差分用です。",
                    parent=dialog)
                return
            rule["runtime_enabled"] = not bool(rule.get("runtime_enabled", True))
            self._refresh_commands_assist_rule_list()
            self._sync_commands_assist_rules_to_active_input_set()
            refresh()

        def apply_selected_to_source():
            item = selected_item()
            if item is None:
                return
            _global_index, rule = item
            if rule.get("replacement_type") != "step_debug_function":
                tkmsg.showinfo(
                    "関数置換", "ソース差分を持つStepデバッグ関数置換を選択してください。",
                    parent=dialog)
                return
            if not rule.get("last_runtime_tested_at") and not tkmsg.askyesno(
                    "実動作が未確認です",
                    "この関数置換は通常Commandsでまだ実行されていません。\n"
                    "実動作試験をせずにソース反映へ進みますか？",
                    parent=dialog):
                return
            if self._apply_step_debug_rule_to_source(
                    self._function_mapping_as_step_rule(rule), dialog):
                rule["runtime_enabled"] = False
                source_rule_id = str(rule.get("step_debug_rule_id", ""))
                source_rule = next((candidate for candidate in self.step_debug_rules
                                    if str(candidate.get("id", "")) == source_rule_id), None)
                if source_rule is not None:
                    for operation_id, applied in rule.get("replacements", {}).items():
                        if not applied.get("applied_at"):
                            continue
                        original = source_rule.get("replacements", {}).get(operation_id)
                        if isinstance(original, dict):
                            original.update({key: applied[key] for key in
                                             ("enabled", "applied_at", "applied_to")
                                             if key in applied})
                    self._write_step_debug_rules()
                self._sync_commands_assist_rules_to_active_input_set()
                refresh()

        actions = ttk.Frame(dialog)
        actions.pack(fill="x", padx=8, pady=(0, 8))
        ttk.Button(actions, text="複数関数を追加…", command=add_many).pack(side="left", padx=3)
        ttk.Button(actions, text="選択した置換処理を編集", command=edit_selected).pack(side="left", padx=3)
        ttk.Button(actions, text="実動作試験 ON／OFF", command=toggle_runtime_trial).pack(side="left", padx=12)
        ttk.Button(actions, text="差分どおりソースへ本反映…",
                   command=apply_selected_to_source).pack(side="left", padx=3)
        ttk.Button(actions, text="削除", command=delete_selected).pack(side="right", padx=3)
        ttk.Button(actions, text="閉じる", command=dialog.destroy).pack(side="right", padx=3)
        listing.bind("<Double-1>", lambda event: edit_selected())
        listing.bind("<<ListboxSelect>>", show_selected)
        refresh()

    def open_recording_variable_rules(self):
        """Edit paired start/end rules; each pair may target one or all commands."""
        dialog = tk.Toplevel(self.root)
        dialog.title("Recording 複数変数条件")
        dialog.transient(self.root)
        dialog.grab_set()
        rule_list = tk.Listbox(dialog, height=8, width=110, exportselection=False)
        rule_list.grid(column=0, columnspan=4, row=0, padx=8, pady=7, sticky="nsew")

        def text_for(rule):
            discard = " / 破棄: {} ({:.1f}秒)".format(
                rule.get("discard_value", ""), float(rule.get("discard_seconds", 0) or 0)) \
                if rule.get("discard_value") else ""
            followup = " / 終了後CommandsAssist" if rule.get("assist_rule_id") else ""
            return "[{}] {} == {} ({:.1f}秒)  →  {} == {} ({:.1f}秒){}{}".format(
                rule.get("command") or "すべて", rule.get("variable", ""),
                rule.get("start_value", ""), float(rule.get("start_seconds", 0) or 0),
                rule.get("variable", ""), rule.get("stop_value", ""),
                float(rule.get("stop_seconds", 0) or 0), discard, followup)

        def refresh():
            rule_list.delete(0, "end")
            for item in self.record_variable_rules:
                rule_list.insert("end", text_for(item))

        def edit_rule(initial=None):
            initial = dict(initial or {})
            popup = tk.Toplevel(dialog)
            popup.title("録画開始・終了条件")
            popup.transient(dialog)
            popup.grab_set()
            scope = tk.StringVar(value=initial.get("command", "すべて"))
            variable = tk.StringVar(value=initial.get("variable", "STATE_1_STORY_FUNCTION"))
            start_value = tk.StringVar(value=initial.get("start_value", "1_STORY_OUT_HOTEL_Z_72"))
            start_seconds = tk.DoubleVar(value=initial.get("start_seconds", 0.0))
            stop_value = tk.StringVar(value=initial.get("stop_value", "1_STORY_OUT_HOTEL_Z_75"))
            stop_seconds = tk.DoubleVar(value=initial.get("stop_seconds", 1.0))
            discard_value = tk.StringVar(value=initial.get("discard_value", "1_STORY_OUT_HOTEL_Z_76"))
            discard_seconds = tk.DoubleVar(value=initial.get("discard_seconds", 0.0))
            assist_labels = ["なし"] + [self._automation_rule_text(rule) for rule in self.commands_assist_rules]
            assist_ids = [""] + [str(rule.get("id", "")) for rule in self.commands_assist_rules]
            current_assist_id = str(initial.get("assist_rule_id", ""))
            assist_index = assist_ids.index(current_assist_id) if current_assist_id in assist_ids else 0
            assist_rule = tk.StringVar(value=assist_labels[assist_index])
            result = {}
            start_combo = ttk.Combobox(popup, textvariable=start_value, width=74, state="normal")
            stop_combo = ttk.Combobox(popup, textvariable=stop_value, width=74, state="normal")
            discard_combo = ttk.Combobox(popup, textvariable=discard_value, width=74, state="normal")
            for combo, value_var in ((start_combo, start_value), (stop_combo, stop_value),
                                     (discard_combo, discard_value)):
                self._bind_state_value_search(combo, value_var, scope, variable)
            fields = [
                ("対象Commands:", ttk.Combobox(popup, state="readonly", values=self._command_names_for_rules(), textvariable=scope, width=48)),
                ("変数:", ttk.Entry(popup, textvariable=variable, width=50)),
                ("開始値（入力・検索可）:", start_combo),
                ("開始値の継続秒:", ttk.Spinbox(popup, from_=0, to=86400, increment=0.5, textvariable=start_seconds, width=10)),
                ("終了値（入力・検索可）:", stop_combo),
                ("終了値の継続秒:", ttk.Spinbox(popup, from_=0, to=86400, increment=0.5, textvariable=stop_seconds, width=10)),
                ("録画破棄値（入力・検索可）:", discard_combo),
                ("破棄値の継続秒:", ttk.Spinbox(popup, from_=0, to=86400, increment=0.5, textvariable=discard_seconds, width=10)),
                ("正常終了後:", ttk.Combobox(popup, state="readonly", values=assist_labels,
                                               textvariable=assist_rule, width=76)),
            ]
            for row, (label, widget) in enumerate(fields):
                ttk.Label(popup, text=label).grid(column=0, row=row, padx=7, pady=4, sticky="e")
                widget.grid(column=1, row=row, padx=7, pady=4, sticky="ew")
            def accept():
                if not variable.get().strip() or not start_value.get() or not stop_value.get():
                    tkmsg.showwarning("Recording", "変数・開始値・終了値を入力してください。", parent=popup)
                    return
                result.update({"id": initial.get("id") or str(time.time_ns()),
                               "command": scope.get(), "variable": variable.get().strip(),
                               "start_value": start_value.get(), "start_seconds": max(0.0, float(start_seconds.get())),
                               "stop_value": stop_value.get(), "stop_seconds": max(0.0, float(stop_seconds.get())),
                               "discard_value": discard_value.get(),
                               "discard_seconds": max(0.0, float(discard_seconds.get())),
                               "assist_rule_id": assist_ids[assist_labels.index(assist_rule.get())]
                               if assist_rule.get() in assist_labels else ""})
                popup.destroy()
            buttons = ttk.Frame(popup)
            buttons.grid(column=0, columnspan=2, row=len(fields), padx=7, pady=8, sticky="e")
            ttk.Button(buttons, text="OK", command=accept).pack(side="left", padx=3)
            ttk.Button(buttons, text="キャンセル", command=popup.destroy).pack(side="left", padx=3)
            popup.columnconfigure(1, weight=1)
            popup.wait_window()
            return result or None

        def add():
            item = edit_rule()
            if item:
                self.record_variable_rules.append(item)
                refresh()

        def change():
            selected = rule_list.curselection()
            if not selected:
                return
            item = edit_rule(self.record_variable_rules[selected[0]])
            if item:
                self.record_variable_rules[selected[0]] = item
                refresh()

        def delete():
            selected = rule_list.curselection()
            if selected:
                del self.record_variable_rules[selected[0]]
                refresh()
        ttk.Button(dialog, text="追加", command=add).grid(column=0, row=1, padx=4, pady=6)
        ttk.Button(dialog, text="編集", command=change).grid(column=1, row=1, padx=4, pady=6)
        ttk.Button(dialog, text="削除", command=delete).grid(column=2, row=1, padx=4, pady=6)
        ttk.Button(dialog, text="閉じる", command=dialog.destroy).grid(column=3, row=1, padx=4, pady=6)
        ttk.Label(dialog, text="開始は各条件のOR。開始後は同じ組の終了・破棄条件を監視し、正常終了時だけCommandsAssistへ接続できます。").grid(
            column=0, columnspan=4, row=2, padx=8, pady=(0, 7), sticky="w")
        dialog.columnconfigure(0, weight=1)
        dialog.rowconfigure(0, weight=1)
        refresh()

    def _reset_commands_assist_monitor(self):
        self._commands_assist_evaluator.reset()
        self._commands_assist_suppressed_rule_id = None
        self.commands_assist_status.set("監視中" if self.commands_assist_enabled.get() else "停止中")

    def _commands_assist_tick(self):
        try:
            if self._commands_assist_busy and self._commands_assist_recovery_done:
                self._commands_assist_recovery_done = False
                self._finish_commands_assist()
            command = getattr(self, "cur_command", None)
            running = command is not None and self.start_button["text"] == "Stop"
            if (self.commands_assist_enabled.get() and not self._commands_assist_busy and running
                    and self._step_debug_session is None
                    and self._step_debug_pending_session is None):
                command_name = getattr(command, "NAME", "")
                for rule in self.commands_assist_rules:
                    # Whole-function Step-debug drafts are installed directly
                    # into the fresh command dispatch table at Start.
                    if rule.get("replacement_type") == "step_debug_function":
                        continue
                    # An exact Step-debug breakpoint stops at the function
                    # boundary and therefore takes precedence over the older
                    # polling pause for the same state.
                    if self._matching_step_debug_rule(
                            command, rule.get("variable", ""), rule.get("value", "")):
                        continue
                    result = self._commands_assist_evaluator.evaluate(rule, command, command_name)
                    rule_id = str(rule.get("id"))
                    if rule_id == self._commands_assist_suppressed_rule_id:
                        if not result["triggered"]:
                            self._commands_assist_suppressed_rule_id = None
                        continue
                    if result["triggered"]:
                        self._commands_assist_suppressed_rule_id = rule_id
                        self._begin_commands_assist(rule, result)
                        break
        except (tk.TclError, RuntimeError):
            return
        except Exception as error:
            self._logger.warning("CommandsAssist monitor failed: %s", error)
        self.root.after(250, self._commands_assist_tick)

    def _begin_commands_assist(self, rule, result):
        self._commands_assist_busy = True
        self._commands_assist_triggered_rule = rule
        self._commands_assist_original_command = getattr(self, "cur_command", None)
        self._commands_assist_original_name = getattr(self._commands_assist_original_command, "NAME", "")
        command = self._commands_assist_original_command
        if command is None:
            self._commands_assist_busy = False
            return
        if self._software_controller_paused_command is command:
            # The condition pause takes ownership; releasing a manual button
            # must not accidentally resume this Step.
            self._software_controller_paused_command = None
        if hasattr(command, "request_pause"):
            command.request_pause()
        else:
            command.pause_requested = True
        action = rule.get("action", "replace")
        self.commands_assist_resume_button["state"] = "normal"
        if action == "pause":
            self._commands_assist_busy = False
            self.commands_assist_status.set("条件成立: {} / Step位置で一時停止中".format(
                self._automation_rule_text(rule)))
            return
        if rule.get("replacement_type") == "controller_recording":
            recording_name = rule.get("controller_recording", "")
            item = self._read_controller_recordings().get(recording_name)
            if not item:
                self._commands_assist_busy = False
                self.commands_assist_status.set(
                    "コントローラー記録「{}」が見つかりません（元コマンドは一時停止中）。".format(recording_name))
                return
            self._commands_assist_recovery_done = False
            self.commands_assist_status.set("元コマンドを一時停止 / 記録置換を再生中: " + recording_name)
            def replay_worker():
                try:
                    replay_recording(item.get("lines", []), self.ser,
                                     should_continue=lambda: self._commands_assist_busy)
                except Exception as error:
                    self._logger.warning("Controller recording replacement failed: %s", error)
                finally:
                    self._commands_assist_recovery_done = True
            threading.Thread(target=replay_worker, daemon=True,
                             name="ControllerRecordingReplacement").start()
            return
        selected = rule.get("replacement_command") or self.commands_assist_recovery_command.get()
        matches = [cls for cls in self.commands_assist_classes if cls.NAME == selected]
        if not matches:
            self._commands_assist_busy = False
            self.commands_assist_status.set("置換コマンドを選択して再読込してください（元コマンドは一時停止中）。")
            return
        recovery = matches[0]()
        # A replacement must run even if the toolbar's global Pause is on.
        recovery.isPause = False
        recovery.pause_requested = False
        self._commands_assist_recovery = recovery
        self._commands_assist_recovery_done = False
        self.commands_assist_status.set("元コマンドを一時停止 / 置換処理実行中: " + selected)
        def run_recovery():
            try:
                recovery.alive = True
                recovery.do_safe(self.ser)
            finally:
                try:
                    if getattr(recovery, "keys", None) is not None:
                        recovery.keys.end()
                except Exception:
                    pass
                self._commands_assist_recovery_done = True
        recovery.thread = threading.Thread(target=run_recovery, daemon=True, name="CommandsAssistReplacement")
        recovery.thread.start()

    def _finish_commands_assist(self):
        command = getattr(self, "_commands_assist_original_command", None)
        if command is not None:
            if hasattr(command, "resume"):
                command.resume()
            else:
                command.pause_requested = False
        self._commands_assist_busy = False
        self.commands_assist_resume_button["state"] = "disabled"
        self.commands_assist_status.set("置換処理完了 / 同じStep位置から再開")

    def resume_commands_assist(self):
        command = getattr(self, "_commands_assist_original_command", None) or getattr(self, "cur_command", None)
        if command is not None:
            if hasattr(command, "resume"):
                command.resume()
            else:
                command.pause_requested = False
        self._commands_assist_busy = False
        self.commands_assist_resume_button["state"] = "disabled"
        self.commands_assist_status.set("手動再開しました。")

    def _resize_input_set_content(self, event):
        self.input_set_canvas.itemconfigure(self.input_set_canvas_window, width=max(1, event.width))

    def _scroll_input_set_with_wheel(self, event):
        canvas = getattr(self, "input_set_canvas", None)
        if canvas is None or not canvas.winfo_exists():
            return
        x, y = self.root.winfo_pointerx(), self.root.winfo_pointery()
        if not (canvas.winfo_rootx() <= x < canvas.winfo_rootx() + canvas.winfo_width() and
                canvas.winfo_rooty() <= y < canvas.winfo_rooty() + canvas.winfo_height()):
            return
        canvas.yview_scroll(-1 if event.delta > 0 else 1, "units")
        return "break"

    def refresh_command_watch_commands(self):
        if not hasattr(self, "command_watch_command_cb"):
            return
        values = list(getattr(self, "py_cb_all", [])) + list(getattr(self, "sample_py_cb_all", []))
        self.command_watch_command_cb.configure(values=values)
        if values and self.command_watch_command.get() not in values:
            self.command_watch_command.set(values[0])
        if hasattr(self, "record_variable_command_cb"):
            self.record_variable_command_cb.configure(values=values)
            if values and self.record_variable_command.get() not in values:
                self.record_variable_command.set(values[0])

    def open_image_match_debug(self):
        """Inspect a command's declared images without starting the command."""
        existing = getattr(self, "image_match_debug_dialog", None)
        if existing is not None and existing.winfo_exists():
            existing.focus_force()
            return
        dialog = tk.Toplevel(self.root)
        dialog.title("Image match debug")
        dialog.transient(self.root)
        self.image_match_debug_dialog = dialog
        self.image_match_debug_active = False
        self.image_match_debug_templates = {}
        self.image_match_debug_worker_running = False
        self.image_match_debug_generation = 0
        self.image_match_debug_command = tk.StringVar(value=self.py_cb.get() if hasattr(self, "py_cb") else "")
        self.image_match_debug_output = tk.StringVar(value="Output#2")
        self.image_match_debug_status = tk.StringVar(value="Select a command that implements get_detection_targets().")
        ttk.Label(dialog, text="Command:").grid(column=0, row=0, padx=6, pady=5, sticky="w")
        ttk.Combobox(dialog, state="readonly", width=48, textvariable=self.image_match_debug_command,
                     values=list(getattr(self, "py_cb_all", [])) + list(getattr(self, "sample_py_cb_all", []))).grid(column=1, columnspan=2, row=0, padx=6, pady=5, sticky="ew")
        ttk.Label(dialog, text="Log output:").grid(column=0, row=1, padx=6, pady=5, sticky="w")
        ttk.Combobox(dialog, state="readonly", width=14, textvariable=self.image_match_debug_output,
                     values=("Output#1", "Output#2")).grid(column=1, row=1, padx=6, pady=5, sticky="w")
        self.image_match_debug_button_popup = ttk.Button(dialog, text="Start monitoring", command=self.toggle_image_match_debug)
        self.image_match_debug_button_popup.grid(column=2, row=1, padx=6, pady=5)
        ttk.Label(dialog, textvariable=self.image_match_debug_status).grid(column=0, columnspan=3, row=2, padx=6, pady=(0, 6), sticky="w")
        dialog.protocol("WM_DELETE_WINDOW", self.close_image_match_debug)

    def close_image_match_debug(self):
        self.image_match_debug_active = False
        self.image_match_debug_generation = getattr(
            self, "image_match_debug_generation", 0) + 1
        dialog = getattr(self, "image_match_debug_dialog", None)
        if dialog is not None and dialog.winfo_exists():
            dialog.destroy()

    def toggle_image_match_debug(self):
        self.image_match_debug_active = not self.image_match_debug_active
        self.image_match_debug_generation = getattr(
            self, "image_match_debug_generation", 0) + 1
        if self.image_match_debug_active:
            self.image_match_debug_button_popup.configure(text="Stop monitoring")
            self.poll_image_match_debug()
        else:
            self.image_match_debug_button_popup.configure(text="Start monitoring")

    def poll_image_match_debug(self):
        dialog = getattr(self, "image_match_debug_dialog", None)
        if not getattr(self, "image_match_debug_active", False) or dialog is None or not dialog.winfo_exists():
            return
        delay = max(500, int(round(500 * self._resource_preview_multiplier())))
        if getattr(self, "image_match_debug_worker_running", False):
            self.root.after(delay, self.poll_image_match_debug)
            return
        selected = self.image_match_debug_command.get()
        command_class = next((
            item for item in list(getattr(self, "py_classes", [])) +
            list(getattr(self, "sample_py_classes", []))
            if item.NAME == selected), None)
        frame = getattr(self.camera, "image_bgr", None)
        if command_class is None:
            self.image_match_debug_status.set(
                "Command was not found. Reload Commands and select it again.")
            self.root.after(delay, self.poll_image_match_debug)
            return
        if frame is None:
            self.image_match_debug_status.set("Waiting for a camera frame.")
            self.root.after(delay, self.poll_image_match_debug)
            return

        generation = self.image_match_debug_generation
        output = self.image_match_debug_output.get()
        self.image_match_debug_worker_running = True

        def worker():
            try:
                targets = command_class.get_detection_targets()
                if not targets:
                    result = ([], "This command has no declared image targets.")
                else:
                    rows = ["[Image match debug] " + selected]
                    for target in targets:
                        name = str(target.get(
                            "name", os.path.basename(target.get("path", "target"))))
                        path = target.get("path", "")
                        image = self.image_match_debug_templates.get(path)
                        if image is None and path:
                            image = cv2.imread(path, cv2.IMREAD_COLOR)
                            self.image_match_debug_templates[path] = image
                        if image is None:
                            rows.append("{}: template missing ({})".format(name, path))
                            continue
                        x, y, width, height = target.get("roi", (0, 0, 0, 0))
                        height_frame, width_frame = frame.shape[:2]
                        reference_width, reference_height = target.get(
                            "reference_resolution", (0, 0))
                        reference_width = int(reference_width or 0)
                        reference_height = int(reference_height or 0)
                        scale_x = float(width_frame) / reference_width if reference_width else 1.0
                        scale_y = float(height_frame) / reference_height if reference_height else 1.0
                        x = max(0, int(round(int(x) * scale_x)))
                        y = max(0, int(round(int(y) * scale_y)))
                        width = (int(round(int(width) * scale_x)) if int(width)
                                 else width_frame - x)
                        height = (int(round(int(height) * scale_y)) if int(height)
                                  else height_frame - y)
                        region = frame[
                            y:min(height_frame, y + height),
                            x:min(width_frame, x + width)]
                        if region.size == 0:
                            rows.append("{}: ROI is outside the camera frame".format(name))
                            continue
                        scaled_image = image
                        if reference_width or reference_height:
                            scaled_image = cv2.resize(image, (
                                max(1, int(round(image.shape[1] * scale_x))),
                                max(1, int(round(image.shape[0] * scale_y)))))
                        if target.get("grayscale", False):
                            region = cv2.cvtColor(region, cv2.COLOR_BGR2GRAY)
                            scaled_image = cv2.cvtColor(
                                scaled_image, cv2.COLOR_BGR2GRAY)
                        if (region.shape[0] < scaled_image.shape[0] or
                                region.shape[1] < scaled_image.shape[1]):
                            rows.append("{}: ROI is smaller than template".format(name))
                            continue
                        _, score, _, _ = cv2.minMaxLoc(cv2.matchTemplate(
                            region, scaled_image, cv2.TM_CCOEFF_NORMED))
                        threshold = float(target.get("threshold", 0.8))
                        rows.append("{}: {:.1f}% / {:.1f}% {}".format(
                            name, score * 100, threshold * 100,
                            "MATCH" if score >= threshold else "NO MATCH"))
                    result = (
                        rows,
                        "Monitoring {} target(s) every {:.1f} s.".format(
                            len(targets), delay / 1000.0))
                callback = lambda: self._finish_image_match_debug(
                    generation, output, result[0], result[1])
            except Exception as error:
                callback = lambda error=error: self._finish_image_match_debug(
                    generation, output, [], "Image debug error: " + str(error))
            self._gui_action_queue.put(callback)

        threading.Thread(
            target=worker, daemon=True, name="ImageMatchDebug").start()
        self.root.after(delay, self.poll_image_match_debug)

    def _finish_image_match_debug(self, generation, output, rows, status):
        self.image_match_debug_worker_running = False
        if (generation != getattr(self, "image_match_debug_generation", -1)
                or not getattr(self, "image_match_debug_active", False)):
            return
        if rows:
            self.show_output(output, text="\n".join(rows))
        self.image_match_debug_status.set(status)

    def add_command_watch_variable(self):
        name = self.command_watch_variable.get().strip()
        if name and name not in self.command_watch_variables:
            self.command_watch_variables.append(name)
            self.command_watch_list.insert("end", name)
            self.command_watch_variable.set("")
            self.reset_command_watch()

    def remove_command_watch_variable(self):
        selected = self.command_watch_list.curselection()
        if selected:
            index = selected[0]
            del self.command_watch_variables[index]
            self.command_watch_list.delete(index)
            self.reset_command_watch()

    def reset_command_watch(self):
        if hasattr(self, "command_watch_last_values"):
            self.command_watch_last_values = {}

    def clear_execution_path_snapshots(self):
        tree = getattr(self, "execution_path_tree", None)
        if tree is None:
            return
        for item in tree.get_children(""):
            tree.delete(item)
        self.execution_path_status.set(
            "履歴を消去しました。［現在位置を取得］で新しい位置を取得できます。")

    def capture_execution_path_snapshot(self):
        """Sample the Commands worker once; never install continuous tracing."""
        command = getattr(self, "cur_command", None)
        project_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
        snapshot = runtime_execution_snapshot(command, project_root)
        command_name = snapshot.get("command") or "停止中"
        self.execution_path_command.set("実行Commands: " + command_name)
        step_path = snapshot.get("step_path") or "Step取得待ち"
        self.execution_path_step.set("Step: " + step_path)
        if not snapshot.get("running"):
            self.execution_path_status.set(
                "Commandsは現在実行されていません。Start後にもう一度取得してください。")
            return

        location = snapshot.get("location") or {}
        stack = list(location.get("stack") or ([] if not location else [location]))
        captured = datetime.datetime.now().strftime("%H:%M:%S.%f")[:-3]
        root_item = self.execution_path_tree.insert(
            "", 0, text="{}  {}".format(captured, step_path),
            values=(command_name, "", ""), open=True)
        for depth, frame in enumerate(stack):
            source_file = os.path.abspath(str(frame.get("file", "") or ""))
            try:
                display_file = os.path.relpath(source_file, project_root)
            except (OSError, ValueError):
                display_file = source_file
            line = int(frame.get("line", 0) or 0)
            self.execution_path_tree.insert(
                root_item, "end", text="現在" if depth == 0 else "呼出元 {}".format(depth),
                values=(
                    str(frame.get("function", "")),
                    "{} : {}".format(display_file, line),
                    str(frame.get("source", ""))),
                tags=("current",) if depth == 0 else ())
        roots = self.execution_path_tree.get_children("")
        for old_item in roots[30:]:
            self.execution_path_tree.delete(old_item)
        if stack:
            current = stack[0]
            self.execution_path_status.set(
                "取得完了: {}（{}行） / 履歴 {}件".format(
                    current.get("function", ""), current.get("line", 0),
                    min(30, len(roots))))
        else:
            self.execution_path_status.set(
                "Commandsは実行中ですが、プロジェクト内の実行位置を取得できませんでした。")

    def start_execution_path_trace(self):
        if self._execution_path_trace_active:
            return
        command = getattr(self, "cur_command", None)
        project_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
        snapshot = runtime_execution_snapshot(command, project_root)
        if not snapshot.get("running"):
            self.execution_path_status.set(
                "Commandsは現在実行されていません。Start後に経路記録を開始してください。")
            return
        trace_root = os.path.dirname(os.path.abspath(__file__))
        request_trace = getattr(command, "request_execution_path_trace", None)
        if not callable(request_trace) or not request_trace(
                duration=10.0, project_root=trace_root):
            self.execution_path_status.set(
                "経路記録を開始できません。PokeCon再起動後、Commands実行中に再試行してください。")
            return
        self._execution_path_trace_active = True
        self._execution_path_trace_command = command
        self._execution_path_trace_started = time.monotonic()
        self._execution_path_trace_started_wall = datetime.datetime.now().isoformat(
            timespec="milliseconds")
        self._execution_path_trace_events = []
        self._execution_path_trace_last_status = 0.0
        self._execution_path_stop_reason = ""
        self.execution_path_start_button.configure(state="disabled")
        self.execution_path_stop_button.configure(state="normal")
        self.execution_path_devstudio_button.configure(state="disabled")
        self.execution_path_command.set(
            "実行Commands: " + (snapshot.get("command") or "取得待ち"))
        self.execution_path_status.set(
            "経路記録を開始しました。約10秒間、実際に通った行を連続収集します。")
        self._poll_execution_path_trace()

    def _poll_execution_path_trace(self):
        self._execution_path_trace_after_id = None
        if not self._execution_path_trace_active:
            return
        command = self._execution_path_trace_command
        trace_snapshot = command.execution_path_trace_snapshot(include_events=False)
        now = time.monotonic()
        elapsed = max(0.0, now - self._execution_path_trace_started)
        if trace_snapshot.get("complete"):
            self._complete_execution_path_trace()
            return
        worker = getattr(command, "thread", None)
        if (command is not getattr(self, "cur_command", None)
                or worker is None or not worker.is_alive()):
            self._execution_path_stop_reason = "Commands終了により自動停止"
            command.request_execution_path_trace_stop()
            if not trace_snapshot.get("active") and not trace_snapshot.get("requested"):
                self._complete_execution_path_trace()
                return
        if now - self._execution_path_trace_last_status >= 0.5:
            self._execution_path_trace_last_status = now
            self.execution_path_status.set(
                "経路記録中：{:.1f}/10.0秒 / 通過行{}件{}".format(
                    min(elapsed, 10.0), trace_snapshot.get("event_count", 0),
                    "（開始待ち）" if trace_snapshot.get("requested") else ""))
        try:
            self._execution_path_trace_after_id = self.root.after(
                100, self._poll_execution_path_trace)
        except tk.TclError:
            self._execution_path_trace_active = False

    def stop_execution_path_trace(self, automatic=False, limit_reached=False):
        if not self._execution_path_trace_active:
            return self._execution_path_last_session
        command = self._execution_path_trace_command
        if command is not None:
            command.request_execution_path_trace_stop()
        self._execution_path_stop_reason = (
            "上限に達したため自動停止" if limit_reached else
            "Commands終了により自動停止" if automatic else "記録停止")
        self.execution_path_stop_button.configure(state="disabled")
        self.execution_path_status.set("経路記録を停止しています…")
        return ""

    def _complete_execution_path_trace(self):
        if not self._execution_path_trace_active:
            return self._execution_path_last_session
        command = self._execution_path_trace_command
        trace_snapshot = command.execution_path_trace_snapshot(include_events=True)
        self._execution_path_trace_events = list(trace_snapshot.get("events") or [])
        self._execution_path_trace_active = False
        after_id, self._execution_path_trace_after_id = (
            self._execution_path_trace_after_id, None)
        if after_id is not None:
            try:
                self.root.after_cancel(after_id)
            except tk.TclError:
                pass
        self.execution_path_start_button.configure(state="normal")
        self.execution_path_stop_button.configure(state="disabled")
        session = self._save_execution_path_trace()
        if session:
            self._execution_path_last_session = session
            self.execution_path_devstudio_button.configure(state="normal")
            reason = self._execution_path_stop_reason or "10秒収集完了"
            self.execution_path_status.set(
                "{}：通過行{}件を保存しました。DevStudioで確認できます。".format(
                    reason, len(self._execution_path_trace_events)))
        else:
            self.execution_path_status.set("実行位置を観測できなかったため保存していません。")
        self._execution_path_trace_command = None
        return session

    def _save_execution_path_trace(self):
        events = list(self._execution_path_trace_events)
        if not events:
            return ""
        command = self._execution_path_trace_command
        serial_dir = os.path.dirname(os.path.abspath(__file__))
        session_dir = os.path.join(
            serial_dir, "ExecutionPaths",
            datetime.datetime.now().strftime("%Y%m%d_%H%M%S_%f"))
        try:
            os.makedirs(session_dir, exist_ok=False)
            trace = {"session_dir": session_dir, "source_snapshots": {}}
            source = self._ensure_command_monitor_source_snapshot(
                trace, command_source_descriptor(command))
            for event in events:
                event["location"] = self._ensure_command_monitor_source_snapshot(
                    trace, event.get("location", {}))
            steps_path = os.path.join(session_dir, "steps.jsonl")
            with open(steps_path, "w", encoding="utf-8", newline="\n") as stream:
                for event in events:
                    json.dump(event, stream, ensure_ascii=False)
                    stream.write("\n")
            duration = max(
                0.0, time.monotonic() - self._execution_path_trace_started)
            states = []
            for event in events:
                step = str(event.get("step_path", "") or "")
                if step and step not in states:
                    states.append(step)
            observed = {
                execution_location_key(event.get("location", {}))
                for event in events
                if event.get("location")
            }
            metadata = {
                "id": str(time.time_ns()),
                "session_dir": session_dir,
                "started_wall": self._execution_path_trace_started_wall,
                "ended_wall": datetime.datetime.now().isoformat(timespec="milliseconds"),
                "duration": duration,
                "mode": "Execution path trace",
                "command": str(getattr(command, "NAME", "")),
                "command_session_id": "execution-path-" + str(time.time_ns()),
                "source": source,
                "source_snapshots": dict(trace.get("source_snapshots", {})),
                "states": states,
                "collection_mode": "python_line_events",
                "duration_limit_seconds": 10.0,
                "event_count": len(events),
                "observed_line_count": len(observed),
            }
            temporary = os.path.join(session_dir, "command_monitor.json.tmp")
            with open(temporary, "w", encoding="utf-8", newline="\n") as stream:
                json.dump(metadata, stream, ensure_ascii=False, indent=2)
                stream.write("\n")
            os.replace(temporary, os.path.join(session_dir, "command_monitor.json"))
            return session_dir
        except (OSError, TypeError, ValueError) as error:
            self._logger.warning("Execution path trace save failed: %s", error)
            self.execution_path_status.set("経路の保存に失敗しました: " + str(error))
            return ""

    def open_execution_path_in_dev_studio(self):
        if self._execution_path_trace_active:
            self.stop_execution_path_trace()
        session = self._execution_path_last_session
        if not session or not os.path.isfile(
                os.path.join(session, "command_monitor.json")):
            self.execution_path_status.set(
                "先に経路記録を開始し、しばらく動作させてから停止してください。")
            return
        self.open_dev_studio(command_recording=session)

    def poll_command_watch(self):
        """Publish only changed public variables; never block the UI/command thread."""
        try:
            if self.command_watch_enabled.get() and self.command_watch_variables:
                command = getattr(self, "cur_command", None)
                expected = self.command_watch_command.get()
                if command is None or getattr(command, "NAME", "") != expected:
                    self.command_watch_status.set("Waiting for selected command to run.")
                else:
                    values = {}
                    for name in self.command_watch_variables:
                        if hasattr(command, name):
                            try:
                                values[name] = repr(getattr(command, name))
                            except Exception:
                                values[name] = "<unreadable>"
                        else:
                            values[name] = "<not set>"
                    if values != self.command_watch_last_values:
                        self.command_watch_last_values = values
                        message = "[Command Watch] " + expected + "\n" + "\n".join(
                            "{} = {}".format(name, value) for name, value in values.items()) + "\n"
                        self.show_output(self.command_watch_target.get(), text=message)
                    self.command_watch_status.set("Watching {} variable(s).".format(len(values)))
        finally:
            try:
                self.root.after(500, self.poll_command_watch)
            except tk.TclError:
                pass

    def open_dev_studio(self, operation_session=None, command_recording=None):
        """Launch the dependency-free PokeCon code search/merge helper."""
        project_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
        studio = os.path.join(project_dir, "DevStudio", "PokeConDevStudio.py")
        if not os.path.isfile(studio):
            tkmsg.showwarning("PokeCon Dev Studio", "DevStudio/PokeConDevStudio.py が見つかりません。")
            return
        try:
            # Do not let Dev Studio's initial code indexing share PokeCon's
            # process/console.  On Windows it is a detached child process, so
            # the main capture/controller UI returns immediately.
            options = {"cwd": os.path.dirname(studio), "close_fds": True}
            if platform.system() == "Windows":
                options["creationflags"] = (getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0) |
                                             getattr(subprocess, "DETACHED_PROCESS", 0x00000008) |
                                             getattr(subprocess, "BELOW_NORMAL_PRIORITY_CLASS", 0x00004000))
            command = [sys.executable, studio, project_dir]
            if operation_session:
                command.extend(["--operation-session", os.path.abspath(operation_session)])
            if command_recording:
                command.extend(["--command-recording", os.path.abspath(command_recording)])
            subprocess.Popen(command, **options)
            self.show_output("Analysis", text="PokeCon Dev Studio started in the background.")
        except OSError as error:
            tkmsg.showerror("PokeCon Dev Studio", "起動できませんでした。\n" + str(error))

    def set_init_device_name(self):
        if not self.com_port_name.get().strip() and int(self.com_port.get() or 0) == 0:
            self.serial_device_name.set("(未設定)")
            return
        for label, detail in getattr(self, "_serial_display_details", {}).items():
            match = re.search(r"(?i)COM(\d+)", detail.get("device", ""))
            if match and int(self.com_port.get()) == int(match.group(1)):
                self.serial_device_name.set(label)
                break

    def set_cameraid(self, event=None):
        selected = self.camera_name_cb.get()
        ret = getattr(self, "_camera_display_to_id", {}).get(selected)
        if ret is None:
            keys = [k for k, v in self.camera_dic.items()
                    if "No." + str(k) + ": " + v == selected]
            ret = keys[0] if keys else None
        if ret is None:
            self.show_output(
                "Analysis", text="Camera Nameの選択をCamera IDへ変換できませんでした。")
            return
        self.camera_id.set(ret)
        if hasattr(self, "audio_filter_camera") and self.audio_filter_camera.get():
            self.update_audio_input_list()
        # A Camera Name choice is an input choice, not merely an edit to the
        # hidden ID field.  In particular, selecting a camera while Window
        # capture is active must switch the source back to the capture device.
        # Defer until the combobox event has returned so its popup can close
        # before DirectShow performs the device hand-off.
        if event is not None and hasattr(self, "camera"):
            selected_id = int(ret)
            self.video_source.set("Capture device")
            self.root.after_idle(
                lambda camera_id=selected_id:
                self._apply_camera_name_selection(camera_id))

    def _apply_camera_name_selection(self, selected_id):
        """Open the Camera Name selection without blocking Tk controls."""
        if int(self.camera_id.get()) != int(selected_id):
            return False
        initial_open = getattr(self, "_initial_video_open_thread", None)
        name_open = getattr(self, "_camera_name_open_thread", None)
        if ((initial_open is not None and initial_open.is_alive()) or
                (name_open is not None and name_open.is_alive())):
            self.root.after(
                100, lambda camera_id=selected_id:
                self._apply_camera_name_selection(camera_id))
            return False
        preview = getattr(self, "preview", None)
        if preview is not None and hasattr(preview, "prioritizeUiInteraction"):
            preview.prioritizeUiInteraction(1.0)
        key = self._camera_usage_key(
            camera_id=selected_id, source_type="Capture device")
        label = str((self.camera_dic or {}).get(
            selected_id, (self.camera_dic or {}).get(
                str(selected_id), "Camera ID {}".format(selected_id))))
        if not self._confirm_shared_device("camera", key, label):
            return False
        self.show_output(
            "Analysis",
            text="Camera Nameの映像へ切り替え中です: Camera ID {}".format(
                selected_id))

        def worker():
            error = ""
            opened = False
            try:
                opened = bool(self.camera.openCamera(selected_id))
                if not opened:
                    error = "選択したカメラを開けませんでした。"
            except Exception as caught:
                error = str(caught)
            self._gui_action_queue.put(
                lambda: self._finish_camera_name_selection(
                    selected_id, key, label, opened, error))

        self._camera_name_open_thread = threading.Thread(
            target=worker, daemon=True, name="CameraNameOpen")
        self._camera_name_open_thread.start()
        return True

    def _finish_camera_name_selection(
            self, selected_id, usage_key, label, opened, error):
        # A newer combobox choice may have been made while DirectShow was
        # opening. Its queued switch owns the final status and device usage.
        if int(self.camera_id.get()) != int(selected_id):
            return
        if not opened:
            self._publish_device_usage("camera", "", "")
            tkmsg.showerror(
                "Video input",
                "選択したCamera Nameの映像を開けませんでした。\n\n"
                "別のPokeConで使用中でないか、USB接続を確認してください。"
                + (("\n\n" + error) if error else ""))
            self.show_output(
                "Analysis",
                text="Camera Nameの映像切替に失敗しました: Camera ID {}".format(
                    selected_id))
            return
        self._publish_device_usage("camera", usage_key, label)
        if hasattr(self, "audio_input_cb"):
            self.refresh_audio_devices()
        self.show_output(
            "Analysis",
            text="Camera Nameの選択を映像へ反映しました: Camera ID {}".format(
                selected_id))

    def set_device(self, event=None):
        selected = self.serial_device_name.get().strip()
        if not selected or selected == "(未設定)":
            self.com_port.set(0)
            self.com_port_name.set("")
            if hasattr(self, "ser"):
                self.inactivateSerial()
            return
        detail = getattr(self, "_serial_display_details", {}).get(selected, {})
        raw = detail.get("description", selected)
        device = detail.get("device", "")
        match = re.search(r"(?i)COM(\d+)", device + " " + raw)
        if match:
            self.com_port.set(int(match.group(1)))
            self.com_port_name.set("")
        elif device:
            self.com_port_name.set(device)

    def set_serial_data_format(self, event=None):
        KeyPress.serial_data_format_name = self.serial_data_format_name.get()
        self.keys_software_controller.init_hat()
        self.preview.changeRightMouseMode(self.serial_data_format_name.get())

        if self.serial_data_format_name.get() == "3DS Controller":
            print("ボーレートを強制的に115200に変更します。")
            self.baud_rate.set("115200")
        else:
            print("ボーレートを強制的に9600に変更します。")
            self.baud_rate.set("9600")
        if not getattr(self, "_defer_serial_open", False):
            self.activateSerial()

    def applyFps(self, event=None):
        print("changed FPS to: " + self.fps.get() + " [fps]")
        self.camera.setFps(self.fps.get())
        self.preview.setFps(self.fps.get())
        self._refresh_preview_priority_status()

    def applyBaudRate(self, event=None):
        pass

    def applyWindowSize(self, event=None):
        width, height = map(int, self.show_size.get().split("x"))
        self.preview.setShowsize(height, width)
        self.changeAreaSize()

        if self.show_size_tmp != self.show_size_cb["values"].index(self.show_size_cb.get()):
            ret = tkmsg.askokcancel("確認", "この画面サイズに変更しますか？")
        else:
            return

        if ret:
            self.show_size_tmp = self.show_size_cb["values"].index(self.show_size_cb.get())
        else:
            self.show_size_cb.current(self.show_size_tmp)
            width_bef, height_bef = map(int, self.show_size.get().split("x"))
            self.preview.setShowsize(height_bef, width_bef)
            # self.show_size_tmp = self.show_size_cb['values'].index(self.show_size_cb.get())

        self.changeAreaSize()

    def activateSerial(self):
        if self.serial_device_name.get().strip() == "(未設定)":
            return
        if self.ser.isOpened():
            print("Port is already opened and being closed.")
            self.ser.closeSerial()
            self._publish_device_usage("serial", "", "")
            self.keyPress = None
            self.activateSerial()
        else:
            key = self._serial_usage_key()
            label = self._selected_serial_device_label()
            if not self._confirm_shared_device("serial", key, label):
                return
            if self.ser.openSerial(self.com_port.get(), self.com_port_name.get(), self.baud_rate.get()):
                print("COM Port " + str(self.com_port.get()) + " connected successfully")
                self._logger.debug("COM Port " + str(self.com_port.get()) + " connected successfully")
                self.keyPress = KeyPress(self.ser)
                self.settings.com_port.set(self.com_port.get())
                self.settings.baud_rate.set(self.baud_rate.get())
                self.settings.save()
                self._publish_device_usage("serial", key, label)

    def _update_sender_show_serial(self):
        sender = getattr(self, "ser", None)
        if sender is not None and hasattr(sender, "set_show_serial"):
            sender.set_show_serial(self.is_show_serial.get())

    def inactivateSerial(self):
        if self.ser.isOpened():
            print("Port is already opened and being closed.")
            self.ser.closeSerial()
            self.keyPress = None
        self._publish_device_usage("serial", "", "")

    def activateKeyboard(self):
        if self.is_use_keyboard.get():
            # bind focus
            if platform.system() != "Linux":
                self.root.bind("<FocusIn>", self.onFocusInController)
                self.root.bind("<FocusOut>", self.onFocusOutController)
            self.root.after_idle(self._sync_keyboard_listener_for_focus)
            self._schedule_keyboard_focus_poll()

        else:
            if self._keyboard_focus_after_id is not None:
                try:
                    self.root.after_cancel(self._keyboard_focus_after_id)
                except tk.TclError:
                    pass
                self._keyboard_focus_after_id = None
            # stop listening to keyboard events
            if self.keyboard is not None:
                self.keyboard.stop()
                self.keyboard = None

            if platform.system() != "Linux":
                self.root.bind("<FocusIn>", self.onFocusInPokeCon)
                self.root.bind("<FocusOut>", self.onFocusOutSoftwareController)

    def onFocusInController(self, event):
        self.onFocusInPokeCon(event)
        try:
            self.root.after_idle(self._sync_keyboard_listener_for_focus)
        except tk.TclError:
            pass

    def onFocusInPokeCon(self, event=None):
        try:
            self.root.after_idle(self._mark_window_focused_if_active)
        except tk.TclError:
            pass

    def _mark_window_focused_if_active(self):
        actual_foreground = foreground_process_matches()
        if actual_foreground is False:
            return
        try:
            if actual_foreground is None and self.root.focus_displayof() is None:
                return
        except (tk.TclError, KeyError):
            return
        now = time.monotonic()
        if now - self._last_focus_mark_monotonic < 0.15:
            return
        self._last_focus_mark_monotonic = now
        # Switch local input immediately; the shared marker makes the other
        # PokeCon release its listener on the next monitor pass.
        self._last_active_input_owner = True
        self._sync_manual_input_owner()
        self._refresh_preview_priority_status()
        threading.Thread(
            target=self._publish_window_focus, daemon=True,
            name="PokeConFocusPublisher").start()

    def onFocusOutController(self, event):
        self.onFocusOutSoftwareController(event)
        try:
            self.root.after_idle(self._sync_keyboard_listener_for_focus)
        except tk.TclError:
            pass

    def _current_process_owns_manual_input(self):
        foreground_pid = foreground_process_id()
        if foreground_pid == os.getpid():
            return True
        if foreground_pid in self._live_pokecon_pids:
            return False
        return bool(self._last_active_input_owner)

    def _sync_manual_input_owner(self):
        self._sync_keyboard_listener_for_focus()
        self._sync_pc_gamepad_input_for_owner()

    def _sync_keyboard_listener_for_focus(self):
        try:
            input_owner = self._current_process_owns_manual_input()
            enabled = self.is_use_keyboard.get()
        except (tk.TclError, KeyError):
            input_owner, enabled = False, False
        should_run = keyboard_listener_should_run(enabled, input_owner)
        if should_run and self.keyboard is None:
            self.keyboard = SwitchKeyboardController(self.keyPress)
            self.keyboard.listen()
        elif not should_run and self.keyboard is not None:
            self.keyboard.stop()
            self.keyboard = None

    def _schedule_keyboard_focus_poll(self):
        if self._keyboard_focus_after_id is not None:
            return

        def poll():
            self._keyboard_focus_after_id = None
            self._sync_keyboard_listener_for_focus()
            if self.is_use_keyboard.get():
                self._keyboard_focus_after_id = self.root.after(200, poll)

        self._keyboard_focus_after_id = self.root.after(200, poll)

    def onFocusOutSoftwareController(self, event):
        """Release a mouse hold that cannot receive ButtonRelease after Alt-Tab."""
        try:
            # A child button, not the root itself, usually owns focus when
            # Alt-Tab occurs.  Check after Tk finishes the focus transition so
            # ordinary focus moves inside this PokeCon do not release a hold.
            self.root.after_idle(self._release_software_controller_if_unfocused)
        except tk.TclError:
            pass

    def _release_software_controller_if_unfocused(self):
        try:
            if self.root.focus_displayof() is not None:
                return
        except (tk.TclError, KeyError):
            return
        self._refresh_preview_priority_status()
        keys = getattr(self, "keys_software_controller", None)
        if (getattr(self, "_software_controller_override_active", False)
                or (keys is not None and bool(getattr(keys, "holdButton", [])))):
            self._queue_software_controller("neutral", None)

    def _ensure_window_activity_registry(self):
        with self._window_activity_registry_lock:
            if self._window_activity_registry is None:
                self._window_activity_registry = ActiveInputSetRegistry(
                    default_window_activity_registry_path(), profile=self.profile)
            return self._window_activity_registry

    def _publish_window_focus(self):
        try:
            with self._window_activity_update_lock:
                if self._window_activity_stop.is_set():
                    return
                self._ensure_window_activity_registry().mark_focused()
        except (OSError, TimeoutError, ValueError) as error:
            self._logger.warning("Could not publish PokeCon focus: %s", error)

    def _queue_resource_status_refresh(self):
        """Coalesce the half-second sampler while Tk is temporarily busy."""
        with self._resource_status_refresh_lock:
            if self._resource_status_refresh_queued:
                return
            self._resource_status_refresh_queued = True
        self._gui_action_queue.put(self._drain_resource_status_refresh)

    def _drain_resource_status_refresh(self):
        with self._resource_status_refresh_lock:
            self._resource_status_refresh_queued = False
        self._refresh_resource_control_status()
        self._refresh_preview_priority_status()

    def _queue_preview_status_refresh(self):
        with self._preview_status_refresh_lock:
            if self._preview_status_refresh_queued:
                return
            self._preview_status_refresh_queued = True
        self._gui_action_queue.put(self._drain_preview_status_refresh)

    def _drain_preview_status_refresh(self):
        with self._preview_status_refresh_lock:
            self._preview_status_refresh_queued = False
        self._refresh_preview_priority_status()

    def _queue_confirmation_audio_reconcile(self):
        """Coalesce main-owner changes before touching Tk audio controls."""
        with self._audio_owner_reconcile_lock:
            if self._audio_owner_reconcile_queued:
                return
            self._audio_owner_reconcile_queued = True
        self._gui_action_queue.put(
            self._drain_confirmation_audio_reconcile)

    def _drain_confirmation_audio_reconcile(self):
        with self._audio_owner_reconcile_lock:
            self._audio_owner_reconcile_queued = False
        action = confirmation_audio_action(
            requested=self._audio_monitor_requested,
            runtime_owner=self._runtime_full_rate_effective,
            other_output_active=self._other_confirmation_audio_output,
            stream_active=self._audio_output_stream_active(),
            recording_uses_output=self._confirmation_audio_recording_active())
        if action == "start":
            if time.monotonic() >= self._audio_auto_retry_at:
                self._start_audio_monitor_internal(automatic=True)
            return
        if action == "keep" and not self._runtime_full_rate_effective:
            self.audio_start_button.configure(text="Audio running (recording)")
            self.audio_level_status.set(
                "録画音声を切らないため、録画終了まで現在の確認再生を維持します。")
            return
        if self._audio_monitor_requested:
            self.audio_monitor_mode.set("Monitor")
            self.audio_start_button.configure(text="Audio waiting (main only)")
            if self._other_confirmation_audio_output:
                message = "別のPokeConの確認再生終了を待っています。"
            else:
                message = "確認再生はメインPokeConだけで有効になります。"
            self.audio_level_status.set(message)

    def _window_activity_monitor_loop(self):
        while not self._window_activity_stop.wait(0.5):
            try:
                with self._window_activity_update_lock:
                    if self._window_activity_stop.is_set():
                        return
                    registry = self._ensure_window_activity_registry()
                    live_entries = registry.entries(include_self=True)
                    if not any(int(entry.get("pid", 0)) == os.getpid()
                               for entry in live_entries):
                        live_entries.append({
                            "pid": os.getpid(),
                            "started_at": getattr(registry, "started_at", ""),
                        })
                    other_entries = [
                        entry for entry in live_entries
                        if int(entry.get("pid", 0)) != os.getpid()]
                    foreground_pid = foreground_process_id()
                    active_input_owner_pid = last_active_pokecon_pid(
                        live_entries, foreground_pid=foreground_pid)
                    active_input_owner = bool(
                        active_input_owner_pid == os.getpid())
                    live_pokecon_pids = {
                        int(entry.get("pid", 0)) for entry in live_entries
                        if int(entry.get("pid", 0)) > 0}
                    other_pokecon_foreground = bool(
                        foreground_pid is not None
                        and foreground_pid != os.getpid()
                        and any(
                            int(entry.get("pid", 0)) == foreground_pid
                            for entry in other_entries))
                    other_confirmation_audio_output = any(
                        self._entry_has_confirmation_audio_output(entry)
                        for entry in other_entries)
                    latest_entry = max(
                        live_entries,
                        key=lambda entry: (
                            str(entry.get("started_at", "")),
                            int(entry.get("pid", 0))),
                        default=None)
                    newest_pokecon_instance = bool(
                        latest_entry is None
                        or int(latest_entry.get("pid", 0)) == os.getpid())
                    other_main_preview_owner = any(
                        isinstance(entry.get("resource"), dict)
                        and bool(entry["resource"].get(
                            "main_effective", False))
                        for entry in other_entries)
                    cpu_percent = self._resource_cpu_sampler.sample()
                    if cpu_percent is not None:
                        self._resource_cpu_percent = cpu_percent
                    config = dict(self._resource_control_config)
                    protected = self._resource_runtime_protected()
                    requested_main = bool(
                        config.get("main_requested", False)
                        and not self._resource_main_open_downgraded)
                    # Publish first to atomically arbitrate the unique main
                    # role. The tier below uses the role returned by the same
                    # locked registry update on the next half-second at worst.
                    effective_main = registry.set_resource_state(
                        enabled=config.get("enabled", True),
                        target_percent=config.get("target_percent", 90),
                        main_requested=requested_main,
                        protected=protected,
                        throttle=self._resource_throttle_level,
                        cpu_percent=self._resource_cpu_percent)
                    if requested_main and not effective_main \
                            and not self._resource_main_open_downgraded:
                        # The registry is the final guard when two checkboxes
                        # are clicked nearly simultaneously. Reflect the lost
                        # claim in Tk so only the real owner remains checked.
                        self._resource_main_open_downgraded = True
                        self._gui_action_queue.put(
                            self._revoke_duplicate_main_request)
                    level = resource_throttle_level(
                        config.get("enabled", True), self._resource_cpu_percent,
                        config.get("target_percent", 90),
                        main_tool=effective_main, protected=protected)
            except (OSError, TimeoutError, ValueError) as error:
                self._logger.warning("Could not read PokeCon focus owner: %s", error)
                continue
            status_changed = (
                effective_main != self._resource_main_effective
                or level != self._resource_throttle_level)
            if effective_main != self._resource_main_effective:
                self._queue_preview_status_refresh()
            self._resource_main_effective = effective_main
            self._resource_throttle_level = level
            if other_pokecon_foreground != self._other_pokecon_foreground:
                self._other_pokecon_foreground = other_pokecon_foreground
                self._queue_preview_status_refresh()
            input_owner_changed = (
                active_input_owner != self._last_active_input_owner)
            self._last_active_input_owner = active_input_owner
            self._live_pokecon_pids = live_pokecon_pids
            if input_owner_changed:
                self._gui_action_queue.put(self._sync_manual_input_owner)
            if newest_pokecon_instance != self._newest_pokecon_instance \
                    or other_main_preview_owner != self._other_main_preview_owner:
                self._newest_pokecon_instance = newest_pokecon_instance
                self._other_main_preview_owner = other_main_preview_owner
                self._queue_preview_status_refresh()
            runtime_full_rate = bool(
                effective_main
                or (newest_pokecon_instance
                    and not other_main_preview_owner))
            if runtime_full_rate != self._runtime_full_rate_effective:
                if not set_main_runtime_priority(runtime_full_rate):
                    self._logger.warning(
                        "Could not change full-rate PokeCon scheduling priority")
                self._runtime_full_rate_effective = runtime_full_rate
            audio_owner_changed = (
                other_confirmation_audio_output
                != self._other_confirmation_audio_output)
            self._other_confirmation_audio_output = \
                other_confirmation_audio_output
            audio_action = confirmation_audio_action(
                requested=self._audio_monitor_requested,
                runtime_owner=runtime_full_rate,
                other_output_active=other_confirmation_audio_output,
                stream_active=self._audio_output_stream_active(),
                recording_uses_output=
                    self._confirmation_audio_recording_active())
            if audio_action == "stop":
                if self._suspend_confirmation_audio_for_owner_loss(registry):
                    audio_action = "wait"
            if audio_owner_changed or audio_action in ("start", "stop", "wait"):
                self._queue_confirmation_audio_reconcile()
            if status_changed or cpu_percent is not None:
                self._queue_resource_status_refresh()

    def _start_window_activity_tracking(self):
        if self._window_activity_thread is not None:
            return
        self._window_activity_stop.clear()
        self._other_pokecon_foreground = False
        self._refresh_preview_priority_status()
        self._window_activity_thread = threading.Thread(
            target=self._window_activity_monitor_loop, daemon=True,
            name="PokeConActivityMonitor")
        self._window_activity_thread.start()
        threading.Thread(
            target=self._publish_window_focus, daemon=True,
            name="PokeConInitialFocusPublisher").start()

    def _stop_window_activity_tracking(self):
        self._window_activity_stop.set()
        set_main_runtime_priority(False)
        with self._window_activity_update_lock:
            registry = self._window_activity_registry
            if registry is not None:
                try:
                    registry.close()
                except (OSError, TimeoutError, ValueError) as error:
                    self._logger.warning("Could not unregister PokeCon focus: %s", error)

    def _preview_render_priority(self):
        # Chrome and other non-PokeCon applications do not reduce the main
        # preview. The checked 60-FPS owner is unique across all PokeCons, so
        # another PokeCon in front does not revoke it either.
        # Exit/finalization waits always release 60-FPS display.
        main_permission, _ = preview_rate_permissions(
            main_tool=self._resource_main_effective,
            other_pokecon_foreground=self._other_pokecon_foreground,
            # The checkbox is now the unique main-owner request. It must not
            # independently grant 60 FPS to a second, downgraded foreground
            # PokeCon after the startup confirmation popup.
            allow_foreground_full_rate=False,
            suspended=self._preview_full_rate_suspended())
        suspended = self._preview_full_rate_suspended()
        newest = bool(self._newest_pokecon_instance)
        # With no checked owner, the last-opened PokeCon keeps the configured
        # FPS. If another PokeCon owns 60 FPS, the newest ordinary instance is
        # still kept warm at 30 FPS rather than dropping to 5 because Chrome
        # or another non-PokeCon application is in front.
        automatic_latest_full_rate = bool(
            newest and not self._other_main_preview_owner and not suspended)
        return (bool(main_permission or automatic_latest_full_rate),
                False, newest)

    def _preview_full_rate_suspended(self):
        # Saving/merging while PokeCon remains open must not reduce preview
        # FPS. Suspension is reserved for the X-button close flow while the
        # final video is being created and the process is waiting to exit.
        return bool(getattr(self, "_preview_shutdown_mode", False))

    def _resource_runtime_protected(self):
        if time.monotonic() < self._resource_protected_until:
            return True
        command = getattr(self, "cur_command", None)
        worker = getattr(command, "thread", None) if command is not None else None
        if worker is not None and worker.is_alive():
            return True
        return bool(
            getattr(self.recorder, "active", False)
            or getattr(self, "record_armed", False)
            or getattr(self.operation_recorder, "active", False)
            or getattr(self, "_software_controller_override_active", False)
        )

    def _resource_preview_multiplier(self):
        if self._resource_runtime_protected():
            return 1.0
        return throttle_multiplier(self._resource_throttle_level)

    def _note_resource_interaction(self, event=None):
        self._resource_protected_until = max(
            self._resource_protected_until, time.monotonic() + 3.0)

    def _prioritize_tab_interaction(self, event=None):
        preview = getattr(self, "preview", None)
        if preview is not None:
            preview.prioritizeUiInteraction()

    def _prioritize_control_interaction(self, event=None):
        preview = getattr(self, "preview", None)
        if preview is None:
            return
        widget = getattr(event, "widget", None)
        # Pointer motion over the video is used for manual stick/touchscreen
        # control and should not suppress its own preview. Other controls get
        # a short render-free window before their click or key event.
        if getattr(event, "type", None) == tk.EventType.Motion and widget is not None:
            try:
                if widget is preview or str(widget).startswith(str(preview) + "."):
                    return
            except (AttributeError, tk.TclError):
                pass
        seconds = 0.30 if getattr(event, "type", None) == tk.EventType.Motion else 0.55
        preview.prioritizeUiInteraction(seconds)

    def _cache_resource_control_config(self):
        try:
            target = clamp_cpu_target(self.resource_cpu_target.get())
        except tk.TclError:
            target = 90
        self._resource_control_config = {
            "enabled": bool(self.resource_control_enabled.get()),
            "target_percent": target,
            "main_requested": bool(self.resource_main_tool.get()),
        }

    def _resource_config_changed(self, event=None):
        target = clamp_cpu_target(self.resource_cpu_target.get())
        if self.resource_cpu_target.get() != target:
            self.resource_cpu_target.set(target)
        self._cache_resource_control_config()
        self._resource_protected_until = max(
            self._resource_protected_until, time.monotonic() + 3.0)
        self._refresh_resource_control_status()
        self._sync_resource_control_to_active_input_set()

    def _resource_main_changed(self):
        if self.resource_main_tool.get():
            conflicts = main_resource_conflicts(self._other_device_usage_entries())
            if conflicts:
                self.resource_main_tool.set(False)
                tkmsg.showwarning(
                    "メインツールは重複できません",
                    "ほかのPokeConがメインツールとして動作中です。\n"
                    "先にそのPokeConのメイン設定を解除するか終了してください。",
                    parent=self.root)
        self._resource_main_open_downgraded = False
        self._resource_config_changed()

    def _revoke_duplicate_main_request(self):
        """Uncheck a 60-FPS claim which lost cross-process arbitration."""
        if self._resource_main_effective or not self.resource_main_tool.get():
            return
        self.resource_main_tool.set(False)
        self.last_active_preview_full_fps.set(False)
        self._cache_resource_control_config()
        self._refresh_resource_control_status()
        self._refresh_preview_priority_status()
        self._sync_resource_control_to_active_input_set()
        self.show_output(
            "Analysis",
            text="表示60FPS維持は別のPokeConで使用中のため、この画面では解除しました。")

    def _refresh_resource_control_status(self):
        if not hasattr(self, "resource_control_status"):
            return
        cpu = self._resource_cpu_percent
        cpu_text = "測定中" if cpu is None else "{:.1f}%".format(cpu)
        if self._resource_main_effective:
            role = "メインツール"
        elif self.resource_main_tool.get() and self._resource_main_open_downgraded:
            role = "通常（別のメインが起動中）"
        elif self.resource_main_tool.get():
            role = "通常（メイン役の取得待ち）"
        elif self._resource_runtime_protected():
            role = "操作保護中"
        else:
            role = "バックグラウンド"
        names = {"normal": "通常", "light": "軽い省負荷",
                 "medium": "省負荷", "strong": "強い省負荷"}
        self.resource_control_status.set(
            "CPU {} / 目標 {}% / 役割: {} / 現在: {}".format(
                cpu_text, self._resource_control_config.get("target_percent", 90),
                role, names.get(self._resource_throttle_level, "通常")))

    @staticmethod
    def _input_set_requests_main_resource(item):
        if not isinstance(item, dict):
            return False
        snapshot = item.get("all_tabs", {})
        values = snapshot.get("values", {}) if isinstance(snapshot, dict) else {}
        return bool(values.get("resource_main_tool", False))

    def _confirm_main_resource_input_set(self, item, name=""):
        self._resource_main_open_downgraded = False
        if not self._input_set_requests_main_resource(item):
            return True
        conflicts = main_resource_conflicts(self._other_device_usage_entries())
        if not conflicts:
            return True
        opened = tkmsg.askyesno(
            "メインツールが起動中です",
            ("InputSet「{}」はメインツール設定ですが、ほかのPokeConがメインです。\n\n"
             "「はい」: このPokeConは通常ツールとしてそのまま開く\n"
             "「いいえ」: このInputSetを開かない").format(name or ""),
            parent=self.root)
        self._resource_main_open_downgraded = bool(opened)
        return bool(opened)

    def _sync_resource_control_to_active_input_set(self):
        name = str(getattr(self, "_active_input_set_name", "") or "").strip()
        if not name or not hasattr(self, "input_set_name") \
                or self.input_set_name.get().strip() != name:
            return False
        data = self._read_input_sets()
        item = data.get("input_sets", {}).get(name)
        snapshot = item.get("all_tabs", {}) if isinstance(item, dict) else {}
        values = snapshot.get("values", {}) if isinstance(snapshot, dict) else {}
        if not isinstance(values, dict):
            return False
        values.update({
            "resource_control_enabled": self.resource_control_enabled.get(),
            "resource_cpu_target": clamp_cpu_target(self.resource_cpu_target.get()),
            "resource_main_tool": self.resource_main_tool.get(),
        })
        self._write_input_sets(data)
        return True

    def _other_device_usage_entries(self):
        try:
            registry = getattr(self, "_window_activity_registry", None)
            if registry is not None:
                return registry.entries(include_self=False)
            return read_active_input_sets(default_window_activity_registry_path())
        except (OSError, TimeoutError, ValueError) as error:
            self._logger.warning("Could not read shared device usage: %s", error)
            return []

    @staticmethod
    def _entry_has_confirmation_audio_output(entry):
        devices = entry.get("devices", {}) if isinstance(entry, dict) else {}
        output = devices.get("audio_output", {}) \
            if isinstance(devices, dict) else {}
        return bool(isinstance(output, dict) and output.get("key"))

    def _device_conflicts(self, kind, key):
        return device_usage_conflicts(self._other_device_usage_entries(), kind, key)

    @staticmethod
    def _device_conflict_owner_text(entries):
        owners = []
        for entry in entries:
            input_set = str(entry.get("input_set", "") or "").strip()
            profile = str(entry.get("profile", "") or "").strip()
            label = input_set or profile or "InputSet未選択"
            owners.append("{} / PID {}".format(label, entry.get("pid", "?")))
        return "、".join(owners)

    def _confirm_shared_device(self, kind, key, label, parent=None):
        if key in self._confirmed_shared_device_keys:
            return True
        conflicts = self._device_conflicts(kind, key)
        if not conflicts:
            return True
        names = {"camera": "Camera", "serial": "Serial", "audio": "Audio"}
        device_name = names.get(kind, kind)
        owner = parent or self.root
        attach_to_owner = dialog_owner_attachment_allowed()
        dialog = tk.Toplevel(owner)
        dialog.title("{}はほかのPokeConで使用中".format(device_name))
        if attach_to_owner:
            dialog.transient(owner)
        dialog.resizable(False, False)
        accepted_state = {"value": False}
        ttk.Label(
            dialog,
            text=("{}\n\nほかのPokeConで使用中です: {}\n"
                  "同じ機器をこのPokeConにも反映しますか？").format(
                      label, self._device_conflict_owner_text(conflicts)),
            justify="left", wraplength=620).pack(fill="x", padx=14, pady=(14, 8))
        buttons = ttk.Frame(dialog)
        buttons.pack(fill="x", padx=14, pady=(2, 14))

        def finish(value):
            accepted_state["value"] = bool(value)
            dialog.destroy()

        ttk.Button(buttons, text="それでも反映",
                   command=lambda: finish(True)).pack(side="left", padx=(0, 6))
        ttk.Button(buttons, text="反映しない",
                   command=lambda: finish(False)).pack(side="left")
        dialog.protocol("WM_DELETE_WINDOW", lambda: finish(False))
        dialog.update_idletasks()
        dialog.wait_visibility()
        if attach_to_owner:
            dialog.lift()
        dialog.grab_set()
        dialog.wait_window()
        accepted = accepted_state["value"]
        if accepted:
            self._confirmed_shared_device_keys.add(key)
        return accepted

    def _publish_device_usage(self, kind, key="", label=""):
        state = (str(key or ""), str(label or ""))
        if self._published_device_usage.get(kind) == state:
            return
        try:
            self._ensure_window_activity_registry().set_device(kind, key, label)
            self._published_device_usage[kind] = state
        except (OSError, TimeoutError, ValueError) as error:
            self._logger.warning("Could not publish %s usage: %s", kind, error)

    def _device_usage_suffix(self, kind, key, entries=None):
        conflicts = device_usage_conflicts(
            self._other_device_usage_entries() if entries is None else entries,
            kind, key)
        if not conflicts:
            return ""
        return " [別PokeConで使用中: {}]".format(
            self._device_conflict_owner_text(conflicts))

    def _camera_usage_key(self, camera_id=None, source_type=None, window_handle=None):
        source_type = source_type or self.video_source.get()
        if source_type == "Window (Steam/game)":
            handle = window_handle
            if handle is None:
                handle = getattr(self, "window_sources", {}).get(self.window_source.get())
            return canonical_device_key("camera", "window-hwnd:{}".format(handle)) if handle else ""
        camera_id = self.camera_id.get() if camera_id is None else camera_id
        devices = self.camera_dic or {}
        value = devices.get(camera_id, devices.get(str(camera_id), "Camera ID {}".format(camera_id)))
        return canonical_device_key("camera", value)

    def _serial_usage_key(self, port_number=None, port_name=None):
        port_name = self.com_port_name.get() if port_name is None else port_name
        port_number = self.com_port.get() if port_number is None else port_number
        value = str(port_name or "").strip() or "COM{}".format(port_number)
        return canonical_device_key("serial", value)

    def _selected_serial_device_label(self):
        selected = self.serial_device_name.get().strip()
        detail = getattr(self, "_serial_display_details", {}).get(selected, {})
        return str(detail.get("description", selected))

    def _audio_usage_key(self, name=None):
        return canonical_device_key(
            "audio", self._selected_audio_device_name() if name is None else name)

    def _set_camera_unconfigured(self):
        if hasattr(self, "camera"):
            self.camera.destroy()
        self.camera_id.set(-1)
        self.camera_name_fromDLL.set("(未設定)")
        self._publish_device_usage("camera", "", "")

    def _set_serial_unconfigured(self):
        if hasattr(self, "ser"):
            self.inactivateSerial()
        self.serial_device_name.set("(未設定)")
        self.com_port.set(0)
        self.com_port_name.set("")

    def _set_audio_unconfigured(self):
        if hasattr(self, "audio_monitor"):
            self.stop_audio_monitor()
        self.audio_input.set("")
        self.audio_auto_start.set(False)

    def _apply_hardware_unconfigured_selection(self):
        """Keep InputSet tab settings while showing all three devices as unset."""
        self.video_source.set("Capture device")
        self.camera_id.set(-1)
        self.camera_name_fromDLL.set("(未設定)")
        self.window_source.set("")
        self.serial_device_name.set("(未設定)")
        self.com_port.set(0)
        self.com_port_name.set("")
        self.audio_input.set("")
        self.audio_auto_start.set(False)

    def _preview_capture_work_active(self):
        """Keep requested capture cadence only for an armed/active recorder."""
        return bool(
            getattr(self.recorder, "active", False)
            or getattr(self, "record_armed", False)
            or getattr(self.operation_recorder, "active", False)
        )

    def _live_frame_analysis_active(self):
        assist = getattr(self, "image_assist_enabled", None)
        if assist is not None and assist.get():
            return True
        rules_enabled = getattr(self, "analysis_rules_enabled", None)
        if rules_enabled is not None and rules_enabled.get() and any(
                item.get("enabled", True) for item in getattr(self, "analysis_rules", [])):
            return True
        vision = getattr(self, "vision", None)
        if vision is not None:
            rule = vision.modes.get(vision.current_mode, {})
            if isinstance(rule, dict) and any(rule.values()):
                return True
        return False

    def _refresh_preview_priority_status(self):
        try:
            requested = max(1, int(self.fps.get()))
        except (tk.TclError, TypeError, ValueError):
            requested = 30
        try:
            actual_foreground = foreground_process_matches()
            foreground = (self.root.focus_displayof() is not None) \
                if actual_foreground is None else actual_foreground
        except (tk.TclError, KeyError):
            foreground = False
        suspended = self._preview_full_rate_suspended()
        newest = bool(self._newest_pokecon_instance)
        automatic_latest_full_rate = bool(
            newest and not self._other_main_preview_owner and not suspended)
        main_full_rate = bool(
            (self._resource_main_effective and not suspended)
            or automatic_latest_full_rate)
        if suspended:
            label = "終了・録画保存待ち"
        elif self._resource_main_effective and main_full_rate:
            label = "メイン表示"
        elif automatic_latest_full_rate:
            label = "最終起動PokeCon"
        elif newest:
            label = "最終起動PokeCon（別メインあり）"
        elif foreground:
            label = "前面表示"
        else:
            label = ""
        if label:
            full_rate = bool(main_full_rate)
            if full_rate:
                limit = min(60, requested)
            elif foreground or newest:
                limit = min(30, requested)
            else:
                limit = min(5, requested)
            status = "{}：{}fps（録画fpsには影響なし）".format(label, limit)
        else:
            status = "省負荷表示：5fps（録画fpsには影響なし）"
        camera = getattr(self, "camera", None)
        preview = getattr(self, "preview", None)
        input_fps = camera.measuredFps() \
            if camera is not None and hasattr(camera, "measuredFps") else 0.0
        display_fps = preview.measuredPreviewFps() \
            if preview is not None and hasattr(preview, "measuredPreviewFps") else 0.0
        measured = "入力{} / 表示{}fps".format(
            "{:.1f}".format(input_fps) if input_fps > 0.0 else "測定中",
            "{:.1f}".format(display_fps) if display_fps > 0.0 else "測定中")
        status = status + " / " + measured
        if status != self._last_active_preview_status_value:
            self._last_active_preview_status_value = status
            self.last_active_preview_status.set(status)

    def createControllerWindow(self):
        if self.controller is not None:
            self.controller.focus_force()
            return

        window = ControllerGUI(self.root, self.ser)
        window.protocol("WM_DELETE_WINDOW", self.closingController)
        self.controller = window

    def activate_Left_stick_mouse(self):
        self.preview.ApplyLStickMouse()

    def activate_Right_stick_mouse(self):
        self.preview.ApplyRStickMouse()

    def run_ProController(self):
        worker = threading.current_thread()
        if self.procon is not None:
            self.procon = None
        try:
            joystick_index = int(self.pc_gamepad.get().split(":", 1)[0])
        except (ValueError, IndexError):
            joystick_index = 0
        try:
            gamepad_mapping = dict(self._active_operation_gamepad_mapping)
            if not gamepad_mapping:
                data = self._operation_gamepad_profile_store().load()
                gamepad_mapping = dict(
                    data["profiles"][data["selected"]].get("mapping", {}))
            self.procon = ProController(
                joystick_index,
                input_enabled_event=self.pc_gamepad_input_event,
                activity_callback=self._notify_pc_gamepad_activity,
                state_callback=self._queue_pc_gamepad_state,
                input_callback=self._record_operation_input,
                control_mapping=gamepad_mapping,
                physical_input_callback=self._queue_operation_gamepad_physical_input,
            )
            self.procon.controller_loop(self.ser, self.flag_record, self.ControllerLogDir)
        except Exception as error:
            self._logger.warning("PC gamepad bridge could not start: %s", error)
            self._gui_action_queue.put(
                lambda message=str(error), owner=worker:
                self._recover_pc_gamepad_ui(message, owner))
        finally:
            self._gui_action_queue.put(
                lambda owner=worker: self._pro_controller_thread_finished(owner))

    def _pro_controller_thread_finished(self, worker=None):
        # A stopped worker can report completion after its replacement has
        # already started.  Never clear the newer bridge in that case.
        if worker is not None and self.pro_controller_thread is not worker:
            return
        self.pro_controller_thread = None
        self.procon = None
        if (self.is_use_Pro_Controller.get()
                and self.pc_gamepad_input_enabled.get()):
            self.pc_gamepad_input_status.set("ゲームパッド再接続中")
            self._schedule_pc_gamepad_bridge_restart()
        elif self.pc_gamepad_input_enabled.get():
            self.pc_gamepad_input_status.set("入力許可中（Hardwareが停止中）")

    def _recover_pc_gamepad_ui(self, message, worker=None):
        if worker is not None and self.pro_controller_thread is not worker:
            return
        ProController.flag_procon = False
        self.is_use_Pro_Controller.set(False)
        self.pc_gamepad_input_enabled.set(False)
        self.pc_gamepad_input_event.clear()
        self.pc_gamepad_input_status.set("操作停止中")
        self.record_pro_controller_checkbox["state"] = "normal"
        self.start_top_button["state"] = "normal"
        self.simplecon_top_button["state"] = "normal"
        tkmsg.showwarning("PCゲームパッド→Switch", message)

    def refresh_pc_gamepads(self):
        values = ProController.devices()
        self.pc_gamepad_cb.configure(values=values)
        if self.pc_gamepad.get() not in values:
            self.pc_gamepad.set(values[0] if values else "")

    def toggle_pc_gamepad_input(self):
        if self.pc_gamepad_input_enabled.get():
            forwarding = self._sync_pc_gamepad_input_for_owner()
            running = (self.pro_controller_thread is not None
                       and self.pro_controller_thread.is_alive()
                       and ProController.flag_procon)
            if not self.is_use_Pro_Controller.get():
                self.pc_gamepad_input_status.set("入力許可中（HardwareがOFF）")
            elif not running:
                self.pc_gamepad_input_status.set("ゲームパッド再接続中")
                self._schedule_pc_gamepad_bridge_restart()
            elif forwarding:
                self.pc_gamepad_input_status.set("ニュートラル確認中")
        else:
            self.pc_gamepad_input_event.clear()
            self.pc_gamepad_input_status.set("操作停止中（許可OFF）")

    def _sync_pc_gamepad_input_for_owner(self):
        try:
            requested = bool(self.pc_gamepad_input_enabled.get())
            owns_input = self._current_process_owns_manual_input()
        except (tk.TclError, KeyError):
            requested, owns_input = False, False
        if requested and owns_input:
            self.pc_gamepad_input_event.set()
        else:
            self.pc_gamepad_input_event.clear()
            if requested:
                self.pc_gamepad_input_status.set(
                    "別のPokeConが操作対象（この画面を選択すると切替）")
        return bool(requested and owns_input)

    def _schedule_pc_gamepad_bridge_restart(self):
        if self._pc_gamepad_restart_pending:
            return
        self._pc_gamepad_restart_pending = True
        self.root.after(100, self._restart_pc_gamepad_bridge_if_requested)

    def _restart_pc_gamepad_bridge_if_requested(self):
        self._pc_gamepad_restart_pending = False
        if (not self.is_use_Pro_Controller.get()
                or not self.pc_gamepad_input_enabled.get()):
            return
        thread = self.pro_controller_thread
        if thread is not None and thread.is_alive():
            if ProController.flag_procon:
                self.pc_gamepad_input_status.set("ニュートラル確認中")
                return
            # The previous SDL loop is still releasing the device.  Retry
            # after it exits instead of leaving the checked UI disconnected.
            self.pc_gamepad_input_status.set("前回の接続終了待ち")
            self._schedule_pc_gamepad_bridge_restart()
            return
        self.mode_change_Pro_Controller()

    def _queue_pc_gamepad_state(self, state):
        self._gui_action_queue.put(
            lambda current=state: self._show_pc_gamepad_state(current))

    def _show_pc_gamepad_state(self, state):
        bridge_ready = (self.is_use_Pro_Controller.get()
                        and self.pro_controller_thread is not None
                        and self.pro_controller_thread.is_alive()
                        and ProController.flag_procon)
        owns_input = self._current_process_owns_manual_input()
        if self.pc_gamepad_input_enabled.get() and not owns_input:
            self.pc_gamepad_input_status.set(
                "別のPokeConが操作対象（この画面を選択すると切替）")
        elif state == "ready" and self.pc_gamepad_input_enabled.get() and bridge_ready:
            self.pc_gamepad_input_status.set("操作可能（HOME無効）")
        elif (state.startswith("waiting_neutral")
              and self.pc_gamepad_input_enabled.get() and bridge_ready):
            blocker = state.split(":", 1)[1] if ":" in state else ""
            self.pc_gamepad_input_status.set(
                "ニュートラル確認中：{}を離してください".format(blocker)
                if blocker else "ニュートラル確認中")
        else:
            self.pc_gamepad_input_status.set("操作停止中（許可OFF）")

    def _notify_pc_gamepad_activity(self):
        if not flag_import_plyer:
            self._logger.warning("plyer is not installed; PC gamepad activity notification is unavailable.")
            return

        def notify():
            try:
                notification.notify(
                    title="PokeCon: Switch操作を検知",
                    message="PCゲームパッドからSwitchへの操作が開始されました。",
                    timeout=5,
                )
            except Exception as error:
                self._logger.warning("PC gamepad activity notification failed: %s", error)

        threading.Thread(target=notify, daemon=True).start()

    def mode_change_show_value(self):
        Command.isSimilarity = self.is_show_value.get()

    def mode_change_show_guide(self):
        Command.isGuide = self.is_show_guide.get()

    def mode_change_show_image(self):
        Command.isImage = self.is_show_image.get()

    def mode_change_notification(self, *event):
        Command.isWinNotStart = self.is_win_notification_start.get()
        Command.isWinNotEnd = self.is_win_notification_end.get()
        Command.isLineNotStart = self.is_line_notification_start.get()
        Command.isLineNotEnd = self.is_line_notification_end.get()
        Command.isDiscordNotStart = self.is_discord_notification_start.get()
        Command.isDiscordNotEnd = self.is_discord_notification_end.get()

    def change_buttons_position(self, *event):
        Command.pos_dialogue_buttons = self.pos_dialogue_buttons.get()

    def mode_change_Pro_Controller(self):
        # Connection and forwarding permission are one user-facing state.
        # Keeping two independent checkboxes allowed a checked-but-inactive
        # combination after pause/re-enable.
        requested = bool(self.is_use_Pro_Controller.get())
        if requested and self._command_execution_active():
            # Re-checking while Commands is still stopping used to create a
            # bridge that looked ready but was competing with the Command.
            self._pc_gamepad_restore_after_command = True
            self.is_use_Pro_Controller.set(False)
            self.pc_gamepad_input_enabled.set(False)
            self.pc_gamepad_input_event.clear()
            self.pc_gamepad_input_status.set("Commands終了後に自動で有効化します")
            return
        self.pc_gamepad_input_enabled.set(requested)
        self._sync_pc_gamepad_input_for_owner()
        if not requested:
            self.pc_gamepad_input_status.set("操作停止中")
        if (self.is_use_Pro_Controller.get()
                and self.pro_controller_thread is not None
                and self.pro_controller_thread.is_alive()):
            if ProController.flag_procon:
                self._sync_pc_gamepad_input_for_owner()
                return
            self.pc_gamepad_input_status.set("前回の接続終了待ち")
            self._schedule_pc_gamepad_bridge_restart()
            return
        if self.is_use_Pro_Controller.get():  # Proconでの操作を有効化する。
            if self.serial_data_format_name.get() == "3DS Controller":
                self.is_use_Pro_Controller.set(False)
                self.pc_gamepad_input_enabled.set(False)
                self.pc_gamepad_input_event.clear()
                self.pc_gamepad_input_status.set("操作停止中")
                tkmsg.showwarning("PCゲームパッド→Switch",
                                  "この機能はSwitch用です。SerialタブのData FormatをDefaultへ変更してください。")
                return
            self.refresh_pc_gamepads()
            if not self.pc_gamepad.get():
                self.is_use_Pro_Controller.set(False)
                self.pc_gamepad_input_enabled.set(False)
                self.pc_gamepad_input_event.clear()
                self.pc_gamepad_input_status.set("操作停止中")
                tkmsg.showwarning("PCゲームパッド→Switch", "PCゲームパッドが見つかりません。接続後に再検索してください。")
                return
            try:
                self.closingController()
            except Exception:
                pass
            ProController.flag_procon = True
            self.flag_record = self.is_record_Pro_Controller.get()
            self.ControllerLogDir = "Controller_Log"
            self.record_pro_controller_checkbox["state"] = "disabled"
            self.pro_controller_thread = threading.Thread(
                target=self.run_ProController, daemon=True, name="PCGamepadToSwitch")
            self.pro_controller_thread.start()
            self.pc_gamepad_input_status.set(
                "ニュートラル確認中"
                if self.pc_gamepad_input_enabled.get()
                and self._current_process_owns_manual_input()
                else ("別のPokeConが操作対象（この画面を選択すると切替）"
                      if self.pc_gamepad_input_enabled.get()
                      else "操作停止中（許可OFF）"))
            self.start_top_button["state"] = "disabled"
            self.simplecon_top_button["state"] = "disabled"

        else:  # Proconでの操作を無効化する。
            ProController.flag_procon = False
            self.record_pro_controller_checkbox["state"] = "normal"
            self.start_top_button["state"] = "normal"
            self.simplecon_top_button["state"] = "normal"

    def _suspend_pc_gamepad_for_command(self):
        """Temporarily stop manual input while Commands owns the controller."""
        self._pc_gamepad_restore_after_command = bool(
            self._pc_gamepad_restore_after_command
            or self.is_use_Pro_Controller.get())
        self.is_use_Pro_Controller.set(False)
        self.mode_change_Pro_Controller()

    def _restore_pc_gamepad_after_command(self):
        if not self._pc_gamepad_restore_after_command:
            return
        if self._command_execution_active():
            self.root.after(100, self._restore_pc_gamepad_after_command)
            return
        self._pc_gamepad_restore_after_command = False
        self.is_use_Pro_Controller.set(True)
        self.mode_change_Pro_Controller()

    def record_Pro_Controller(self):
        self.flag_record = self.is_record_Pro_Controller.get()

    def open_controller_log_editor(self):
        """Manage multiple reusable PC-controller recordings."""
        from tkinter import filedialog, simpledialog

        dialog = tk.Toplevel(self.root)
        dialog.title("コントローラー記録ライブラリ")
        dialog.transient(self.root)
        dialog.geometry("820x430")
        listing = tk.Listbox(dialog, exportselection=False)
        listing.pack(fill="both", expand=True, padx=8, pady=8)

        def selected_name():
            selected = listing.curselection()
            return listing.get(selected[0]).split("  |  ", 1)[0] if selected else ""

        def refresh():
            listing.delete(0, "end")
            for name, item in sorted(self._read_controller_recordings().items(), key=lambda pair: pair[0].casefold()):
                listing.insert("end", "{}  |  {}行  |  {}".format(
                    name, len(item.get("lines", [])), item.get("source_path", "")))

        def register_file():
            initial_dir = os.path.abspath(getattr(self, "ControllerLogDir", "Controller_Log"))
            path = filedialog.askopenfilename(
                title="PCコントローラー記録を登録", initialdir=initial_dir,
                filetypes=[("Controller log", "*.txt"), ("All files", "*.*")], parent=dialog)
            if not path:
                return
            try:
                with open(path, "r", encoding="utf-8") as stream:
                    lines = stream.readlines()
                python_replacement_body(lines)
            except (OSError, ValueError) as error:
                tkmsg.showerror("コントローラー記録", str(error), parent=dialog)
                return
            name = simpledialog.askstring(
                "コントローラー記録", "登録名:", initialvalue=os.path.splitext(os.path.basename(path))[0],
                parent=dialog)
            if not name or not name.strip():
                return
            name = name.strip()
            data = self._read_controller_recordings()
            if name in data and not tkmsg.askyesno("コントローラー記録", "同名の登録を更新しますか？", parent=dialog):
                return
            data[name] = {"source_path": os.path.abspath(path), "lines": lines}
            self._write_controller_recordings(data)
            refresh()

        def edit_selected():
            name = selected_name()
            item = self._read_controller_recordings().get(name)
            if item:
                self._show_controller_recording_editor(name, item, refresh)

        def delete_selected():
            name = selected_name()
            linked = [rule for rule in self.commands_assist_rules
                      if rule.get("replacement_type") == "controller_recording"
                      and rule.get("controller_recording") == name]
            detail = "\nこの記録を使う関数置換{}件も削除します。".format(len(linked)) if linked else ""
            if not name or not tkmsg.askyesno(
                    "コントローラー記録", "「{}」を削除しますか？{}".format(name, detail), parent=dialog):
                return
            data = self._read_controller_recordings()
            data.pop(name, None)
            self._write_controller_recordings(data)
            if linked:
                self.commands_assist_rules = [
                    rule for rule in self.commands_assist_rules
                    if not (rule.get("replacement_type") == "controller_recording"
                            and rule.get("controller_recording") == name)]
                self._refresh_commands_assist_rule_list()
                self._commands_assist_evaluator.reset()
            refresh()

        def copy_selected():
            name = selected_name()
            item = self._read_controller_recordings().get(name)
            if not item:
                return
            try:
                body = python_replacement_body(item.get("lines", []))
            except ValueError as error:
                tkmsg.showwarning("置換処理", str(error), parent=dialog)
                return
            self.root.clipboard_clear()
            self.root.clipboard_append(body)
            self.commands_assist_status.set("登録「{}」の置換処理コードをコピーしました。".format(name))

        actions = ttk.Frame(dialog)
        actions.pack(fill="x", padx=8, pady=(0, 8))
        ttk.Button(actions, text="ファイルを登録", command=register_file).pack(side="left", padx=3)
        ttk.Button(actions, text="角度・範囲を編集", command=edit_selected).pack(side="left", padx=3)
        ttk.Button(actions, text="置換コードをコピー", command=copy_selected).pack(side="left", padx=3)
        ttk.Button(actions, text="削除", command=delete_selected).pack(side="right", padx=3)
        ttk.Button(actions, text="閉じる", command=dialog.destroy).pack(side="right", padx=3)
        listing.bind("<Double-1>", lambda event: edit_selected())
        refresh()

    def _controller_recordings_path(self):
        return os.path.join(os.path.dirname(Settings.GuiSettings.SETTING_PATH), "controller_recordings.json")

    def _read_controller_recordings(self):
        try:
            with open(self._controller_recordings_path(), "r", encoding="utf-8") as stream:
                data = json.load(stream)
            return data if isinstance(data, dict) else {}
        except (OSError, ValueError):
            return {}

    def _write_controller_recordings(self, data):
        path = self._controller_recordings_path()
        os.makedirs(os.path.dirname(path), exist_ok=True)
        temporary = path + ".tmp"
        with open(temporary, "w", encoding="utf-8", newline="\n") as stream:
            json.dump(data, stream, ensure_ascii=False, indent=2)
            stream.write("\n")
        os.replace(temporary, path)

    def _show_controller_recording_editor(self, name, item, refresh_callback=None):
        from tkinter import filedialog
        lines = list(item.get("lines", []))
        dialog = tk.Toplevel(self.root)
        dialog.title("コントローラー記録編集: " + name)
        dialog.transient(self.root)
        dialog.geometry("980x620")
        controls = ttk.Frame(dialog)
        controls.pack(fill="x", padx=7, pady=7)
        start_line = tk.IntVar(value=1)
        end_line = tk.IntVar(value=max(1, len(lines)))
        degrees = tk.DoubleVar(value=0.0)
        sticks = tk.StringVar(value="both")
        for label, variable, width in (("開始行", start_line, 7), ("終了行", end_line, 7),
                                       ("角度差(度)", degrees, 8)):
            ttk.Label(controls, text=label).pack(side="left", padx=(4, 2))
            ttk.Entry(controls, textvariable=variable, width=width).pack(side="left")
        ttk.Label(controls, text="対象スティック").pack(side="left", padx=(12, 2))
        ttk.Combobox(controls, state="readonly", width=8, textvariable=sticks,
                     values=("both", "left", "right")).pack(side="left")
        editor = tk.Text(dialog, wrap="none", font=("Consolas", 10), tabs=(32,))
        editor.pack(fill="both", expand=True, padx=7, pady=(0, 7))
        editor.insert("1.0", "".join(lines))

        def current_lines():
            content = editor.get("1.0", "end-1c")
            return content.splitlines(True)

        def apply_angle():
            try:
                changed = rotate_log_range(current_lines(), start_line.get(), end_line.get(),
                                           degrees.get(), sticks.get())
            except (ValueError, TypeError) as error:
                tkmsg.showwarning("角度一括補正", str(error), parent=dialog)
                return
            editor.delete("1.0", "end")
            editor.insert("1.0", "".join(changed))

        def save_as():
            target = filedialog.asksaveasfilename(
                title="補正済みコントローラー記録を保存", initialfile=name + ".txt",
                defaultextension=".txt", filetypes=[("Controller log", "*.txt")], parent=dialog)
            if not target:
                return
            try:
                with open(target, "w", encoding="utf-8", newline="\n") as stream:
                    stream.write("".join(current_lines()))
            except OSError as error:
                tkmsg.showerror("コントローラー記録", str(error), parent=dialog)

        def save_registration():
            try:
                new_lines = current_lines()
                python_replacement_body(new_lines)
            except ValueError as error:
                tkmsg.showwarning("コントローラー記録", str(error), parent=dialog)
                return
            data = self._read_controller_recordings()
            if name not in data:
                tkmsg.showwarning("コントローラー記録", "登録が削除されています。", parent=dialog)
                return
            data[name]["lines"] = new_lines
            self._write_controller_recordings(data)
            if refresh_callback:
                refresh_callback()
            self.commands_assist_status.set("コントローラー記録「{}」を更新しました。".format(name))

        def copy_replacement():
            try:
                body = python_replacement_body(current_lines())
            except ValueError as error:
                tkmsg.showwarning("置換処理", str(error), parent=dialog)
                return
            self.root.clipboard_clear()
            self.root.clipboard_append(body)
            self.commands_assist_status.set("コントローラー記録から置換処理コードをクリップボードへコピーしました。")

        ttk.Button(controls, text="範囲へ角度差を反映", command=apply_angle).pack(side="left", padx=8)
        ttk.Button(controls, text="登録を更新", command=save_registration).pack(side="right", padx=3)
        ttk.Button(controls, text="別名保存", command=save_as).pack(side="right", padx=3)
        ttk.Button(controls, text="置換処理コードをコピー", command=copy_replacement).pack(side="right", padx=3)

