    def _on_recording_mode_tab_changed(self, _event=None):
        if not hasattr(self, "recording_mode_tabs"):
            return
        # The start button shares its text variable between both pages.
        # Force the next UI poll to apply the label for the newly selected mode.
        self._recording_ui_state = None
        selected = self.recording_mode_tabs.select()
        if selected == str(self.recording_monitor_page):
            if ((self.recorder.active or self.record_armed)
                    and self.record_mode.get() != "CommandMonitor"):
                self.recording_mode_tabs.select(self.recording_normal_page)
                return
            if self.record_mode.get() != "CommandMonitor":
                self._recording_normal_mode = self.record_mode.get() or "Manual"
            self.record_mode.set("CommandMonitor")
        elif self.record_mode.get() == "CommandMonitor":
            if self.recorder.active or self.record_armed:
                self.recording_mode_tabs.select(self.recording_monitor_page)
                return
            self.record_mode.set(self._recording_normal_mode or "Manual")

    def _arm_command_monitor_recording(self, show_popup=True):
        if getattr(self, "operation_capture_session", None) is not None:
            if show_popup:
                tkmsg.showinfo(
                    "Commands監視録画",
                    "［操作記録→Commands］のセッションを完了してから開始してください。",
                    parent=self.root)
            self.record_monitor_status.set("開始できません：操作記録セッションを使用中です。")
            return False
        frame = getattr(self.camera, "image_bgr", None)
        if frame is None:
            if show_popup:
                tkmsg.showwarning(
                    "Commands監視録画", "カメラ映像を開始してから監視を開始してください。")
            self.record_monitor_status.set("開始できません：カメラ映像がありません。")
            return False
        if not self._recording_disk_space_ok(show_popup=show_popup, force=True):
            return False
        if not self._confirm_selected_audio_for_use():
            self.record_monitor_status.set("使用中のAudioを反映しなかったため監視を開始していません。")
            return False
        self.record_armed = True
        self._command_monitor_command = None
        self._command_monitor_current_chunk = None
        self._command_monitor_last_check = 0.0
        self._command_monitor_visual_detector.reset()
        self._command_monitor_input_tracker.reset(time.monotonic())
        self.record_monitor_status.set(
            "監視開始：Commands開始を待っています。開始後は自動録画します。")
        self._refresh_command_monitor_tree()
        return True

    def _auto_arm_command_monitor_recording(self):
        if (self.record_mode.get() == "CommandMonitor"
                and self.record_monitor_auto_arm.get() and not self.record_armed):
            if not self._arm_command_monitor_recording(show_popup=True):
                self.show_output(
                    "Analysis", text="Commands監視録画を自動開始できませんでした。Commandsは継続します。")
        if (self.record_mode.get() == "CommandMonitor" and self.record_armed
                and getattr(self, "cur_command", None) is not None):
            # A selected Command object can be reused. Start a distinct session
            # for every Start so Stop cleanup never reaches an earlier run.
            self._command_monitor_begin_session(self.cur_command)

    def open_command_monitor_recording_guide(self):
        path = os.path.join(
            os.path.dirname(os.path.abspath(__file__)),
            "COMMAND_MONITOR_RECORDING_GUIDE.md")
        try:
            with open(path, "r", encoding="utf-8") as stream:
                content = stream.read()
        except OSError as error:
            tkmsg.showerror("Commands監視録画", str(error), parent=self.root)
            return
        dialog = tk.Toplevel(self.root)
        dialog.title("Commands監視録画 - 使い方")
        dialog.geometry("860x680")
        dialog.transient(self.root)
        frame = ttk.Frame(dialog)
        frame.pack(fill="both", expand=True, padx=7, pady=7)
        viewer = tk.Text(frame, wrap="word", padx=10, pady=8)
        scrollbar = ttk.Scrollbar(frame, orient="vertical", command=viewer.yview)
        viewer.configure(yscrollcommand=scrollbar.set)
        viewer.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")
        viewer.insert("1.0", content)
        viewer.configure(state="disabled")
        ttk.Button(dialog, text="閉じる", command=dialog.destroy).pack(pady=(0, 7))

    def open_selected_command_recording_in_dev_studio(self):
        selected = list(self.record_monitor_tree.selection()) \
            if hasattr(self, "record_monitor_tree") else []
        chunks = [chunk for chunk in self._command_monitor_chunks
                  if str(chunk.get("id", "")) in selected]
        if not chunks and self._command_monitor_chunks:
            chunks = [self._command_monitor_chunks[-1]]
        if not chunks:
            tkmsg.showinfo(
                "Commands録画とソース比較",
                "比較する録画を一覧から選んでください。", parent=self.root)
            return
        chunk = chunks[0]
        if chunk is self._command_monitor_current_chunk or chunk.get("merge_pending"):
            tkmsg.showinfo(
                "Commands録画とソース比較",
                "録画または結合の完了後に開いてください。", parent=self.root)
            return
        path = os.path.abspath(str(chunk.get("session_dir", "") or ""))
        if not os.path.isfile(os.path.join(path, "command_monitor.json")):
            tkmsg.showwarning(
                "Commands録画とソース比較",
                "録画情報が見つかりません。\n" + path, parent=self.root)
            return
        self.open_dev_studio(command_recording=path)

    def _select_recording_mode_page(self):
        if not hasattr(self, "recording_mode_tabs"):
            return
        if self.record_mode.get() == "CommandMonitor":
            self.recording_mode_tabs.select(self.recording_monitor_page)
        else:
            self._recording_normal_mode = self.record_mode.get() or "Manual"
            self.recording_mode_tabs.select(self.recording_normal_page)

    @staticmethod
    def _command_monitor_step_text(snapshot):
        if not snapshot:
            return "Step取得待ち"
        return state_path_text(snapshot) or "Step取得待ち"

    def _start_command_monitor_chunk(self, frame, command, now=None):
        now = time.monotonic() if now is None else float(now)
        if self.recorder.active:
            return
        if not self._confirm_selected_audio_for_use():
            self.record_monitor_status.set("使用中のAudioを反映しなかったため録画を開始していません。")
            return
        self._start_capture_recorder(
            frame, self.fps.get(), self._selected_audio_device_name(), self.audio_gain.get(),
            cleanup_rules=[], minimum_duration=0,
            audio_level_options=self._audio_level_options())
        self._sync_audio_device_usage()
        chunk = {
            "id": str(time.time_ns()),
            "session_dir": os.path.abspath(self.recorder.session_dir),
            "started": now,
            "started_wall": datetime.datetime.now().isoformat(timespec="seconds"),
            "ended": None,
            "states": [],
            "pinned": False,
            "loop_anchor": False,
            "delete_pending": False,
            "command": str(getattr(command, "NAME", "")),
            "command_session_id": self._command_monitor_session_id,
            "source": dict(self._command_monitor_source),
            "source_snapshots": {},
        }
        chunk["source"] = self._ensure_command_monitor_source_snapshot(
            chunk, chunk["source"])
        with self._command_monitor_lock:
            self._command_monitor_current_chunk = chunk
        self._command_monitor_chunks.append(chunk)
        self._write_command_monitor_metadata(chunk)
        self._refresh_command_monitor_tree()

    def _ensure_command_monitor_source_snapshot(self, chunk, location):
        """Copy each linked source file once so later edits do not erase evidence."""
        location = dict(location or {})
        source_file = os.path.abspath(str(location.get("file", "") or ""))
        if not source_file or not os.path.isfile(source_file) or not chunk:
            return location
        snapshots = chunk.setdefault("source_snapshots", {})
        relative = snapshots.get(source_file)
        if not relative:
            digest = hashlib.sha1(source_file.lower().encode("utf-8")).hexdigest()[:12]
            safe_name = re.sub(r"[^0-9A-Za-z_.-]+", "_", os.path.basename(source_file))
            relative = os.path.join(
                "source_snapshots", "{}_{}".format(digest, safe_name))
            target = os.path.join(chunk["session_dir"], relative)
            try:
                os.makedirs(os.path.dirname(target), exist_ok=True)
                shutil.copy2(source_file, target)
                snapshots[source_file] = relative
            except OSError as error:
                self._logger.warning("Command source snapshot failed: %s", error)
                return location
        location["snapshot"] = relative
        return location

    def _command_trace_writer_loop(self):
        while True:
            batch = [self._command_trace_queue.get()]
            # A busy command may change source locations many times per
            # second. Drain a bounded burst and append each file once instead
            # of repeatedly opening it; every evidence event is still kept.
            for _ in range(255):
                try:
                    batch.append(self._command_trace_queue.get_nowait())
                except queue.Empty:
                    break
            try:
                by_path = {}
                for item in batch:
                    if item is not None:
                        path, payload = item
                        by_path.setdefault(path, []).append(payload)
                for path, payloads in by_path.items():
                    try:
                        with open(path, "a", encoding="utf-8", newline="\n") as stream:
                            for payload in payloads:
                                json.dump(payload, stream, ensure_ascii=False)
                                stream.write("\n")
                    except OSError as error:
                        logger = getattr(self, "_logger", None)
                        if logger is not None:
                            logger.warning(
                                "Command recording trace write failed: %s", error)
            finally:
                for _ in batch:
                    self._command_trace_queue.task_done()
            if any(item is None for item in batch):
                return

    def _write_command_monitor_event(self, chunk, snapshot, event_name="state",
                                     location=None, now=None, extra=None):
        if not chunk:
            return
        now = time.monotonic() if now is None else float(now)
        step_text = self._command_monitor_step_text(snapshot)
        with self._command_monitor_lock:
            if step_text not in chunk["states"]:
                chunk["states"].append(step_text)
        if location is None:
            location = runtime_execution_location(
                self._command_monitor_command,
                os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
        location = self._ensure_command_monitor_source_snapshot(chunk, location)
        path = os.path.join(chunk["session_dir"], "steps.jsonl")
        payload = {
            "time": datetime.datetime.now().isoformat(timespec="milliseconds"),
            "event": event_name,
            "states": dict(snapshot or {}),
            "step_path": step_text,
            "chunk_time": max(0.0, now - float(chunk.get("started", now))),
            "command_time": max(
                0.0, now - float(self._command_monitor_session_started or now)),
            "location": location,
        }
        if isinstance(extra, dict):
            payload.update(extra)
        self._command_trace_queue.put((path, payload))

    def _write_command_monitor_metadata(self, chunk):
        if not chunk:
            return
        payload = {key: value for key, value in chunk.items()
                   if key not in ("started", "ended")}
        payload["started_monotonic"] = chunk.get("started")
        payload["ended_monotonic"] = chunk.get("ended")
        payload["duration"] = max(
            0.0, (chunk.get("ended") or time.monotonic()) - chunk.get("started", 0.0))
        payload["mode"] = "Commands monitoring recording"
        try:
            with open(os.path.join(chunk["session_dir"], "command_monitor.json"),
                      "w", encoding="utf-8", newline="\n") as stream:
                json.dump(payload, stream, ensure_ascii=False, indent=2)
                stream.write("\n")
        except OSError as error:
            self._logger.warning("Command monitor metadata failed: %s", error)

    def _write_command_monitor_output_log(self, chunk):
        try:
            lines = self._record_log_lines(240)
            with open(os.path.join(chunk["session_dir"], "commands.log"),
                      "w", encoding="utf-8", newline="\n") as stream:
                stream.write("\n".join(lines))
                if lines:
                    stream.write("\n")
        except (OSError, tk.TclError) as error:
            self._logger.warning("Command monitor output log failed: %s", error)

    def _finish_command_monitor_chunk(self, reason="chunk_end", frame=None, restart=False):
        with self._command_monitor_lock:
            chunk = self._command_monitor_current_chunk
        if chunk is None:
            return
        chunk["ended"] = time.monotonic()
        self._write_command_monitor_event(
            chunk, runtime_state_snapshot(self._command_monitor_command), reason)
        self._write_command_monitor_output_log(chunk)
        self._write_command_monitor_metadata(chunk)
        self._stop_capture_recorder()
        self._sync_audio_device_usage()
        with self._command_monitor_lock:
            if self._command_monitor_current_chunk is chunk:
                self._command_monitor_current_chunk = None
        self._refresh_command_monitor_tree()
        if restart and frame is not None and self.record_armed:
            self._start_command_monitor_chunk(
                frame, self._command_monitor_command, time.monotonic())

    def _command_monitor_begin_session(self, command):
        self._command_monitor_command = command
        self._command_monitor_session_id = datetime.datetime.now().strftime(
            "%Y%m%d_%H%M%S_%f")
        self._command_monitor_session_started = time.monotonic()
        self._command_monitor_source = command_source_descriptor(command)
        self._command_monitor_last_location_key = ()
        self._command_monitor_last_snapshot = {}
        try:
            loop_cycles = max(2, int(self.record_monitor_loop_cycles.get()))
        except (tk.TclError, TypeError, ValueError):
            loop_cycles = 3
            self.record_monitor_loop_cycles.set(loop_cycles)
        self._command_monitor_timeline.reset(loop_cycles=loop_cycles)
        self._command_monitor_visual_detector.reset()
        self._command_monitor_input_tracker.reset(time.monotonic())
        self._command_monitor_failure_capture_until = None
        self._command_monitor_failure_capture_mode = ""
        self._command_monitor_last_check = 0.0
        self._command_monitor_last_trace_check = 0.0
        self.record_monitor_status.set(
            "監視中: {} / Stepを自動検出しています".format(
                getattr(command, "NAME", "Commands")))

    def _update_command_monitor_state(self, command, now):
        state_due = now - self._command_monitor_last_check >= 0.25
        trace_due = now - self._command_monitor_last_trace_check >= 0.10
        if not state_due and not trace_due:
            return {"changed": False, "loop_started": False,
                    "loop_ended": False}
        if state_due:
            self._command_monitor_last_check = now
        if trace_due:
            self._command_monitor_last_trace_check = now
        if state_due or not self._command_monitor_last_snapshot:
            snapshot = runtime_state_snapshot(command)
            self._command_monitor_last_snapshot = dict(snapshot)
        else:
            snapshot = dict(self._command_monitor_last_snapshot)
        result = self._command_monitor_timeline.add(snapshot, now) if state_due else {
            "changed": False, "loop_started": False, "loop_ended": False,
        }
        location = runtime_execution_location(
            command, os.path.dirname(os.path.dirname(os.path.abspath(__file__)))) \
            if trace_due else {}
        if result.get("changed") and not location:
            location = runtime_execution_location(
                command, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
        location_key = execution_location_key(location)
        location_changed = bool(location_key and
                                location_key != self._command_monitor_last_location_key)
        if result.get("changed") or location_changed:
            self._write_command_monitor_event(
                self._command_monitor_current_chunk, snapshot,
                "state_changed" if result.get("changed") else "execution",
                location=location, now=now)
            if location_key:
                self._command_monitor_last_location_key = location_key
        if result.get("changed"):
            if result.get("loop_started"):
                loop = result.get("loop") or {}
                for chunk in self._command_monitor_chunks:
                    end = chunk.get("ended") or now
                    if end >= loop.get("anchor_start", now) and chunk.get("started", now) <= loop.get("anchor_end", now):
                        chunk["loop_anchor"] = True
                        self._write_command_monitor_metadata(chunk)
                self.record_monitor_status.set(
                    "ループ検出: {}Step × {}周 / ループ前と最初の周回だけを保持".format(
                        loop.get("period", 0), self.record_monitor_loop_cycles.get()))
            elif result.get("loop_ended"):
                for chunk in self._command_monitor_chunks:
                    if not chunk.get("pinned"):
                        chunk["loop_anchor"] = False
                        self._write_command_monitor_metadata(chunk)
                self.record_monitor_status.set(
                    "ループ終了を検出しました。開始側の一時保持を解除します。")
            else:
                self.record_monitor_status.set(
                    "監視中: " + self._command_monitor_step_text(snapshot))
        if state_due:
            self._mark_command_monitor_prune_candidates(now)
        return result

    def _update_command_monitor_visual_state(self, frame, now):
        """Detect only a sustained black/still failure, never a normal static menu."""
        result = self._command_monitor_visual_detector.add(frame, now)
        if result.get("stall_started"):
            active = result.get("active") or {}
            self._write_command_monitor_event(
                self._command_monitor_current_chunk,
                self._command_monitor_last_snapshot,
                "dark_still_detected", now=now,
                extra={
                    "brightness": active.get("brightness"),
                    "frame_difference": active.get("difference"),
                    "failure_started_at": active.get("started_at"),
                })
            self.record_monitor_status.set(
                "暗転・画面停止を検出しました。停止開始から約{}秒まで原因確認映像を記録します。".format(
                    int(self._command_monitor_failure_tail_seconds())))
        elif result.get("recovered"):
            self._write_command_monitor_event(
                self._command_monitor_current_chunk,
                self._command_monitor_last_snapshot,
                "dark_still_recovered", now=now)
            self.record_monitor_status.set("画面変化が戻ったため、暗転停止の保持制限を解除しました。")
        return result

    def _record_command_key_activity(self, _payload, priority=False):
        """Sender callback: update a timestamp only; never touch Tk here."""
        if priority:
            return
        tracker = getattr(self, "_command_monitor_input_tracker", None)
        command = getattr(self, "cur_command", None)
        if (tracker is not None and command is not None
                and command is getattr(self, "_command_monitor_command", None)
                and getattr(command, "alive", False)):
            tracker.mark_activity(time.monotonic())

    def _update_command_monitor_input_state(self, now):
        result = self._command_monitor_input_tracker.check(now)
        if result.get("stall_started"):
            active = result.get("active") or {}
            self._write_command_monitor_event(
                self._command_monitor_current_chunk,
                self._command_monitor_last_snapshot,
                "key_inactivity_detected", now=now,
                extra={
                    "last_key_activity_at": active.get("started_at"),
                    "idle_seconds": active.get("idle_seconds"),
                })
            self.record_monitor_status.set(
                "キー操作が60秒間ありません。停止開始から約{}秒分を原因確認映像として保持します。".format(
                    int(self._command_monitor_failure_tail_seconds())))
        elif result.get("recovered"):
            self._write_command_monitor_event(
                self._command_monitor_current_chunk,
                self._command_monitor_last_snapshot,
                "key_activity_recovered", now=now)
            self.record_monitor_status.set("60秒以内にキー操作が再開したため、無操作判定を解除しました。")
        return result

    def _mark_command_monitor_prune_candidates(self, now=None,
                                               explicit_stop=False):
        now = time.monotonic() if now is None else float(now)
        visual = getattr(self._command_monitor_visual_detector, "active", None)
        inactivity = getattr(self._command_monitor_input_tracker, "active", None)
        terminals = []
        tail_seconds = self._command_monitor_failure_tail_seconds()
        if isinstance(visual, dict):
            started = float(visual.get("started_at", now))
            terminals.append((failure_evidence_end(
                started, now, tail_seconds), "dark_still", started))
        if isinstance(inactivity, dict):
            started = float(inactivity.get("started_at", now))
            terminals.append((failure_evidence_end(
                started, now, tail_seconds),
                              "key_inactivity", started))
        if explicit_stop and not terminals and self._command_monitor_timeline.events:
            # An explicit Stop means the current Step is the suspected problem
            # even when loop/dark/input detectors have not fired yet.
            started = float(self._command_monitor_timeline.events[-1]["time"])
            terminals.append((failure_evidence_end(
                started, now, tail_seconds), "manual_stop", started))
        if terminals:
            terminal_time, terminal_mode, terminal_started_at = min(
                terminals, key=lambda value: value[0])
        else:
            terminal_time, terminal_mode, terminal_started_at = None, "", None
        try:
            retention = self._command_monitor_timeline.retention(
                now,
                keep_unique_steps=max(1, int(self.record_monitor_keep_steps.get())),
                long_step_seconds=max(30.0, float(self.record_monitor_long_seconds.get())),
                loop_cycles=max(2, int(self.record_monitor_loop_cycles.get())),
                terminal_time=terminal_time,
                terminal_mode=terminal_mode,
                terminal_started_at=terminal_started_at,
            )
        except (tk.TclError, TypeError, ValueError):
            return None
        keep_after = retention["keep_after"]
        keep_before = retention.get("keep_before")
        anchors = retention["loop_anchors"]
        for chunk in self._command_monitor_chunks:
            if (chunk is self._command_monitor_current_chunk or chunk.get("pinned")
                    or chunk.get("merge_pending")):
                chunk["delete_pending"] = False
                continue
            end = chunk.get("ended") or now
            overlaps_anchor = any(
                end >= start and chunk.get("started", end) <= finish
                for start, finish in anchors)
            if keep_before is not None:
                keep = end >= keep_after and chunk.get("started", end) <= keep_before
            else:
                keep = end >= keep_after or overlaps_anchor or (
                    chunk.get("loop_anchor") and self._command_monitor_timeline.active_loop)
            chunk["delete_pending"] = not keep
        self._flush_command_monitor_deletes()
        self._refresh_command_monitor_tree()
        return retention

    def _command_monitor_failure_tail_seconds(self):
        try:
            return max(10.0, min(
                300.0, float(self.record_monitor_failure_tail_seconds.get())))
        except (tk.TclError, TypeError, ValueError):
            return 60.0

    def _queue_command_monitor_folder_delete(self, path, output_root=None):
        root = os.path.abspath(
            output_root or self._effective_record_output_dir())
        target = os.path.abspath(path)
        try:
            safe = os.path.commonpath([root, target]) == root and target != root
        except ValueError:
            safe = False
        if not safe:
            return False
        if not os.path.isdir(target):
            return True
        self._command_monitor_delete_queue.put_nowait(target)
        return True

    def _command_monitor_delete_loop(self):
        """Delete large video folders without ever blocking Tk or input."""
        while True:
            target = self._command_monitor_delete_queue.get()
            try:
                if os.path.isdir(target):
                    shutil.rmtree(target)
            except OSError as error:
                self._logger.warning("Command monitor cleanup failed: %s", error)
            finally:
                self._command_monitor_delete_queue.task_done()

    def _flush_command_monitor_deletes(self):
        if self.recorder.is_finalizing:
            return False
        before = len(self._command_monitor_chunks)
        kept = []
        for chunk in self._command_monitor_chunks:
            if (chunk.get("delete_pending") and not chunk.get("pinned")
                    and not chunk.get("merge_pending")
                    and chunk is not self._command_monitor_current_chunk):
                try:
                    if not self._queue_command_monitor_folder_delete(
                            chunk["session_dir"]):
                        kept.append(chunk)
                except OSError as error:
                    self._logger.warning("Command monitor cleanup failed: %s", error)
                    kept.append(chunk)
            else:
                kept.append(chunk)
        self._command_monitor_chunks = kept
        return len(kept) != before

    def _load_command_monitor_chunks(self):
        root = os.path.abspath(self._effective_record_output_dir())
        loaded = []
        try:
            names = sorted(os.listdir(root)) if os.path.isdir(root) else []
        except OSError:
            names = []
        now = time.monotonic()
        for name in names:
            session_dir = os.path.abspath(os.path.join(root, name))
            metadata_path = os.path.join(session_dir, "command_monitor.json")
            if not os.path.isfile(metadata_path):
                continue
            try:
                with open(metadata_path, "r", encoding="utf-8") as stream:
                    value = json.load(stream)
                if not isinstance(value, dict):
                    continue
                duration = max(0.0, float(value.get("duration", 0.0) or 0.0))
                chunk_id = str(value.get("id") or "history-" + name)
                if any(item["id"] == chunk_id for item in loaded):
                    chunk_id += "-" + name
                loaded.append({
                    "id": chunk_id,
                    "session_dir": session_dir,
                    "started": 0.0,
                    "started_wall": str(value.get("started_wall", name)),
                    "ended": 0.0,
                    "states": [str(item) for item in value.get("states", [])],
                    "pinned": bool(value.get("pinned", False)),
                    "loop_anchor": False,
                    "delete_pending": False,
                    "command": str(value.get("command", "")),
                    "command_session_id": str(value.get("command_session_id", "")),
                    "merged": bool(value.get("merged", False)),
                    "source_chunk_ids": [str(item) for item in
                                         value.get("source_chunk_ids", [])],
                    "source": dict(value.get("source", {}) or {}),
                    "sources": [dict(item) for item in value.get("sources", [])
                                if isinstance(item, dict)],
                    "source_snapshots": dict(
                        value.get("source_snapshots", {}) or {}),
                    "historical": True,
                    "duration_saved": duration,
                })
            except (OSError, TypeError, ValueError):
                continue
        # Rebuild the old chunks as one chronological tail.  Giving every old
        # chunk the same end time made all of them look current forever.
        cursor = now
        for chunk in reversed(loaded):
            duration = float(chunk.get("duration_saved", 0.0) or 0.0)
            chunk["ended"] = cursor
            chunk["started"] = cursor - duration
            cursor = chunk["started"]
        keep_ids = historical_retention_ids(
            loaded,
            keep_unique_steps=max(1, int(self.record_monitor_keep_steps.get())),
            long_step_seconds=max(30.0, float(self.record_monitor_long_seconds.get())),
            loop_cycles=max(2, int(self.record_monitor_loop_cycles.get())),
        )
        for chunk in loaded:
            if not chunk.get("pinned") and chunk["id"] not in keep_ids:
                chunk["delete_pending"] = True
        loaded_count = len(loaded)
        self._command_monitor_chunks = loaded
        self._command_monitor_current_chunk = None
        self._flush_command_monitor_deletes()
        deleted_count = loaded_count - len(self._command_monitor_chunks)
        if self._command_monitor_chunks:
            self.record_monitor_status.set(
                "前回までのCommands監視録画を{}本読み込み、不要な{}本を自動削除しました。".format(
                    len(self._command_monitor_chunks), deleted_count))
        self._refresh_command_monitor_tree()

    def _refresh_command_monitor_tree(self):
        if not hasattr(self, "record_monitor_tree"):
            return
        selected_ids = set(self.record_monitor_tree.selection())
        self.record_monitor_tree.delete(*self.record_monitor_tree.get_children())
        now = time.monotonic()
        for chunk in self._command_monitor_chunks:
            if chunk is self._command_monitor_current_chunk:
                status = "録画中"
            elif chunk.get("merge_pending"):
                status = "結合中"
            elif chunk.get("pinned"):
                status = "保護"
            elif chunk.get("merged"):
                status = "統合済み"
            elif chunk.get("delete_pending"):
                status = "削除待ち"
            elif chunk.get("loop_anchor"):
                status = "ループ保持"
            elif chunk.get("historical"):
                status = "前回一時"
            else:
                status = "一時"
            duration = max(
                0.0, (chunk.get("ended") or now) - chunk.get("started", now))
            if chunk.get("historical"):
                duration = float(chunk.get("duration_saved", duration))
            iid = chunk["id"]
            self.record_monitor_tree.insert(
                "", "end", iid=iid, values=(
                    status, chunk.get("started_wall", ""), "{:.1f}".format(duration),
                    " / ".join(chunk.get("states", [])[-3:]) or "-",
                    os.path.basename(chunk.get("session_dir", ""))))
            if iid in selected_ids:
                self.record_monitor_tree.selection_add(iid)
        temporary = sum(1 for chunk in self._command_monitor_chunks
                        if not chunk.get("pinned"))
        protected = sum(1 for chunk in self._command_monitor_chunks
                        if chunk.get("pinned"))
        pending = sum(1 for chunk in self._command_monitor_chunks
                      if chunk.get("delete_pending"))
        self.record_monitor_counts.set(
            "一時 {}本 / 保護 {}本 / 削除待ち {}本".format(
                temporary, protected, pending))

    def protect_command_monitor_recordings(self):
        if not self._command_monitor_chunks:
            tkmsg.showinfo("Commands監視録画", "現在保持されている録画はありません。")
            return
        for chunk in self._command_monitor_chunks:
            chunk["pinned"] = True
            chunk["delete_pending"] = False
            self._write_command_monitor_metadata(chunk)
        self.record_monitor_status.set(
            "現在保持されている録画とログを保護しました。自動削除されません。")
        self._refresh_command_monitor_tree()

    def stop_command_for_adjustment_with_recordings(self):
        self.protect_command_monitor_recordings()
        command = getattr(self, "cur_command", None)
        if command is not None and getattr(command, "alive", False):
            self.stopPlay()

    def toggle_selected_command_monitor_chunks(self):
        selected = set(self.record_monitor_tree.selection())
        if not selected:
            tkmsg.showinfo("Commands監視録画", "保護を切り替える録画を選択してください。")
            return
        for chunk in self._command_monitor_chunks:
            if chunk["id"] in selected:
                chunk["pinned"] = not chunk.get("pinned")
                chunk["delete_pending"] = False
                self._write_command_monitor_metadata(chunk)
        self._refresh_command_monitor_tree()

    def discard_command_monitor_temporary(self):
        targets = [chunk for chunk in self._command_monitor_chunks
                   if not chunk.get("pinned")]
        if not targets:
            tkmsg.showinfo("Commands監視録画", "破棄できる一時録画はありません。")
            return
        if not tkmsg.askyesno(
                "Commands監視録画",
                "保護されていない一時録画{}本を破棄しますか？\n"
                "保護録画は削除されません。".format(len(targets))):
            return
        if self._command_monitor_current_chunk in targets:
            self._finish_command_monitor_chunk("manual_discard")
        for chunk in targets:
            chunk["delete_pending"] = True
        self._flush_command_monitor_deletes()
        self.record_monitor_status.set("保護されていない一時録画を破棄しました。")
        self._refresh_command_monitor_tree()

    def _request_command_monitor_stop_cleanup(self, command):
        """Remember an explicit Stop without including natural command exits."""
        enabled = (getattr(self, "record_monitor_confirm_delete_on_stop", None)
                   is not None
                   and self.record_monitor_confirm_delete_on_stop.get())
        if (not enabled or getattr(self, "record_mode", None) is None
                or self.record_mode.get() != "CommandMonitor"
                or command is None
                or command is not getattr(self, "_command_monitor_command", None)):
            return
        self._command_monitor_stop_cleanup_command = command
        self._command_monitor_stop_cleanup_session_id = str(
            getattr(self, "_command_monitor_session_id", "") or "")

    def _stop_command_monitor_capture_on_request(self, command, reason):
        """Bound and stop recording immediately, even if Commands cannot exit."""
        if (getattr(self, "record_mode", None) is None
                or self.record_mode.get() != "CommandMonitor"
                or command is None
                or command is not getattr(self, "_command_monitor_command", None)):
            return False
        self.record_armed = False
        if self._command_monitor_current_chunk is not None:
            self._finish_command_monitor_chunk(reason)
        retention = self._mark_command_monitor_prune_candidates(
            time.monotonic(), explicit_stop=True) or {}
        mode = retention.get("mode")
        if mode == "loop":
            message = "Stop時に録画を確定しました。ループ前{} Stepと最初の{}周だけを保持します。".format(
                self.record_monitor_keep_steps.get(), self.record_monitor_loop_cycles.get())
        elif mode == "dark_still":
            message = (
                "Stop時に録画を確定しました。暗転・画面停止の開始から最大{}秒の原因確認映像を保持します。"
            ).format(int(self._command_monitor_failure_tail_seconds()))
        elif mode == "key_inactivity":
            message = (
                "Stop時に録画を確定しました。最後のキー操作から最大{}秒の原因確認映像を保持します。"
            ).format(int(self._command_monitor_failure_tail_seconds()))
        elif mode == "manual_stop":
            message = (
                "Stop時に録画を確定しました。問題Stepの前{} Stepから、"
                "問題Step開始後最大{}秒までを保存候補にします。"
            ).format(
                self.record_monitor_keep_steps.get(),
                int(self._command_monitor_failure_tail_seconds()))
        else:
            message = "Stop時にCommands監視録画を停止し、直近の有効なStep範囲だけを保持します。"
        self.record_monitor_status.set(message)
        self._refresh_command_monitor_tree()
        return True

    def _consume_command_monitor_stop_cleanup(self, command):
        if (command is None
                or command is not getattr(
                    self, "_command_monitor_stop_cleanup_command", None)):
            return ""
        session_id = str(getattr(
            self, "_command_monitor_stop_cleanup_session_id", "") or "")
        self._command_monitor_stop_cleanup_command = None
        self._command_monitor_stop_cleanup_session_id = ""
        return session_id

    def _merge_stopped_command_monitor_recordings(self, session_id, target_ids):
        target_ids = {str(value) for value in target_ids}
        targets = [chunk for chunk in self._command_monitor_chunks
                   if str(chunk.get("id", "")) in target_ids]
        if len(targets) < 2:
            self.record_monitor_status.set(
                "今回のCommands録画は1本のため、そのまま保持しました。")
            self._refresh_command_monitor_tree()
            return
        for chunk in targets:
            chunk["merge_pending"] = True
            chunk["delete_pending"] = False
            self._write_command_monitor_metadata(chunk)
        self.record_monitor_status.set(
            "今回のCommands仮録画{}本を1本へ結合しています。元録画は成功まで保持します。".format(
                len(targets)))
        self._refresh_command_monitor_tree()
        output_root = os.path.abspath(self._effective_record_output_dir())
        with self._command_monitor_merge_lock:
            self._command_monitor_merge_active += 1

        def finish_merge(merged=None, error=None):
            current_by_id = {
                str(chunk.get("id", "")): chunk
                for chunk in self._command_monitor_chunks
            }
            current_targets = [current_by_id[value] for value in target_ids
                               if value in current_by_id]
            if error is not None:
                for chunk in current_targets:
                    chunk["merge_pending"] = False
                    self._write_command_monitor_metadata(chunk)
                self.record_monitor_status.set(
                    "録画の結合に失敗しました。分割録画は削除せず保持しています。")
                self._refresh_command_monitor_tree()
                tkmsg.showwarning(
                    "Commands録画の結合",
                    "録画を1本に結合できませんでした。元の分割録画は残しています。\n\n{}".format(
                        error), parent=self.root)
                return

            insert_at = min(
                (self._command_monitor_chunks.index(chunk) for chunk in current_targets),
                default=len(self._command_monitor_chunks))
            self._command_monitor_chunks = [
                chunk for chunk in self._command_monitor_chunks
                if str(chunk.get("id", "")) not in target_ids]
            self._command_monitor_chunks.insert(
                min(insert_at, len(self._command_monitor_chunks)), merged)
            for chunk in current_targets:
                self._queue_command_monitor_folder_delete(
                    chunk.get("session_dir", ""), output_root=output_root)
            self.record_monitor_status.set(
                "今回のCommands仮録画{}本を1本へ結合して保持しました。".format(
                    len(current_targets)))
            self._refresh_command_monitor_tree()

        def worker():
            merged = None
            error = None
            try:
                # CaptureRecorder finalizes each short clip asynchronously.
                # Do not read its AVI/WAV files until all writers/muxers have
                # released them.  This wait never blocks Tk or controller I/O.
                deadline = time.monotonic() + 600.0
                while self.recorder.is_finalizing and time.monotonic() < deadline:
                    time.sleep(0.2)
                if self.recorder.is_finalizing:
                    raise TimeoutError("分割録画の保存完了を10分以内に確認できませんでした。")
                # Source/Step events use a dedicated writer so they never
                # delay controller input.  Flush it before reading the chunks.
                self._command_trace_queue.join()
                merged = merge_command_recording_chunks(
                    targets, output_root, session_id)
            except Exception as caught:
                error = caught

            def apply_result(result=merged, failure=error):
                try:
                    finish_merge(result, failure)
                finally:
                    with self._command_monitor_merge_lock:
                        self._command_monitor_merge_active = max(
                            0, self._command_monitor_merge_active - 1)

            self._gui_action_queue.put(apply_result)

        threading.Thread(
            target=worker, daemon=True,
            name="CommandMonitorRecordingMerge").start()

    def _confirm_save_stopped_command_monitor_recordings(self, session_id):
        target_ids = temporary_chunk_ids_for_session(
            self._command_monitor_chunks, session_id)
        session_ids = {
            str(chunk.get("id", ""))
            for chunk in self._command_monitor_chunks
            if (str(chunk.get("command_session_id", "")) == str(session_id)
                and not chunk.get("historical")
                and not chunk.get("delete_pending")
                and chunk.get("id") not in (None, ""))
        }
        if not target_ids:
            # "調整停止＋保護" already expresses a keep decision, so there is
            # nothing to ask about saving.  Still collapse that run to one
            # protected recording when it produced several chunks.
            if len(session_ids) > 1:
                self._merge_stopped_command_monitor_recordings(
                    session_id, session_ids)
            return
        targets = [chunk for chunk in self._command_monitor_chunks
                   if str(chunk.get("id", "")) in target_ids]
        if tkmsg.askyesno(
                "Commands録画の保存",
                "今回のCommands実行で作成した録画が{}本あります。\n"
                "問題確認用として保存しますか？\n\n"
                "［はい］1本へ結合して保護保存　［いいえ］今回分だけ削除\n"
                "保護した録画と過去の実行分は削除されません。".format(len(targets))):
            saved_ids = apply_stopped_session_recording_choice(
                self._command_monitor_chunks, session_id, save=True)
            for chunk in self._command_monitor_chunks:
                if str(chunk.get("id", "")) in saved_ids:
                    self._write_command_monitor_metadata(chunk)
            self._merge_stopped_command_monitor_recordings(
                session_id, session_ids)
            return
        deleted_ids = apply_stopped_session_recording_choice(
            self._command_monitor_chunks, session_id, save=False)
        for chunk in self._command_monitor_chunks:
            if str(chunk.get("id", "")) in deleted_ids:
                self._write_command_monitor_metadata(chunk)
        self._flush_command_monitor_deletes()
        self.record_monitor_status.set(
            "今回のCommands録画{}本を削除待ちにしました。".format(len(targets)))
        self._refresh_command_monitor_tree()

    def _command_monitor_failure_active(self):
        return bool(
            self._command_monitor_timeline.active_loop
            or getattr(self._command_monitor_visual_detector, "active", None)
            or getattr(self._command_monitor_input_tracker, "active", None))

    def _process_command_monitor_frame(self, frame):
        if not self.record_armed:
            return
        command = getattr(self, "cur_command", None)
        if command is None or not getattr(command, "alive", False):
            if self._command_monitor_current_chunk is not None:
                self._finish_command_monitor_chunk("command_stopped")
                self.record_monitor_status.set(
                    "Commands停止を検出しました。録画は確認待ちで保持しています。")
            else:
                self.record_monitor_status.set("Commands開始待ちです。")
            return
        if command is not self._command_monitor_command:
            if self._command_monitor_current_chunk is not None:
                self._finish_command_monitor_chunk("command_changed")
            self._command_monitor_begin_session(command)
        now = time.monotonic()
        if not self.recorder.active and not self._command_monitor_failure_active():
            if not self._recording_disk_space_ok(show_popup=True, force=True):
                self._interrupt_recording_for_disk_space()
                return
            self._start_command_monitor_chunk(frame, command, now)
            snapshot = runtime_state_snapshot(command)
            self._command_monitor_last_snapshot = dict(snapshot)
            self._command_monitor_timeline.add(snapshot, now)
            location = runtime_execution_location(
                command, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
            self._command_monitor_last_location_key = execution_location_key(location)
            self._write_command_monitor_event(
                self._command_monitor_current_chunk, snapshot, "recording_started",
                location=location, now=now)
        state_result = self._update_command_monitor_state(command, now)
        visual_result = self._update_command_monitor_visual_state(frame, now)
        input_result = self._update_command_monitor_input_state(now)
        evidence_started = bool(
            state_result.get("loop_started") or visual_result.get("stall_started")
            or input_result.get("stall_started"))
        bounded_for_evidence = False
        if evidence_started and self._command_monitor_current_chunk is not None:
            if state_result.get("loop_started"):
                reason = "loop_evidence_bounded"
                self._finish_command_monitor_chunk(reason)
                self._mark_command_monitor_prune_candidates(now)
                bounded_for_evidence = True
            else:
                active = ((input_result.get("active")
                           if input_result.get("stall_started") else None)
                          or visual_result.get("active") or {})
                started_at = float(active.get("started_at", now))
                self._command_monitor_failure_capture_until = (
                    started_at + self._command_monitor_failure_tail_seconds())
                self._command_monitor_failure_capture_mode = (
                    "key_inactivity" if input_result.get("stall_started")
                    else "dark_still")

        failure_until = self._command_monitor_failure_capture_until
        if (failure_until is not None
                and self._command_monitor_current_chunk is not None
                and now >= float(failure_until)):
            reason = "{}_evidence_60s_bounded".format(
                self._command_monitor_failure_capture_mode or "failure")
            self._finish_command_monitor_chunk(reason)
            self._mark_command_monitor_prune_candidates(now)
            self.record_monitor_status.set(
                "停止開始から約{}秒の原因確認映像を保持しました。復帰するまで後続の無変化映像は破棄します。".format(
                    int(self._command_monitor_failure_tail_seconds())))
            self._command_monitor_failure_capture_until = None
            self._command_monitor_failure_capture_mode = ""
            bounded_for_evidence = True
        recovered = bool(
            state_result.get("loop_ended") or visual_result.get("recovered")
            or input_result.get("recovered"))
        if recovered:
            self._command_monitor_failure_capture_until = None
            self._command_monitor_failure_capture_mode = ""
            self._mark_command_monitor_prune_candidates(now)
            if (not self._command_monitor_failure_active()
                    and not self.recorder.active):
                self._start_command_monitor_chunk(frame, command, now)
                snapshot = runtime_state_snapshot(command)
                self._command_monitor_last_snapshot = dict(snapshot)
                self._write_command_monitor_event(
                    self._command_monitor_current_chunk, snapshot,
                    "recording_resumed", now=now)
        try:
            chunk_seconds = max(10.0, float(self.record_monitor_chunk_seconds.get()))
        except (tk.TclError, TypeError, ValueError):
            chunk_seconds = 30.0
        if (not bounded_for_evidence
                and self._command_monitor_current_chunk is not None
                and now - self._command_monitor_current_chunk["started"] >= chunk_seconds):
            self._finish_command_monitor_chunk(
                "chunk_rotated", frame=frame, restart=True)
        if self.recorder.active:
            self._queue_recording_frame(frame)

    def _apply_record_output_dir(self):
        """Apply the destination to the next recording without moving active files."""
        self.recorder.output_dir = self._effective_record_output_dir()

    def _record_output_dir_changed(self, *_):
        self._apply_record_output_dir()
        if (hasattr(self, "_command_monitor_chunks")
                and not self.record_armed and not self.recorder.active):
            self._load_command_monitor_chunks()

    def choose_record_output_dir(self):
        from tkinter import filedialog
        current = self.record_output_dir.get().strip()
        initial = current if current and os.path.isdir(current) else os.path.abspath("Recordings")
        path = filedialog.askdirectory(title="録画の保存先を選択", initialdir=initial)
        if path:
            self.record_output_dir.set(os.path.abspath(path))
            self._apply_record_output_dir()

    def clear_record_output_dir(self):
        self.record_output_dir.set("")
        self._apply_record_output_dir()

    def open_record_output_dir(self):
        directory = self._effective_record_output_dir()
        try:
            os.makedirs(directory, exist_ok=True)
            if platform.system() == "Windows":
                subprocess.Popen(["explorer", directory])
            elif platform.system() == "Darwin":
                subprocess.Popen(["open", directory])
            else:
                subprocess.Popen(["xdg-open", directory])
        except OSError as error:
            tkmsg.showerror("Recording", "保存先を開けませんでした。\n" + str(error))

    def configure_recording_rules(self):
        """Apply saved multi-image AND rules and post-recording discard rules."""
        valid_trigger = [rule for rule in self.record_trigger_rules if rule.get("path")]
        self.recorder.configure_trigger_rules(valid_trigger)
        self.recorder.configure_cleanup_rules(self.record_cleanup_rules, self.record_minimum_duration.get())

    def _recording_presets_path(self):
        return os.path.join(os.path.dirname(Settings.GuiSettings.SETTING_PATH), "recording_presets.json")

    def _read_recording_presets(self):
        path = self._recording_presets_path()
        try:
            with open(path, "r", encoding="utf-8") as file:
                data = json.load(file)
            return data if isinstance(data, dict) else {}
        except (OSError, ValueError):
            return {}

    def _write_recording_presets(self, data):
        path = self._recording_presets_path()
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as file:
            json.dump(data, file, ensure_ascii=False, indent=2)

    def refresh_recording_presets(self):
        if hasattr(self, "recording_preset_cb"):
            self.recording_preset_cb.configure(values=sorted(self._read_recording_presets().keys()))
        if hasattr(self, "input_recording_record_cb"):
            self.refresh_input_sets()

    def _recording_preset_data(self):
        return {
            "mode": self.record_mode.get(),
            "output_dir": self.record_output_dir.get().strip(),
            "template_path": self.record_template_path.get(),
            "threshold": self.record_threshold.get(),
            "interval": self.record_interval.get(),
            "release_seconds": self.record_release.get(),
            "roi": self.record_roi.get(),
            "debug": self.record_debug.get(),
            "trigger_rules": self.record_trigger_rules,
            "cleanup_rules": self.record_cleanup_rules,
            "minimum_duration": self.record_minimum_duration.get(),
            "min_free_gb": self.record_min_free_gb.get(),
            "max_disk_usage_percent": self.record_max_disk_usage_percent.get(),
            "variable_command": self.record_variable_command.get(),
            "variable_name": self.record_variable_name.get(),
            "variable_start": self.record_variable_start.get(),
            "variable_stop": self.record_variable_stop.get(),
            "variable_rules": self.record_variable_rules,
            "output_mode": self.record_output_mode.get(),
            "output_logs": self.record_output_logs.get(),
            "output_guide": self.record_output_guide.get(),
            "output_value": self.record_output_value.get(),
            "output_detection": self.record_output_detection.get(),
            "monitor_chunk_seconds": self.record_monitor_chunk_seconds.get(),
            "monitor_keep_steps": self.record_monitor_keep_steps.get(),
            "monitor_loop_cycles": self.record_monitor_loop_cycles.get(),
            "monitor_long_seconds": self.record_monitor_long_seconds.get(),
            "monitor_failure_tail_seconds": self.record_monitor_failure_tail_seconds.get(),
            "monitor_auto_arm": self.record_monitor_auto_arm.get(),
            "monitor_confirm_delete_on_stop": self.record_monitor_confirm_delete_on_stop.get(),
        }

    def save_recording_preset(self):
        name = self.recording_preset_name.get().strip()
        if not name:
            tkmsg.showwarning("Recording set", "Enter a set name.")
            return
        data = self._read_recording_presets()
        data[name] = self._recording_preset_data()
        self._write_recording_presets(data)
        self.refresh_recording_presets()

    def load_recording_preset(self):
        name = self.recording_preset_name.get().strip()
        data = self._read_recording_presets().get(name)
        if not data:
            tkmsg.showwarning("Recording set", "Select a saved recording set.")
            return
        self._apply_recording_preset_data(
            data, show_limited_warning=True)

    def _apply_recording_preset_data(
            self, data, show_limited_warning=False):
        """Apply recording data from a preset or an all-tab InputSet snapshot."""
        self.record_mode.set(data.get("mode", "Manual"))
        self.record_output_dir.set(data.get("output_dir", ""))
        self._apply_record_output_dir()
        self.record_template_path.set(data.get("template_path", ""))
        self.record_threshold.set(data.get("threshold", 0.9))
        self.record_interval.set(data.get("interval", 0.5))
        self.record_release.set(data.get("release_seconds", 1.0))
        self.record_roi.set(data.get("roi", "0,0,0,0"))
        self.record_debug.set(data.get("debug", False))
        self.record_trigger_rules = data.get("trigger_rules", [])
        self.record_cleanup_rules = data.get("cleanup_rules", [])
        self.record_minimum_duration.set(data.get("minimum_duration", 0))
        self.record_min_free_gb.set(data.get("min_free_gb", 5.0))
        self.record_max_disk_usage_percent.set(data.get("max_disk_usage_percent", 95.0))
        self.record_variable_command.set(data.get("variable_command", ""))
        self.record_variable_name.set(data.get("variable_name", "current_step"))
        self.record_variable_start.set(data.get("variable_start", ""))
        self.record_variable_stop.set(data.get("variable_stop", ""))
        self.record_variable_rules = data.get("variable_rules", [])
        self.record_output_mode.set(data.get("output_mode", "Video only"))
        self.record_output_logs.set(data.get("output_logs", "Output#1"))
        self.record_output_guide.set(data.get("output_guide", False))
        self.record_output_value.set(data.get("output_value", False))
        self.record_output_detection.set(data.get("output_detection", True))
        self.record_monitor_chunk_seconds.set(data.get("monitor_chunk_seconds", 30.0))
        self.record_monitor_keep_steps.set(data.get("monitor_keep_steps", 15))
        self.record_monitor_loop_cycles.set(data.get("monitor_loop_cycles", 3))
        self.record_monitor_long_seconds.set(data.get("monitor_long_seconds", 180.0))
        self.record_monitor_failure_tail_seconds.set(
            data.get("monitor_failure_tail_seconds", 60.0))
        self.record_monitor_auto_arm.set(data.get("monitor_auto_arm", True))
        self.record_monitor_confirm_delete_on_stop.set(
            data.get("monitor_confirm_delete_on_stop", True))
        self._select_recording_mode_page()
        self.configure_recording_rules()
        if not self.record_trigger_rules:
            self.recorder.configure_template(self.record_template_path.get())
        self.toggle_record_debug(
            show_limited_warning=show_limited_warning)

    def delete_recording_preset(self):
        name = self.recording_preset_name.get().strip()
        data = self._read_recording_presets()
        if name not in data:
            tkmsg.showwarning("Recording set", "Select a saved recording set.")
            return
        if tkmsg.askyesno("Recording set", "Delete recording set '" + name + "'?"):
            del data[name]
            self._write_recording_presets(data)
            self.recording_preset_name.set("")
            self.refresh_recording_presets()

    def open_recording_rules(self):
        """Edit multi-image start (AND) and discard rules in a small popup."""
        from tkinter import filedialog

        dialog = tk.Toplevel(self.root)
        dialog.title("Recording image rules")
        dialog.transient(self.root)
        trigger_rows = [
            {"path": tk.StringVar(value=item.get("path", "")), "threshold": tk.DoubleVar(value=item.get("threshold", 0.9))}
            for item in self.record_trigger_rules
        ] or [{"path": tk.StringVar(value=self.record_template_path.get()), "threshold": tk.DoubleVar(value=self.record_threshold.get())}]
        cleanup_rows = [
            {"path": tk.StringVar(value=item.get("path", "")), "threshold": tk.DoubleVar(value=item.get("threshold", 0.9)),
             "minimum_percent": tk.DoubleVar(value=item.get("minimum_percent", 100.0))}
            for item in self.record_cleanup_rules
        ]
        trigger_frame = ttk.Labelframe(dialog, text="Start images — ALL images must match (AND)")
        cleanup_frame = ttk.Labelframe(dialog, text="Discard a completed recording when an image is present")
        trigger_frame.grid(column=0, row=0, padx=8, pady=6, sticky="ew")
        cleanup_frame.grid(column=0, row=1, padx=8, pady=6, sticky="ew")

        def pick(target):
            path = filedialog.askopenfilename(title="Choose image", filetypes=[("Image", "*.png;*.jpg;*.jpeg;*.bmp")])
            if path:
                target.set(path)

        def render_trigger():
            for child in trigger_frame.winfo_children():
                child.destroy()
            ttk.Label(trigger_frame, text="Image").grid(column=0, row=0, padx=3)
            ttk.Label(trigger_frame, text="Threshold").grid(column=3, row=0, padx=3)
            for row, item in enumerate(trigger_rows, 1):
                ttk.Entry(trigger_frame, textvariable=item["path"], width=52).grid(column=0, row=row, padx=3, pady=2)
                ttk.Button(trigger_frame, text="...", width=3, command=lambda value=item["path"]: pick(value)).grid(column=1, row=row)
                ttk.Spinbox(trigger_frame, from_=0.1, to=1.0, increment=0.05, textvariable=item["threshold"], width=6).grid(column=3, row=row)
                ttk.Button(trigger_frame, text="-", width=3, command=lambda index=row - 1: (trigger_rows.pop(index), render_trigger())).grid(column=4, row=row)
            ttk.Button(trigger_frame, text="+ Add start image", command=lambda: (trigger_rows.append({"path": tk.StringVar(), "threshold": tk.DoubleVar(value=0.9)}), render_trigger())).grid(column=0, row=len(trigger_rows) + 1, padx=3, pady=3, sticky="w")

        def render_cleanup():
            for child in cleanup_frame.winfo_children():
                child.destroy()
            ttk.Label(cleanup_frame, text="Image").grid(column=0, row=0, padx=3)
            ttk.Label(cleanup_frame, text="Match threshold").grid(column=3, row=0, padx=3)
            ttk.Label(cleanup_frame, text="Discard if present >= %").grid(column=4, row=0, padx=3)
            for row, item in enumerate(cleanup_rows, 1):
                ttk.Entry(cleanup_frame, textvariable=item["path"], width=52).grid(column=0, row=row, padx=3, pady=2)
                ttk.Button(cleanup_frame, text="...", width=3, command=lambda value=item["path"]: pick(value)).grid(column=1, row=row)
                ttk.Spinbox(cleanup_frame, from_=0.1, to=1.0, increment=0.05, textvariable=item["threshold"], width=6).grid(column=3, row=row)
                ttk.Spinbox(cleanup_frame, from_=0, to=100, increment=1, textvariable=item["minimum_percent"], width=6).grid(column=4, row=row)
                ttk.Button(cleanup_frame, text="-", width=3, command=lambda index=row - 1: (cleanup_rows.pop(index), render_cleanup())).grid(column=5, row=row)
            ttk.Button(cleanup_frame, text="+ Add discard image", command=lambda: (cleanup_rows.append({"path": tk.StringVar(), "threshold": tk.DoubleVar(value=0.9), "minimum_percent": tk.DoubleVar(value=100.0)}), render_cleanup())).grid(column=0, row=len(cleanup_rows) + 1, padx=3, pady=3, sticky="w")

        def save_rules():
            self.record_trigger_rules = [{"path": item["path"].get(), "threshold": item["threshold"].get()} for item in trigger_rows if item["path"].get()]
            self.record_cleanup_rules = [
                {"path": item["path"].get(), "threshold": item["threshold"].get(), "minimum_percent": item["minimum_percent"].get()}
                for item in cleanup_rows if item["path"].get()
            ]
            self.configure_recording_rules()
            dialog.destroy()

        render_trigger()
        render_cleanup()
        ttk.Label(dialog, text="Discard recordings shorter than (s):").grid(column=0, row=2, padx=8, pady=(4, 0), sticky="w")
        ttk.Spinbox(dialog, from_=0, to=3600, increment=1, textvariable=self.record_minimum_duration, width=8).grid(column=0, row=3, padx=8, sticky="w")
        ttk.Button(dialog, text="Save rules", command=save_rules).grid(column=0, row=4, padx=8, pady=8, sticky="e")

    def _recording_roi(self):
        try:
            values = tuple(map(int, self.record_roi.get().split(",")))
            return values if len(values) == 4 else (0, 0, 0, 0)
        except ValueError:
            return 0, 0, 0, 0

    def toggle_record_debug(self, show_limited_warning=True):
        if self.record_debug.get():
            if not self._require_tk_video_overlay(
                    "録画条件のROIデバッグ表示",
                    show_popup=show_limited_warning):
                self.record_debug.set(False)
                self.record_debug_status.set(
                    "Debug: 機能制限版では停止（Cameraタブで通常版へ変更）")
                return
            self.record_debug_status.set("Debug: checking template in the ROI...")
            return
        self.record_debug_status.set("Debug: disabled")
        if hasattr(self, "preview"):
            self.preview.deleteImageRect("RecordingDebugROI")
            self.preview.deleteImageText("RecordingDebugText")

    def update_recording_debug(self, frame):
        """Show the template search area and the most recent match result."""
        if not self.record_debug.get():
            return
        x, y, width, height = self.recorder.last_roi
        if width <= 0 or height <= 0:
            height, width = frame.shape[:2]
            x, y = 0, 0
        score = self.recorder.last_score
        threshold = self.record_threshold.get()
        if score is None:
            text = "ROI: {}  score: n/a (template is larger than ROI or unavailable)".format((x, y, width, height))
            color = "orange"
        else:
            matched = score >= threshold
            text = "ROI: {}  score: {:.3f} / threshold: {:.3f}  {}".format(
                (x, y, width, height), score, threshold, "MATCH" if matched else "NO MATCH"
            )
            color = "lime" if matched else "red"
        self.record_debug_status.set("Debug: " + text)
        self.preview.deleteImageRect("RecordingDebugROI")
        self.preview.deleteImageText("RecordingDebugText")
        self.preview.ImgRect(x, y, x + width, y + height, color, "RecordingDebugROI", 0, flag=False)
        self.preview.ImgText(x, max(18, y + 20), text, "RecordingDebugText", 0, color=color, flag=False)

    def _poll_recording_ui_state(self):
        """Keep the Recording tab and quick button explicit about live state."""
        try:
            if (hasattr(self, "_command_monitor_chunks")
                    and self._flush_command_monitor_deletes()):
                self._refresh_command_monitor_tree()
            if self.recorder.active:
                state = "recording"
                button_text = "● 録画中（停止）"
                status_text = ("● Commands監視録画中：映像とStep履歴を書き込み中です"
                               if self.record_mode.get() == "CommandMonitor" else
                               "● 録画中：映像を書き込み中です")
                color = "#c62828"
            elif self.record_armed:
                state = "armed"
                button_text = "● Commands監視中（停止）" \
                    if self.record_mode.get() == "CommandMonitor" else "● 監視中（停止）"
                status_text = ("● Commands開始待ち：開始後にStep自動録画を始めます"
                               if self.record_mode.get() == "CommandMonitor" else
                               "● 録画条件を監視中：条件成立で録画を開始します")
                color = "#b26a00"
            elif self.recorder.is_finalizing:
                state = "finalizing"
                button_text = "○ 録画開始"
                status_text = "◐ 録画停止中：MP4を保存処理中です"
                color = "#1565c0"
            else:
                state = "idle"
                button_text = ("○ Step自動録画を監視開始"
                               if self.record_mode.get() == "CommandMonitor" else
                               "○ 録画開始")
                status_text = ("○ Commands監視停止中"
                               if self.record_mode.get() == "CommandMonitor" else
                               "○ 録画停止中")
                color = "#555555"
            if state != self._recording_ui_state:
                self._recording_ui_state = state
                self.record_button_text.set(button_text)
                self.recording_state_text.set(status_text)
                self.recording_state_label.configure(fg=color)
        except (AttributeError, tk.TclError):
            return
        try:
            self.root.after(150, self._poll_recording_ui_state)
        except tk.TclError:
            pass

    def toggle_recording(self):
        operation = getattr(self, "operation_capture_session", None)
        operation_finalizing = (self._operation_finalize_thread is not None
                                and self._operation_finalize_thread.is_alive())
        if (operation is not None
                or (getattr(self, "operation_recorder", None) is not None
                    and self.operation_recorder.active)
                or operation_finalizing):
            tkmsg.showinfo(
                "Recording",
                "［操作記録→Commands］は通常Recordingと別管理です。\n"
                "操作セッションを完了してから通常録画を開始してください。",
                parent=self.root)
            return
        if (not getattr(self.recorder, "active", False)
                and not self.record_armed and self.record_debug.get()
                and not self._require_tk_video_overlay(
                    "録画条件のROIデバッグ表示")):
            return
        self.configure_recording_rules()
        if self.record_mode.get() == "CommandMonitor":
            if self.record_armed:
                self.record_armed = False
                if self._command_monitor_current_chunk is not None:
                    self._finish_command_monitor_chunk("monitoring_stopped")
                self.record_monitor_status.set(
                    "監視を停止しました。一時録画は確認または次回整理まで保持します。")
                self._refresh_command_monitor_tree()
                return
            self._arm_command_monitor_recording(show_popup=True)
            return
        if self.record_mode.get() == "Variable":
            if self.record_armed:
                self.record_armed = False
                if self.recorder.active:
                    self._stop_capture_recorder()
                self.record_button.configure(text="Start recording")
                self.record_variable_status.set("Variable segments: stopped")
                return
            legacy_complete = (self.record_variable_command.get() and self.record_variable_name.get().strip()
                               and self.record_variable_start.get().strip() and self.record_variable_stop.get().strip())
            if not self.record_variable_rules and not legacy_complete:
                tkmsg.showwarning("Recording", "Select a command and enter variable, start value, and stop value.")
                return
            if not self.record_variable_rules:
                self.record_variable_rules = [{
                    "id": "legacy", "command": self.record_variable_command.get(),
                    "variable": self.record_variable_name.get().strip(),
                    "start_value": self.record_variable_start.get(), "start_seconds": 0.0,
                    "stop_value": self.record_variable_stop.get(), "stop_seconds": 0.0,
                }]
            if not self._recording_disk_space_ok(show_popup=True, force=True):
                return
            if not self._confirm_selected_audio_for_use():
                return
            self.record_armed = True
            self._record_variable_evaluator.reset()
            self._record_variable_active_rule_id = None
            self._record_variable_last_check = 0.0
            self.record_button.configure(text="Stop monitoring")
            self.record_variable_status.set("Armed: {}個の開始条件をOR監視".format(len(self.record_variable_rules)))
            return
        if self.record_mode.get() == "Template":
            if self.record_armed:
                self.record_armed = False
                if self.recorder.active:
                    self._stop_capture_recorder()
                self.record_button.configure(text="Start recording")
                return
            if not self.record_trigger_rules and not self.record_template_path.get():
                tkmsg.showwarning("Recording", "Choose a template image before arming template recording.")
                return
            if not self.record_trigger_rules:
                self.recorder.configure_template(self.record_template_path.get())
            expected_rules = len(self.record_trigger_rules) if self.record_trigger_rules else 1
            configured_rules = len(self.recorder.trigger_rules) if self.record_trigger_rules else (1 if self.recorder.template is not None else 0)
            if configured_rules != expected_rules:
                tkmsg.showwarning("Recording", "The template image could not be read.")
                return
            if not self._recording_disk_space_ok(show_popup=True, force=True):
                return
            if not self._confirm_selected_audio_for_use():
                return
            self.record_armed = True
            self.recorder.last_check = 0.0
            self.record_button.configure(text="Stop monitoring")
            self.show_output("Analysis", text="Template recording armed: waiting for score >= threshold.")
            return
        if self.recorder.active:
            self._stop_capture_recorder()
            self._sync_audio_device_usage()
            self.record_button.configure(text="Start recording")
            self.show_output("Analysis", text="録画を停止しました。MP4はバックグラウンドで結合中です。")
            return
        frame = getattr(self.camera, "image_bgr", None)
        if frame is None:
            tkmsg.showwarning("Recording", "カメラ映像を開始してから録画してください。")
            return
        if not self._recording_disk_space_ok(show_popup=True, force=True):
            return
        if not self._confirm_selected_audio_for_use():
            return
        self._start_capture_recorder(
            frame, self.fps.get(), self._selected_audio_device_name(),
            self.audio_gain.get(),
            audio_level_options=self._audio_level_options())
        self._sync_audio_device_usage()
        self.record_button.configure(text="Stop recording")

    def open_recording_output_layout(self):
        if self._record_output_dialog is not None:
            try:
                if self._record_output_dialog.winfo_exists():
                    self._record_output_dialog.lift()
                    self._record_output_dialog.focus_set()
                    return
            except tk.TclError:
                pass
        dialog = tk.Toplevel(self.root)
        self._record_output_dialog = dialog
        dialog.title("Recording output layout")
        dialog.transient(self.root)
        dialog.resizable(False, False)
        dialog.protocol("WM_DELETE_WINDOW", self._close_recording_output_layout)
        ttk.Radiobutton(dialog, text="Video only (existing recording sets)", value="Video only", variable=self.record_output_mode).grid(column=0, columnspan=2, row=0, padx=8, pady=5, sticky="w")
        ttk.Radiobutton(dialog, text="Video + log panel", value="Video + logs", variable=self.record_output_mode).grid(column=0, columnspan=2, row=1, padx=8, pady=3, sticky="w")
        ttk.Label(dialog, text="Log panel:").grid(column=0, row=2, padx=8, pady=4, sticky="w")
        ttk.Combobox(
            dialog, state="readonly", width=28, textvariable=self.record_output_logs,
            values=("Output#1", "Output#2", "Output#3", "Output#4",
                    "Output#1 + Output#2", "Output#3 + Output#4", "All outputs"),
        ).grid(column=1, row=2, padx=8, pady=4, sticky="w")
        ttk.Checkbutton(dialog, text="Include detection boxes / scores", variable=self.record_output_detection).grid(column=0, columnspan=2, row=3, padx=8, pady=3, sticky="w")
        ttk.Checkbutton(dialog, text="Include Show Guide state", variable=self.record_output_guide).grid(column=0, columnspan=2, row=4, padx=8, pady=3, sticky="w")
        ttk.Checkbutton(dialog, text="Include Show Value state", variable=self.record_output_value).grid(column=0, columnspan=2, row=5, padx=8, pady=3, sticky="w")
        ttk.Label(dialog, text="Only the latest log lines are cached; opening this window does not scan the full log.").grid(
            column=0, columnspan=2, row=6, padx=8, pady=(4, 0), sticky="w")
        ttk.Button(dialog, text="Close", command=self._close_recording_output_layout).grid(column=1, row=7, padx=8, pady=8, sticky="e")

    def _close_recording_output_layout(self):
        dialog = self._record_output_dialog
        self._record_output_dialog = None
        if dialog is not None:
            try:
                dialog.destroy()
            except tk.TclError:
                pass

    def _record_output_area(self, output):
        logical_value = "Log: " + output
        slot = next((name for name, value in self.panel_slots.items()
                     if value.get() == logical_value), None)
        if slot is None:
            slot = {"Output#1": "right_top", "Output#2": "right_bottom",
                    "Output#3": "left_top", "Output#4": "left_bottom"}.get(output)
        return self.panel_widgets[slot][2] if slot in self.panel_widgets else None

    def _selected_record_outputs(self):
        selected = self.record_output_logs.get()
        if selected == "All outputs":
            return ("Output#1", "Output#2", "Output#3", "Output#4")
        return tuple(name for name in ("Output#1", "Output#2", "Output#3", "Output#4")
                     if name in selected)

    def _record_log_sections(self, line_limit=48):
        """Read bounded Text tails, omitting selected outputs with no text."""
        now = time.monotonic()
        outputs = self._selected_record_outputs()
        cache_key = (outputs, int(line_limit))
        if self._record_log_cache_key == cache_key and now - self._record_log_cache_at < 0.25:
            return [(name, list(lines)) for name, lines in self._record_log_cache_sections]
        sections = []
        for output in outputs:
            area = self._record_output_area(output)
            if area is None:
                continue
            try:
                # Unlike get('1.0', ...), this remains constant-time when a
                # long-running command has accumulated a very large log.
                tail = area.get("end-{}l".format(int(line_limit) + 1), "end-1c")
            except tk.TclError:
                tail = ""
            lines = tail.splitlines()[-int(line_limit):]
            if any(line.strip() for line in lines):
                sections.append((output, lines))
        self._record_log_cache_key = cache_key
        self._record_log_cache_sections = [(name, list(lines)) for name, lines in sections]
        self._record_log_cache_lines = [line for name, lines in sections
                                        for line in (["[{}]".format(name)] + lines)]
        self._record_log_cache_at = now
        return [(name, list(lines)) for name, lines in sections]

    def _record_log_lines(self, line_limit=48):
        """Compatibility flattened view of the bounded recording logs."""
        sections = self._record_log_sections(line_limit)
        return [line for name, lines in sections
                for line in (["[{}]".format(name)] + lines)]

    def receive_image_detection_event(self, detail):
        """Receive one portable image-detection result without touching Tk."""
        if not isinstance(detail, dict):
            return
        position = detail.get("position")
        size = detail.get("template_size")
        rect = None
        if position and size and len(position) == 2 and len(size) == 2:
            rect = (int(position[0]), int(position[1]), int(size[0]), int(size[1]))
        event = {
            "name": str(detail.get("name", "image detection")),
            "score": detail.get("score"),
            "threshold": detail.get("threshold", 0.0),
            "matched": bool(detail.get("matched")),
            "show_value": bool(detail.get("show_value", False)),
            "source": "Commands",
            "position": detail.get("position"),
            "template_size": detail.get("template_size"),
            "variant": detail.get("variant"),
            "rect": rect,
            "timestamp": float(detail.get("timestamp", time.time())),
        }
        with self._record_detection_events_lock:
            self._record_detection_events[event["name"]] = event
            # A command containing many generated names must not grow this
            # evidence cache without bound.
            if len(self._record_detection_events) > 64:
                oldest = min(self._record_detection_events,
                             key=lambda key: self._record_detection_events[key]["timestamp"])
                del self._record_detection_events[oldest]
        if event["show_value"] or Command.isSimilarity:
            with self._pending_image_detection_value_lock:
                key = (event["name"], str(event.get("variant") or ""))
                self._pending_image_detection_values[key] = dict(event)
                # Commands may call many detections per cycle.  Coalesce each
                # name independently but keep the worker-to-Tk queue bounded.
                while len(self._pending_image_detection_values) > 32:
                    del self._pending_image_detection_values[
                        next(iter(self._pending_image_detection_values))]
                if not self._pending_image_detection_value_queued:
                    self._pending_image_detection_value_queued = True
                    self._gui_action_queue.put(self._drain_image_detection_value)

    def _drain_image_detection_value(self):
        with self._pending_image_detection_value_lock:
            details = list(self._pending_image_detection_values.values())
            self._pending_image_detection_values = {}
            self._pending_image_detection_value_queued = False
        accepted = False
        for detail in details:
            accepted = self._show_image_detection_value(detail, refresh=False) or accepted
        if accepted:
            self._refresh_image_detection_value_output(force=True)

    def _show_image_detection_value(self, detail, refresh=True):
        """Keep the newest value for each image and render active values together."""
        if not isinstance(detail, dict):
            return False
        if not bool(detail.get("show_value")) and not self.is_show_value.get():
            return False
        update_show_value_entries(self._image_detection_value_entries, detail)
        if refresh:
            self._refresh_image_detection_value_output(force=True)
        return True

    def _image_detection_value_timeout_seconds(self):
        try:
            return max(0.5, min(60.0, float(
                self.image_detection_monitor_value_timeout.get())))
        except (TypeError, ValueError, tk.TclError):
            return 5.0

    def _output_panel_text_widget(self, panel):
        """Return the Text widget currently assigned to an output name."""
        logical = "Log: " + str(panel).replace("Log: ", "", 1)
        slot = next((name for name, value in self.panel_slots.items()
                     if value.get() == logical), None)
        if slot is None:
            slot = {"Output#1": "right_top", "Output#2": "right_bottom",
                    "Output#3": "left_top", "Output#4": "left_bottom"}.get(
                        str(panel).replace("Log: ", "", 1), "right_bottom")
        return self.panel_widgets[slot][2]

    def _output_panel_current_text(self, panel):
        """Read the assigned output text so stale cleanup never erases newer tools."""
        try:
            return self._output_panel_text_widget(panel).get("1.0", "end-1c")
        except (KeyError, tk.TclError):
            return ""

    def _color_matched_image_detection_values(self, output, blocks):
        """Highlight matched ShowValue blocks without changing other logs."""
        text_area = None
        restore_disabled = False
        try:
            text_area = self._output_panel_text_widget(output)
            restore_disabled = str(text_area.cget("state")) == "disabled"
            text_area.configure(state="normal")
            tag = "show_value_matched"
            text_area.tag_remove(tag, "1.0", "end")
            text_area.tag_configure(
                tag, foreground="#087f23", background="#e8f5e9")
            for start, end in matched_show_value_spans(blocks):
                text_area.tag_add(
                    tag, "1.0+{}c".format(start), "1.0+{}c".format(end))
        except (KeyError, tk.TclError):
            pass
        finally:
            if restore_disabled and text_area is not None:
                try:
                    text_area.configure(state="disabled")
                except tk.TclError:
                    pass

    def _refresh_image_detection_value_output(self, force=False):
        now = time.time()
        if not force and now < self._image_detection_value_next_prune:
            return
        self._image_detection_value_next_prune = now + 0.25
        removed = prune_show_value_entries(
            self._image_detection_value_entries,
            self._image_detection_value_timeout_seconds(), now=now)
        if not force and not removed:
            return
        output = self.image_detection_monitor_output.get()
        blocks = format_show_value_blocks(
            self._image_detection_value_entries,
            self.image_detection_monitor_output_tag.get().strip() or "ShowValue")
        text = "\n\n".join(block for block, _matched in blocks)
        previous_output = self._image_detection_value_rendered_output
        previous_text = self._image_detection_value_rendered_text
        if output == "Disabled":
            # Clear only text still owned by this ShowValue renderer.
            if previous_output and previous_text and \
                    self._output_panel_current_text(previous_output) == previous_text:
                self.show_output(previous_output, text="")
            self._image_detection_value_rendered_output = None
            self._image_detection_value_rendered_text = ""
            return
        if previous_output and previous_output != output and previous_text and \
                self._output_panel_current_text(previous_output) == previous_text:
            self.show_output(previous_output, text="")
        if text:
            self.show_output(output, text=text)
            self._color_matched_image_detection_values(output, blocks)
            self._image_detection_value_rendered_output = output
            self._image_detection_value_rendered_text = text
        else:
            if previous_output == output and previous_text and \
                    self._output_panel_current_text(output) == previous_text:
                self.show_output(output, text="")
            self._image_detection_value_rendered_output = None
            self._image_detection_value_rendered_text = ""

    def _recent_image_detection_events(self, seconds=3.0):
        cutoff = time.time() - float(seconds)
        with self._record_detection_events_lock:
            stale = [name for name, detail in self._record_detection_events.items()
                     if detail.get("timestamp", 0.0) < cutoff]
            for name in stale:
                del self._record_detection_events[name]
            return [dict(detail) for detail in self._record_detection_events.values()]

    def _draw_record_detection_overlay(self, frame, details=None, enabled=None):
        if enabled is None:
            enabled = self.record_output_detection.get()
        if not enabled:
            return frame
        if details is None:
            details = list(getattr(self.recorder, "last_detection_details", ()))
            details.extend(self._recent_image_detection_events())
        if not details:
            return frame
        result = frame.copy()
        height, width = result.shape[:2]
        for index, detail in enumerate(details):
            matched = bool(detail.get("matched"))
            color = (60, 220, 70) if matched else (40, 80, 245)
            rect = detail.get("rect")
            if rect:
                x, y, box_width, box_height = (int(value) for value in rect)
                x = min(max(0, x), max(0, width - 1))
                y = min(max(0, y), max(0, height - 1))
                x2 = min(width - 1, x + max(1, box_width))
                y2 = min(height - 1, y + max(1, box_height))
                cv2.rectangle(result, (x, y), (x2, y2), color, 2, cv2.LINE_AA)
                text_y = max(18, y - 6)
            else:
                text_y = 22 + index * 22
                x = 8
            score = detail.get("score")
            score_text = "n/a" if score is None else "{:.3f}".format(float(score))
            label = "{}  score {} / threshold {:.3f}  {}".format(
                detail.get("name", "template"), score_text,
                float(detail.get("threshold", 0.0)),
                "MATCH" if matched else "NO MATCH",
            )
            cv2.putText(result, label[:120], (x, text_y), cv2.FONT_HERSHEY_SIMPLEX,
                        0.48, (0, 0, 0), 3, cv2.LINE_AA)
            cv2.putText(result, label[:120], (x, text_y), cv2.FONT_HERSHEY_SIMPLEX,
                        0.48, color, 1, cv2.LINE_AA)
        return result

    def _recording_overlay_font(self):
        if self._record_overlay_font is not None:
            return self._record_overlay_font
        for path in (r"C:\Windows\Fonts\meiryo.ttc", r"C:\Windows\Fonts\msgothic.ttc"):
            try:
                self._record_overlay_font = ImageFont.truetype(path, 14)
                break
            except OSError:
                continue
        if self._record_overlay_font is None:
            self._record_overlay_font = ImageFont.load_default()
        return self._record_overlay_font

    def _recording_output_snapshot(self, frame_height):
        mode = self.record_output_mode.get()
        if mode == "Video only":
            return {"mode": mode}
        sections = self._record_log_sections(48)
        status_lines = []
        if self.record_output_guide.get() and self.is_show_guide.get():
            status_lines.append("ガイド表示: ON")
        if self.record_output_value.get() and self.is_show_value.get():
            status_lines.append("値表示: ON")
        details = []
        detection_enabled = self.record_output_detection.get()
        if detection_enabled:
            details = [dict(item) for item in getattr(self.recorder, "last_detection_details", ())]
            details.extend(self._recent_image_detection_events())
        return {
            "mode": mode,
            "sections": tuple((name, tuple(lines)) for name, lines in sections),
            "status_lines": tuple(status_lines),
            "detection_enabled": detection_enabled,
            "details": tuple(details),
        }

    @staticmethod
    def _format_record_log_line(line):
        text = str(line).strip()
        if "::" not in text:
            return text, ""
        label, value = (part.strip() for part in text.split("::", 1))
        if label == "BATTLE_COUNT":
            label += " (回数)"
        if label.endswith("_CHECK") and value in ("0", "1"):
            value += " (成立)" if value == "1" else " (未成立)"
        return label + ":", value

    @staticmethod
    def _record_text_width(draw, text, font):
        try:
            box = draw.textbbox((0, 0), text, font=font)
            return box[2] - box[0]
        except AttributeError:
            return draw.textsize(text, font=font)[0]

    def _wrap_record_text(self, draw, text, font, max_width, continuation=""):
        text = str(text)
        if not text:
            return [""]
        rows = []
        remaining = text
        prefix = ""
        while remaining:
            candidate = prefix + remaining
            if self._record_text_width(draw, candidate, font) <= max_width:
                rows.append(candidate)
                break
            low, high = 1, len(remaining)
            while low < high:
                middle = (low + high + 1) // 2
                if self._record_text_width(draw, prefix + remaining[:middle], font) <= max_width:
                    low = middle
                else:
                    high = middle - 1
            cut = max(1, low)
            # Prefer a readable separator near the measured boundary.
            separator = max(remaining.rfind(" ", 0, cut), remaining.rfind("_", 0, cut))
            if separator >= max(1, cut // 2):
                cut = separator + (1 if remaining[separator] == "_" else 0)
            rows.append(prefix + remaining[:cut].rstrip())
            remaining = remaining[cut:].lstrip()
            prefix = continuation
        return rows

    def _record_visual_rows(self, draw, lines, font, max_width):
        rows = []
        for line in lines:
            label, value = self._format_record_log_line(line)
            if value:
                combined = "{} {}".format(label, value)
                if self._record_text_width(draw, combined, font) <= max_width:
                    rows.append(combined)
                else:
                    rows.extend(self._wrap_record_text(draw, label, font, max_width))
                    rows.extend(self._wrap_record_text(
                        draw, "→ " + value, font, max_width, continuation="  "))
            else:
                rows.extend(self._wrap_record_text(draw, label, font, max_width, continuation="  "))
        return rows

    def _render_record_log_panel(self, panel_width, height, snapshot):
        panel_image = Image.new("RGB", (panel_width, height), (32, 32, 32))
        draw = ImageDraw.Draw(panel_image)
        font = self._recording_overlay_font()
        line_height = 16
        y = 7
        for status in snapshot.get("status_lines", ()):
            draw.text((9, y), status, font=font, fill=(150, 220, 255))
            y += line_height
        sections = list(snapshot.get("sections", ()))
        if not sections:
            draw.text((9, y), "選択したOutputにログはありません", font=font, fill=(190, 190, 190))
            return cv2.cvtColor(np.asarray(panel_image), cv2.COLOR_RGB2BGR)
        section_height = max(line_height * 3, (height - y) // len(sections))
        max_width = max(40, panel_width - 18)
        for section_index, (name, source_lines) in enumerate(sections):
            section_bottom = height if section_index == len(sections) - 1 else min(height, y + section_height)
            draw.text((9, y), "[{}]".format(name), font=font, fill=(255, 215, 120))
            y += line_height
            visual_rows = self._record_visual_rows(draw, source_lines, font, max_width)
            capacity = max(1, (section_bottom - y) // line_height)
            clipped = len(visual_rows) > capacity
            if clipped:
                visual_rows = visual_rows[:max(1, capacity - 1)] + ["… 続きあり"]
            for row in visual_rows:
                if y + line_height > section_bottom:
                    break
                draw.text((9, y), row, font=font, fill=(235, 235, 235))
                y += line_height
            y = section_bottom
        return cv2.cvtColor(np.asarray(panel_image), cv2.COLOR_RGB2BGR)

    def _compose_recording_frame(self, frame, snapshot):
        if snapshot.get("mode") == "Video only":
            return frame
        video = self._draw_record_detection_overlay(
            frame, details=snapshot.get("details", ()),
            enabled=snapshot.get("detection_enabled", False))
        height, width = video.shape[:2]
        panel_width = min(560, max(260, int(width * 0.40)))
        video_width = max(1, width - panel_width)
        canvas = np.full((height, width, 3), 32, dtype=np.uint8)
        canvas[:, :video_width] = cv2.resize(video, (video_width, height), interpolation=cv2.INTER_AREA)
        panel_key = (panel_width, height, snapshot.get("sections", ()), snapshot.get("status_lines", ()))
        if self._record_panel_cache_key != panel_key:
            self._record_panel_cache_key = panel_key
            self._record_panel_cache = self._render_record_log_panel(panel_width, height, snapshot)
        canvas[:, video_width:] = self._record_panel_cache
        return canvas

    def recording_output_frame(self, frame):
        """Synchronous compatibility helper; live recording uses the worker."""
        return self._compose_recording_frame(frame, self._recording_output_snapshot(frame.shape[0]))

    def _queue_recording_frame(self, frame, presented_at=None,
                               presentation_mode=None):
        if frame is None or not self.recorder.active:
            return
        if presented_at is None:
            # Capture callbacks continue to drive triggers and cache the Tk
            # overlay state. The recorded picture itself follows the frame
            # that PokeCon actually presented, so audio/video share the same
            # user-observed timeline.
            snapshot = self._recording_output_snapshot(frame.shape[0])
            with self._record_compose_lock:
                self._recording_latest_snapshot = snapshot
            now = time.monotonic()
            if self._recording_last_presentation_at > 0.0 \
                    and now - self._recording_last_presentation_at < 0.5:
                return
            presented_at = now
            presentation_mode = "capture_fallback"
        else:
            with self._record_compose_lock:
                snapshot = self._recording_latest_snapshot
            if snapshot is None:
                snapshot = {"mode": "Video only"}
        session = getattr(self.recorder, "session_dir", None)
        mode = str(snapshot.get("mode", "Video only"))
        if mode == "Video only":
            # The camera publishes immutable frame objects.  Video-only output
            # needs no compositor, so hand the displayed frame straight to the
            # recorder's ordered queue without blocking the 60-Hz draw thread.
            with self._record_compose_condition:
                stopping = session in self._record_compose_closing_sessions
            if not stopping:
                self.recorder.add_frame(
                    frame, presented_at=presented_at,
                    presentation_mode=presentation_mode)
            return
        with self._record_compose_condition:
            if session in self._record_compose_closing_sessions:
                return
            self._record_compose_queue.append((
                frame, snapshot, session, float(presented_at),
                str(presentation_mode or "preview_presented")))
            self._record_compose_queue_max_depth = max(
                self._record_compose_queue_max_depth,
                len(self._record_compose_queue))
            self.recorder.video_compositor_queue_max_depth = max(
                getattr(self.recorder,
                        "video_compositor_queue_max_depth", 0),
                self._record_compose_queue_max_depth)
            self._record_compose_condition.notify()

    def process_presented_recording_frame(
            self, frame, _frame_sequence, presented_at):
        """Feed recording from the image the user actually saw."""
        if frame is None or not self.recorder.active:
            return
        self._recording_last_presentation_at = float(presented_at)
        self._queue_recording_frame(
            frame, presented_at=presented_at,
            presentation_mode="preview_presented")

    def _recording_compose_loop(self):
        while True:
            with self._record_compose_condition:
                while not self._record_compose_queue:
                    self._record_compose_condition.wait()
                pending = self._record_compose_queue.popleft()
                self._record_compose_active_session = pending[2]
            frame, snapshot, session, presented_at, presentation_mode = pending
            try:
                composed = self._compose_recording_frame(frame, snapshot)
                if (self.recorder.active
                        and getattr(self.recorder, "session_dir", None) == session):
                    self.recorder.add_frame(
                        composed, presented_at=presented_at,
                        presentation_mode=presentation_mode)
            except Exception as error:
                self._logger.warning("Recording compositor failed: %s", error)
            finally:
                with self._record_compose_condition:
                    self._record_compose_active_session = None
                    self._record_compose_condition.notify_all()

    def _stop_capture_recorder(self, discard=False):
        """Stop after every already-presented frame reaches the AVI queue."""
        session = getattr(self.recorder, "session_dir", None)
        if session is None or not getattr(self.recorder, "active", False):
            return self.recorder.stop(discard=discard)
        with self._record_compose_condition:
            self._record_compose_closing_sessions.add(session)
            while (self._record_compose_active_session == session
                   or any(item[2] == session
                          for item in self._record_compose_queue)):
                # Do not close the AVI on a partial queue.  Stopping may wait
                # briefly for overlay composition, but displayed frames are
                # never discarded merely because a deadline elapsed.
                self._record_compose_condition.wait()
        try:
            return self.recorder.stop(discard=discard)
        finally:
            with self._record_compose_condition:
                self._record_compose_closing_sessions.discard(session)

    def _start_capture_recorder(self, *args, **kwargs):
        with self._record_compose_condition:
            self._record_compose_queue_max_depth = 0
            self._recording_latest_snapshot = None
            self._recording_last_presentation_at = 0.0
        return self.recorder.start(*args, **kwargs)

    def process_recording_frame(self, frame):
        self._sync_audio_device_usage()
        # Operation authoring is an independent clean-video pipeline.  Feed it
        # before the normal recording mode returns from this callback.
        self._process_operation_capture_frame(frame)
        if (self.recorder.active or self.record_armed) and not self._recording_disk_space_ok(show_popup=True):
            self._interrupt_recording_for_disk_space()
            return
        if self.record_mode.get() == "CommandMonitor":
            self._process_command_monitor_frame(frame)
            return
        if self.record_mode.get() == "Manual":
            if not self.recorder.active:
                return
            # Detection metadata is useful evidence even when detection is not
            # what starts/stops the recording.
            if not self.record_trigger_rules and self.recorder.template_path != self.record_template_path.get():
                self.recorder.configure_template(self.record_template_path.get())
            self.recorder.process_detection(
                frame, self.fps.get(), self._selected_audio_device_name(), self.audio_gain.get(),
                self.record_threshold.get(), self._recording_roi(), self.record_interval.get(),
                self.record_release.get(), allow_start=False,
                audio_level_options=self._audio_level_options(),
            )
            self._queue_recording_frame(frame)
            return
        if self.record_mode.get() == "Variable":
            if not self.record_armed:
                return
            command = getattr(self, "cur_command", None)
            command_name = getattr(command, "NAME", "") if command is not None else ""
            if command is None:
                self.record_variable_status.set("Waiting for a command to run.")
                return
            if not self.record_trigger_rules and self.recorder.template_path != self.record_template_path.get():
                self.recorder.configure_template(self.record_template_path.get())
            self.recorder.process_detection(
                frame, self.fps.get(), self._selected_audio_device_name(), self.audio_gain.get(),
                self.record_threshold.get(), self._recording_roi(), self.record_interval.get(),
                self.record_release.get(), allow_start=False,
                audio_level_options=self._audio_level_options(),
            )
            now = time.monotonic()
            # Camera callbacks may run at 60 FPS; scalar condition checks need
            # only 4 Hz and should never make recording or control sluggish.
            if now - self._record_variable_last_check < 0.25:
                if self.recorder.active:
                    self._queue_recording_frame(frame)
                return
            self._record_variable_last_check = now
            if not self.recorder.active:
                for rule in self.record_variable_rules:
                    start_rule = {"id": str(rule.get("id")) + ":start",
                                  "command": rule.get("command", "すべて"),
                                  "kind": "value_stable", "variable": rule.get("variable", ""),
                                  "value": rule.get("start_value", ""),
                                  "seconds": rule.get("start_seconds", 0.0)}
                    result = self._record_variable_evaluator.evaluate(start_rule, command, command_name, now)
                    if result["triggered"]:
                        if not self._recording_disk_space_ok(show_popup=True, force=True):
                            self._interrupt_recording_for_disk_space()
                            return
                        self._start_capture_recorder(
                            frame, self.fps.get(), self._selected_audio_device_name(),
                            self.audio_gain.get(),
                            audio_level_options=self._audio_level_options())
                        self._record_variable_active_rule_id = str(rule.get("id"))
                        self.record_variable_status.set("Recording: {} == {}".format(
                            rule.get("variable", ""), result.get("value")))
                        break
            if self.recorder.active:
                self._queue_recording_frame(frame)
                active = next((rule for rule in self.record_variable_rules
                               if str(rule.get("id")) == self._record_variable_active_rule_id), None)
                if active is not None:
                    discard_value = active.get("discard_value", "")
                    if discard_value:
                        discard_rule = {"id": str(active.get("id")) + ":discard",
                                        "command": active.get("command", "すべて"),
                                        "kind": "value_stable", "variable": active.get("variable", ""),
                                        "value": discard_value,
                                        "seconds": active.get("discard_seconds", 0.0)}
                        discard_result = self._record_variable_evaluator.evaluate(
                            discard_rule, command, command_name, now)
                        if discard_result["triggered"]:
                            self._stop_capture_recorder(discard=True)
                            self.record_variable_status.set(
                                "Segment discarded: {} == {}. Waiting for next start.".format(
                                    active.get("variable", ""), discard_result.get("value")))
                            self._record_variable_active_rule_id = None
                            self._record_variable_evaluator.reset()
                            return
                    stop_rule = {"id": str(active.get("id")) + ":stop",
                                 "command": active.get("command", "すべて"),
                                 "kind": "value_stable", "variable": active.get("variable", ""),
                                 "value": active.get("stop_value", ""),
                                 "seconds": active.get("stop_seconds", 0.0)}
                    result = self._record_variable_evaluator.evaluate(stop_rule, command, command_name, now)
                    if result["triggered"]:
                        self._stop_capture_recorder()
                        self.record_variable_status.set("Segment completed: {} == {}. Waiting for next start.".format(
                            active.get("variable", ""), result.get("value")))
                        self._record_variable_active_rule_id = None
                        self._record_variable_evaluator.reset()
                        assist_rule_id = str(active.get("assist_rule_id", ""))
                        if assist_rule_id:
                            self._gui_action_queue.put(
                                lambda rule_id=assist_rule_id:
                                self._run_recording_commands_assist(rule_id))
            return
        if not self.record_armed and not self.record_debug.get():
            return
        if not self.record_trigger_rules and self.recorder.template_path != self.record_template_path.get():
            self.recorder.configure_template(self.record_template_path.get())
        result = self.recorder.process_detection(
            frame, self.fps.get(), self._selected_audio_device_name(), self.audio_gain.get(),
            self.record_threshold.get(), self._recording_roi(),
            self.record_interval.get(), self.record_release.get(), allow_start=self.record_armed,
            audio_level_options=self._audio_level_options(),
        )
        self.update_recording_debug(frame)
        # A detected segment must receive every camera frame, not merely the
        # low-frequency frames that are used for template matching.
        if self.recorder.active:
            self._queue_recording_frame(frame)
        if result is not None:
            # Stay armed after one segment finishes so the next matching
            # appearance becomes the next timestamped recording.
            self._gui_action_queue.put(
                lambda: self.record_button.configure(text="Stop monitoring"))
        elif self.recorder.active:
            self._gui_action_queue.put(
                lambda: self.record_button.configure(text="Stop recording"))

    def _run_recording_commands_assist(self, rule_id):
        """Run a linked pause/replacement action after a normal segment end."""
        if self._commands_assist_busy:
            self.commands_assist_status.set("録画終了後の置換処理は、別の置換処理が実行中のため保留されました。")
            return
        rule = next((item for item in self.commands_assist_rules
                     if str(item.get("id", "")) == str(rule_id)), None)
        if rule is None:
            self.commands_assist_status.set("録画条件に紐づくCommandsAssistルールが見つかりません。")
            return
        self._commands_assist_suppressed_rule_id = str(rule.get("id", ""))
        self._begin_commands_assist(rule, {"triggered": True, "source": "recording"})

